/* ============================================================
   NEON FIST · RAGDOLL ARENA
   A dependency-free arcade interface.
   ============================================================ */

:root {
  --ink: #05070f;
  --ink-2: #0a0e1b;
  --panel: rgba(9, 14, 28, 0.82);
  --panel-solid: #0b1020;
  --line: rgba(132, 206, 255, 0.18);
  --line-strong: rgba(132, 206, 255, 0.42);
  --cyan: #39f5ff;
  --cyan-soft: #8ffbff;
  --blue: #2f7dff;
  --blue-deep: #1747c7;
  --magenta: #ff3ea5;
  --red: #ff3b4e;
  --orange: #ff8a2b;
  --gold: #ffd34d;
  --green: #53ff9a;
  --white: #eef7ff;
  --muted: #8aa2c4;
  --display: "Bahnschrift", "DIN Alternate", "Arial Narrow", "Arial Black", "Liberation Sans", system-ui, sans-serif;
  --mono: "JetBrains Mono", "SFMono-Regular", "Cascadia Mono", "Roboto Mono", Consolas, monospace;
  --ease-out: cubic-bezier(.16, 1, .3, 1);
  --ease-snap: cubic-bezier(.2, .9, .1, 1.2);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--white);
  font-family: var(--display);
  -webkit-user-select: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
  touch-action: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  cursor: pointer;
  touch-action: none;
}

button:focus-visible {
  outline: 2px solid var(--cyan);
  outline-offset: 3px;
}

#app {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 100dvh;
  overflow: hidden;
  isolation: isolate;
  background:
    radial-gradient(ellipse at 50% 70%, rgba(20, 48, 95, 0.5), transparent 60%),
    var(--ink);
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  touch-action: none;
}

/* ---------- global cinematic overlays ---------- */
.screen-fx {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 4;
}
.scanlines {
  position: absolute;
  inset: 0;
  opacity: .12;
  background: repeating-linear-gradient(
    to bottom,
    transparent 0px,
    transparent 2px,
    rgba(160, 230, 255, .16) 3px,
    transparent 4px
  );
  mix-blend-mode: overlay;
}
.vignette {
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at 50% 45%, transparent 45%, rgba(0, 3, 10, .52) 100%);
}
.grain {
  position: absolute;
  inset: -50%;
  opacity: .04;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 220 220' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
  animation: grain-shift 0.7s steps(2) infinite;
}
@keyframes grain-shift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-2%, 1%); }
  50% { transform: translate(1%, -2%); }
  75% { transform: translate(2%, 2%); }
  100% { transform: translate(0, 0); }
}

/* ============================================================
   HUD
   ============================================================ */
.hud {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  z-index: 20;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: calc(14px + env(safe-area-inset-top)) clamp(14px, 2.2vw, 34px) 0;
  pointer-events: none;
  transition: opacity .3s ease;
}
.hud.is-dimmed { opacity: .25; }

.fighter-card {
  display: flex;
  align-items: center;
  gap: 13px;
  width: min(410px, 40vw);
  min-width: 285px;
  padding: 10px 16px 12px 12px;
  background: linear-gradient(110deg, rgba(10, 17, 36, .92), rgba(8, 14, 29, .66));
  border: 1px solid var(--line);
  border-left: 2px solid var(--cyan);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%);
  box-shadow: 0 12px 40px rgba(0,0,0,.5), inset 0 1px 0 rgba(255,255,255,.04);
  backdrop-filter: blur(10px);
}

.avatar {
  position: relative;
  flex: 0 0 51px;
  width: 51px;
  height: 51px;
  display: grid;
  place-items: center;
  border: 1px solid rgba(57, 245, 255, .35);
  background: radial-gradient(circle at 50% 40%, rgba(57,245,255,.16), rgba(5,10,22,.95) 70%);
  clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%);
}
.avatar svg {
  width: 32px;
  height: 32px;
  overflow: visible;
  fill: none;
  stroke: var(--cyan);
  stroke-width: 2.4;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 5px rgba(57, 245, 255, .9));
}
.avatar svg circle { fill: rgba(57,245,255,.12); }
.avatar-pulse {
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(57,245,255,.25);
  clip-path: polygon(50% 0, 100% 25%, 100% 75%, 50% 100%, 0 75%, 0 25%);
  animation: avatar-pulse 2.6s ease-out infinite;
}
@keyframes avatar-pulse {
  0%, 65% { opacity: .7; transform: scale(.94); }
  100% { opacity: 0; transform: scale(1.16); }
}

.meters { flex: 1; min-width: 0; }
.meter-label {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin: 0 1px 4px;
  font-family: var(--mono);
  font-size: 9px;
  letter-spacing: .13em;
  color: var(--muted);
}
.fighter-name {
  font-family: var(--display);
  font-size: 15px;
  font-weight: 800;
  letter-spacing: .16em;
  color: var(--white);
  font-stretch: condensed;
}
.fighter-name em { font-style: normal; font-size: 9px; color: var(--cyan); opacity: .8; letter-spacing: .18em; }
.meter-number { color: #cfefff; font-size: 10px; letter-spacing: .04em; }
.meter-label-battery { margin-top: 7px; color: #a7b9d6; }
.meter-label-battery em {
  font-style: normal;
  font-size: 8px;
  color: var(--cyan);
  margin-left: 4px;
  opacity: .8;
}
.meter-label-battery em.ready {
  color: var(--gold);
  animation: battery-blink .8s steps(2) infinite;
}
@keyframes battery-blink { 50% { opacity: .25; } }

.meter {
  position: relative;
  height: 11px;
  overflow: hidden;
  background: rgba(0, 6, 16, .9);
  border: 1px solid rgba(130, 190, 255, .15);
  transform: skewX(-16deg);
}
.meter-hp { height: 13px; }
.meter-fill {
  position: absolute;
  inset: 0;
  transform-origin: left center;
  transition: transform .18s var(--ease-out);
  background: linear-gradient(90deg, #1b5bff, var(--cyan) 62%, #d2ffff);
  box-shadow: 0 0 12px rgba(57,245,255,.55), inset 0 0 6px rgba(255,255,255,.35);
}
.meter-fill::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(255,255,255,.32), transparent 45%, rgba(0,0,0,.2));
}
.meter-fill.low {
  background: linear-gradient(90deg, #ff1f45, #ff7155 70%, #ffd2a8);
  box-shadow: 0 0 12px rgba(255,59,78,.6);
  animation: low-hp 1s ease-in-out infinite;
}
@keyframes low-hp { 50% { filter: brightness(1.45); } }
.meter-ghost {
  position: absolute;
  inset: 0;
  transform-origin: left center;
  background: rgba(255, 235, 235, .55);
  transition: transform .7s ease .3s;
}
.meter-battery .meter-fill {
  background: linear-gradient(90deg, #8a5b00, var(--gold) 55%, #fff6bc);
  box-shadow: 0 0 12px rgba(255, 211, 77, .5);
}
.meter-battery.is-full .meter-fill {
  background: linear-gradient(90deg, var(--cyan), #eaffff);
  box-shadow: 0 0 18px rgba(57,245,255,.85);
  animation: full-battery .75s ease-in-out infinite;
}
@keyframes full-battery { 50% { filter: brightness(1.35); } }
.meter-ticks {
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 calc(20% - 1px), rgba(0, 4, 12, .6) calc(20% - 1px) 20%);
  pointer-events: none;
}
.battery-spark {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 18px;
  left: -30px;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.8), transparent);
  opacity: 0;
}
.meter-battery.is-full .battery-spark {
  opacity: 1;
  animation: battery-sweep 1.8s linear infinite;
}
@keyframes battery-sweep {
  from { left: -20px; }
  to { left: 100%; }
}

.run-stats {
  display: flex;
  align-items: stretch;
  gap: 0;
  margin-top: 1px;
  padding: 8px 3px;
  border-top: 1px solid rgba(57,245,255,.22);
  border-bottom: 1px solid rgba(57,245,255,.08);
  background: linear-gradient(90deg, transparent, rgba(5,10,24,.72), transparent);
}
.stat { display: flex; flex-direction: column; align-items: center; min-width: 94px; padding: 0 16px; }
.stat-label { font-family: var(--mono); font-size: 8px; letter-spacing: .22em; color: var(--muted); }
.stat-value {
  font-family: var(--display);
  font-size: clamp(22px, 2.6vw, 32px);
  line-height: 1;
  font-weight: 900;
  letter-spacing: .05em;
  color: var(--white);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 18px rgba(57,245,255,.35);
}
.stat-divider { width: 1px; margin: 5px 0; background: linear-gradient(transparent, rgba(57,245,255,.4), transparent); }
.stat:last-child .stat-value { color: var(--cyan-soft); }

.hud-actions {
  display: flex;
  gap: 8px;
  pointer-events: auto;
}
.icon-btn {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  background: rgba(7, 12, 25, .72);
  color: #a9c6e8;
  backdrop-filter: blur(8px);
  transition: .2s ease;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%);
}
.icon-btn:hover { color: var(--cyan); border-color: var(--line-strong); background: rgba(12, 26, 48, .9); }
.icon-btn svg { width: 20px; height: 20px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }
.icon-sound-off { display: none; }
body.muted .icon-sound-on { display: none; }
body.muted .icon-sound-off { display: block; }

.combo-display {
  position: absolute;
  right: clamp(14px, 3vw, 54px);
  top: 118px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  opacity: 0;
  transform: translateX(18px) scale(.94);
  transition: .22s var(--ease-out);
  pointer-events: none;
  text-shadow: 0 0 24px rgba(57,245,255,.55);
}
.combo-display.show { opacity: 1; transform: none; }
.combo-count {
  font-family: var(--display);
  font-size: clamp(38px, 5vw, 66px);
  line-height: .78;
  font-weight: 900;
  color: var(--white);
  -webkit-text-stroke: 1px rgba(57,245,255,.5);
}
.combo-word { font-family: var(--mono); font-size: 10px; letter-spacing: .38em; color: var(--cyan); margin-top: 7px; }
.combo-rank { font-family: var(--mono); font-size: 9px; letter-spacing: .2em; color: var(--gold); margin-top: 2px; }
.combo-timer { width: 96px; height: 2px; margin-top: 5px; background: rgba(255,255,255,.12); overflow: hidden; }
.combo-timer i { display: block; height: 100%; width: 100%; transform-origin: right; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }

/* ---------- wave banner ---------- */
.banner {
  position: absolute;
  z-index: 25;
  top: 22%;
  left: 50%;
  width: min(760px, 86vw);
  transform: translate(-50%, -8px);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity .3s ease, transform .5s var(--ease-out);
  filter: drop-shadow(0 0 30px rgba(0,0,0,.8));
}
.banner.show { opacity: 1; transform: translate(-50%, 0); }
.banner-kicker {
  font-family: var(--mono);
  font-size: 11px;
  letter-spacing: .55em;
  color: var(--cyan);
  padding: 5px 14px 5px 18px;
  border-top: 1px solid rgba(57,245,255,.45);
  border-bottom: 1px solid rgba(57,245,255,.22);
  background: linear-gradient(90deg, transparent, rgba(8,20,40,.7), transparent);
}
.banner-title {
  margin-top: 10px;
  font-family: var(--display);
  font-weight: 900;
  font-size: clamp(34px, 6.4vw, 78px);
  line-height: .86;
  letter-spacing: .06em;
  color: var(--white);
  -webkit-text-stroke: 1px rgba(57,245,255,.4);
  text-shadow: 0 0 44px rgba(57,245,255,.26), 5px 5px 0 rgba(0, 40, 90, .5);
}
.banner-sub { margin-top: 8px; font-family: var(--mono); font-size: 10px; letter-spacing: .18em; color: #a8c1df; }
.banner.alert .banner-kicker { color: var(--gold); border-color: rgba(255,211,77,.5); }
.banner.alert .banner-title { color: var(--gold); -webkit-text-stroke-color: rgba(255,211,77,.4); }
.banner.danger .banner-kicker { color: var(--red); border-color: rgba(255,59,78,.5); }
.banner.danger .banner-title { color: #ffe7e7; -webkit-text-stroke-color: rgba(255,59,78,.55); }

/* ---------- context tips ---------- */
.context-tip {
  position: absolute;
  z-index: 24;
  left: 50%;
  bottom: clamp(180px, 27vh, 270px);
  transform: translate(-50%, 8px);
  opacity: 0;
  padding: 7px 16px;
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: .16em;
  color: var(--cyan-soft);
  background: rgba(5, 12, 26, .82);
  border: 1px solid rgba(57,245,255,.32);
  border-left: 2px solid var(--cyan);
  white-space: nowrap;
  transition: .2s ease;
  pointer-events: none;
  box-shadow: 0 0 24px rgba(0,0,0,.45);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%);
}
.context-tip.show { opacity: 1; transform: translate(-50%, 0); }
.context-tip b { color: var(--gold); font-weight: 500; }

/* ============================================================
   TOUCH CONTROLS
   ============================================================ */
.controls {
  position: absolute;
  z-index: 22;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  padding: 0 clamp(16px, 3.2vw, 54px) calc(18px + env(safe-area-inset-bottom));
  pointer-events: none;
  transition: opacity .35s ease, transform .35s ease;
}
.controls.is-hidden { opacity: 0; pointer-events: none; transform: translateY(15px); }

.dpad-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  pointer-events: auto;
}
.dpad {
  position: relative;
  width: clamp(128px, 15vw, 172px);
  height: clamp(128px, 15vw, 172px);
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: repeat(3, 1fr);
  padding: 4px;
  border-radius: 50%;
  background:
    radial-gradient(circle, rgba(16, 31, 58, .5) 0 46%, transparent 47%),
    rgba(5, 10, 22, .25);
  border: 1px solid rgba(120, 190, 255, .09);
  touch-action: none;
}
.dpad::before {
  content: "";
  position: absolute;
  inset: 17%;
  border-radius: 50%;
  border: 1px dashed rgba(57,245,255,.15);
  animation: dpad-spin 14s linear infinite;
  pointer-events: none;
}
@keyframes dpad-spin { to { transform: rotate(360deg); } }
.pad-btn {
  display: grid;
  place-items: center;
  border-radius: 16px;
  color: rgba(175, 220, 255, .82);
  background: linear-gradient(150deg, rgba(23, 44, 78, .48), rgba(5, 11, 24, .44));
  border: 1px solid rgba(118, 185, 255, .16);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.05), 0 7px 18px rgba(0,0,0,.24);
  transition: transform .07s ease, background .1s ease, color .1s ease, box-shadow .1s ease;
  position: relative;
}
.pad-btn::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: radial-gradient(circle at 50% 30%, rgba(57,245,255,.18), transparent 70%);
  opacity: 0;
  transition: opacity .1s;
}
.pad-btn.active, .pad-btn:active {
  color: var(--cyan);
  background: rgba(20, 58, 92, .72);
  box-shadow: inset 0 0 20px rgba(57,245,255,.25), 0 0 24px rgba(57,245,255,.18);
  transform: scale(.94);
}
.pad-btn.active::after, .pad-btn:active::after { opacity: 1; }
.pad-btn svg { width: 27px; height: 27px; fill: none; stroke: currentColor; stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; filter: drop-shadow(0 0 5px rgba(57,245,255,.3)); }
.pad-left { grid-area: 2 / 1; border-radius: 18px 9px 9px 18px; }
.pad-right { grid-area: 2 / 3; border-radius: 9px 18px 18px 9px; }
.pad-down { grid-area: 3 / 2; border-radius: 9px 9px 18px 18px; width: 100%; height: 100%; }
.dpad-hub {
  grid-area: 2 / 2;
  align-self: center;
  justify-self: center;
  width: 26%;
  aspect-ratio: 1;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, rgba(57,245,255,.3), rgba(7,16,32,.9) 65%);
  border: 1px solid rgba(57,245,255,.24);
  box-shadow: 0 0 14px rgba(57,245,255,.15);
}
.control-caption {
  font-family: var(--mono);
  font-size: 7.5px;
  letter-spacing: .26em;
  color: rgba(150, 190, 230, .45);
}

.action-cluster {
  display: flex;
  align-items: flex-end;
  gap: clamp(9px, 1vw, 16px);
  pointer-events: auto;
}
.action-btn {
  position: relative;
  width: clamp(57px, 5.4vw, 72px);
  height: clamp(57px, 5.4vw, 72px);
  border-radius: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1px;
  color: #dff8ff;
  background:
    radial-gradient(circle at 42% 30%, rgba(70, 120, 175, .34), transparent 55%),
    linear-gradient(150deg, rgba(17, 31, 56, .92), rgba(5, 10, 22, .88));
  border: 1px solid rgba(127, 194, 255, .3);
  box-shadow: inset 0 1px 0 rgba(255,255,255,.1), 0 8px 22px rgba(0,0,0,.42), 0 0 0 4px rgba(5,10,20,.28);
  transition: transform .07s ease, box-shadow .1s ease, border-color .1s ease;
  touch-action: none;
}
.action-btn::before {
  content: "";
  position: absolute;
  inset: 4px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.05);
  pointer-events: none;
}
.action-btn.active, .action-btn:active {
  transform: scale(.9);
  border-color: var(--cyan);
  box-shadow: inset 0 0 22px rgba(57,245,255,.25), 0 0 30px rgba(57,245,255,.23), 0 0 0 5px rgba(57,245,255,.06);
}
.action-icon {
  font-family: var(--display);
  font-size: clamp(18px, 1.8vw, 23px);
  line-height: .8;
  font-weight: 900;
  text-shadow: 0 0 10px rgba(57,245,255,.45);
}
.action-label { font-family: var(--mono); font-size: 6.5px; letter-spacing: .1em; color: rgba(200, 227, 255, .68); }
.action-light { border-color: rgba(57,245,255,.45); }
.action-light .action-icon { color: var(--cyan); }
.action-heavy { width: clamp(64px, 6vw, 80px); height: clamp(64px, 6vw, 80px); border-color: rgba(255,211,77,.4); }
.action-heavy .action-icon { color: var(--gold); }
.action-grab { border-color: rgba(255, 62, 165, .35); }
.action-grab .action-icon { color: var(--magenta); }

.action-grid {
  display: grid;
  grid-template-columns: repeat(2, auto);
  grid-template-rows: repeat(2, auto);
  gap: clamp(7px, .8vw, 12px);
  align-items: center;
  justify-items: center;
  padding-bottom: 2px;
}
.action-grid .action-grab { grid-area: 1 / 1; }
.action-grid .action-heavy { grid-area: 1 / 2; }
.action-grid .action-light { grid-area: 2 / 2; }
.action-grid::before {
  content: "";
  grid-area: 2 / 1;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px dashed rgba(127, 194, 255, .15);
}

.action-jump {
  width: clamp(70px, 6.6vw, 88px);
  height: clamp(70px, 6.6vw, 88px);
  border-color: rgba(57,245,255,.34);
  background:
    radial-gradient(circle at 42% 30%, rgba(57,245,255,.2), transparent 55%),
    linear-gradient(150deg, rgba(14, 37, 66, .95), rgba(5, 10, 22, .9));
}
.action-jump .action-icon { font-size: clamp(22px, 2.2vw, 28px); color: var(--cyan-soft); }

.action-special {
  width: clamp(66px, 6.2vw, 84px);
  height: clamp(66px, 6.2vw, 84px);
  border-color: rgba(255,211,77,.3);
  overflow: visible;
}
.action-special .action-icon { color: var(--gold); font-size: clamp(23px, 2.3vw, 30px); }
.action-special .action-label { color: rgba(255, 225, 136, .7); }
.action-special .action-ring {
  position: absolute;
  inset: -3px;
  border-radius: 50%;
  background: conic-gradient(var(--gold) var(--charge, 0deg), rgba(255,255,255,.07) 0);
  -webkit-mask: radial-gradient(circle, transparent 61%, #000 62%);
  mask: radial-gradient(circle, transparent 61%, #000 62%);
  pointer-events: none;
}
.action-special.ready {
  border-color: var(--gold);
  box-shadow: 0 0 28px rgba(255,211,77,.28), inset 0 0 25px rgba(255,211,77,.15), 0 0 0 5px rgba(255,211,77,.05);
  animation: special-ready 1.15s ease-in-out infinite;
}
@keyframes special-ready {
  50% { box-shadow: 0 0 42px rgba(255,211,77,.55), inset 0 0 30px rgba(255,211,77,.24), 0 0 0 7px rgba(255,211,77,.1); }
}
.action-special.locked { opacity: .62; filter: saturate(.4); }
.charge-pip {
  position: absolute;
  bottom: -14px;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .08em;
  color: rgba(255,225,136,.55);
  white-space: nowrap;
}
.action-special.ready .charge-pip { color: var(--gold); }

/* ============================================================
   SCREENS
   ============================================================ */
.screen {
  position: absolute;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: max(24px, env(safe-area-inset-top)) clamp(16px, 4vw, 60px) max(24px, env(safe-area-inset-bottom));
  background: radial-gradient(ellipse at 50% 45%, rgba(4, 10, 24, .35), rgba(2, 5, 12, .9) 80%);
  backdrop-filter: blur(3px);
  transition: opacity .3s ease, visibility .3s ease;
}
.screen.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}
.screen::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(57,245,255,.028) 1px, transparent 1px),
    linear-gradient(90deg, rgba(57,245,255,.028) 1px, transparent 1px);
  background-size: 64px 64px;
  mask-image: radial-gradient(ellipse at center, #000 20%, transparent 78%);
  pointer-events: none;
}

/* ---------- main menu ---------- */
.menu-screen {
  flex-direction: row;
  gap: clamp(26px, 5vw, 78px);
  padding-top: 90px;
  background: linear-gradient(100deg, rgba(2, 6, 17, .88) 0%, rgba(4, 10, 24, .68) 45%, rgba(3, 8, 18, .52) 70%, rgba(2, 5, 12, .7) 100%);
  backdrop-filter: blur(2px);
}
.menu-panel {
  width: min(620px, 55vw);
  display: flex;
  flex-direction: column;
  padding-left: clamp(4px, 2vw, 30px);
  animation: menu-in .7s var(--ease-out) both;
}
@keyframes menu-in {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: none; }
}
.menu-topline {
  display: flex;
  align-items: center;
  gap: 12px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .32em;
  color: rgba(145, 187, 230, .68);
  margin-bottom: 18px;
}
.menu-topline-dot { width: 4px; height: 4px; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }
.logo-lockup { position: relative; }
.logo-kicker {
  display: inline-block;
  font-family: var(--mono);
  font-size: clamp(9px, 1vw, 12px);
  letter-spacing: .58em;
  color: var(--cyan);
  padding-left: 5px;
  margin-bottom: 2px;
}
.logo-lockup h1 {
  margin: 0;
  font-family: var(--display);
  font-stretch: condensed;
  font-weight: 900;
  font-size: clamp(64px, 10.2vw, 142px);
  line-height: .76;
  letter-spacing: -.025em;
  color: transparent;
  background: linear-gradient(180deg, #ffffff 12%, #c6f6ff 48%, #5fd3ff 62%, #147de0 100%);
  -webkit-background-clip: text;
  background-clip: text;
  filter: drop-shadow(0 0 32px rgba(57, 166, 255, .34)) drop-shadow(0 8px 0 rgba(1, 12, 32, .9));
  position: relative;
}
.logo-lockup h1::after {
  content: "";
  position: absolute;
  left: 2%;
  bottom: -.035em;
  width: 78%;
  height: 2px;
  background: linear-gradient(90deg, var(--cyan), rgba(57,245,255,0));
  box-shadow: 0 0 18px rgba(57,245,255,.7);
  opacity: .7;
}
.logo-lockup h1 span {
  color: transparent;
  background: linear-gradient(180deg, #fff4fa, #ff5fb1 55%, #c5006b 100%);
  -webkit-background-clip: text;
  background-clip: text;
  text-shadow: 0 0 40px rgba(255,62,165,.25);
}
.logo-rule {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 11px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .4em;
  color: #8fa9c9;
}
.logo-rule i { height: 1px; width: 34px; background: linear-gradient(90deg, transparent, rgba(57,245,255,.7)); }
.logo-rule i:last-child { transform: scaleX(-1); }
.menu-tagline {
  margin: 20px 0 0;
  max-width: 470px;
  font-family: var(--mono);
  font-size: clamp(10px, .95vw, 12px);
  line-height: 1.75;
  letter-spacing: .045em;
  color: #a1b8d4;
}
.menu-actions { margin-top: 28px; width: min(370px, 100%); }
.btn {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 2px;
  min-height: 52px;
  padding: 13px 28px;
  font-family: var(--display);
  font-weight: 800;
  letter-spacing: .16em;
  text-transform: uppercase;
  overflow: hidden;
  transition: transform .12s ease, box-shadow .2s ease, background .2s ease, border-color .2s ease;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 11px), calc(100% - 11px) 100%, 0 100%);
}
.btn:active { transform: scale(.975); }
.btn-primary {
  min-height: 66px;
  color: #00131e;
  background: linear-gradient(100deg, #5ff7ff, #2dd3ff 45%, #4e8cff);
  border: 1px solid rgba(220, 255, 255, .65);
  box-shadow: 0 0 40px rgba(57, 220, 255, .25), inset 0 1px 0 rgba(255,255,255,.55);
}
.btn-primary .btn-label { font-size: clamp(18px, 1.6vw, 23px); letter-spacing: .2em; line-height: 1; }
.btn-primary .btn-sub { font-family: var(--mono); font-size: 7.5px; letter-spacing: .24em; opacity: .7; }
.btn-primary .btn-shine {
  position: absolute;
  top: -40%;
  bottom: -40%;
  width: 40px;
  left: -60px;
  transform: skewX(-22deg);
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.7), transparent);
  animation: btn-shine 3.4s ease-in-out infinite;
}
@keyframes btn-shine {
  0%, 55% { left: -60px; opacity: 0; }
  62% { opacity: 1; }
  82%, 100% { left: 110%; opacity: 0; }
}
.btn-primary:hover {
  background: linear-gradient(100deg, #a8fdff, #59e8ff 45%, #75abff);
  box-shadow: 0 0 54px rgba(57, 220, 255, .42), inset 0 1px 0 rgba(255,255,255,.6);
}
.menu-secondary { display: flex; gap: 8px; margin-top: 9px; }
.btn-ghost {
  flex: 1;
  min-height: 43px;
  padding: 10px 16px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .16em;
  color: #9db8d8;
  background: rgba(11, 20, 38, .55);
  border: 1px solid rgba(122, 181, 240, .19);
}
.btn-ghost:hover { color: var(--cyan); border-color: rgba(57,245,255,.4); background: rgba(15, 35, 62, .66); }
.btn-quiet {
  min-height: 42px;
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: .16em;
  color: #6f87a5;
  border: 1px solid transparent;
}
.btn-quiet:hover { color: #b9d1ea; }
.menu-footer { margin-top: 24px; }
.feature-pills { display: flex; flex-wrap: wrap; gap: 13px; font-family: var(--mono); font-size: 7.5px; letter-spacing: .14em; color: #7d97b8; }
.feature-pills span { display: flex; align-items: center; gap: 6px; }
.dot { width: 4px; height: 4px; border-radius: 50%; }
.dot.cyan { background: var(--cyan); box-shadow: 0 0 8px var(--cyan); }
.dot.red { background: var(--red); box-shadow: 0 0 8px var(--red); }
.dot.yellow { background: var(--gold); box-shadow: 0 0 8px var(--gold); }
.menu-footer p { margin: 10px 0 0; font-family: var(--mono); font-size: 7px; letter-spacing: .1em; color: rgba(125, 151, 184, .5); }

.menu-side {
  width: min(300px, 27vw);
  display: flex;
  flex-direction: column;
  gap: 10px;
  align-self: center;
  animation: menu-in .8s .12s var(--ease-out) both;
}
.side-card {
  position: relative;
  padding: 17px 19px 16px;
  background: linear-gradient(120deg, rgba(10, 20, 40, .62), rgba(5, 11, 24, .28));
  border: 1px solid rgba(112, 178, 240, .12);
  border-left: 1px solid rgba(57,245,255,.36);
  backdrop-filter: blur(8px);
  transition: border-color .25s, background .25s;
}
.side-card:hover { border-color: rgba(57,245,255,.3); background: linear-gradient(120deg, rgba(12, 28, 54, .72), rgba(5, 11, 24, .4)); }
.side-index { position: absolute; right: 13px; top: 10px; font-family: var(--mono); font-size: 8px; color: rgba(57,245,255,.35); letter-spacing: .08em; }
.side-card h3 { margin: 0 0 7px; font-size: 11px; letter-spacing: .18em; font-weight: 800; color: #d2ecff; }
.side-card p { margin: 0; font-family: var(--mono); font-size: 8.5px; line-height: 1.65; letter-spacing: .02em; color: #7f99b9; }
.menu-version {
  position: absolute;
  right: clamp(16px, 3vw, 42px);
  bottom: calc(20px + env(safe-area-inset-bottom));
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .18em;
  color: rgba(112, 140, 177, .45);
}

/* ---------- sheet / how to play ---------- */
.sheet-screen { background: rgba(2, 6, 14, .86); backdrop-filter: blur(9px); }
.sheet {
  width: min(900px, 94vw);
  max-height: 90dvh;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: clamp(20px, 3vw, 38px);
  background: linear-gradient(145deg, rgba(11, 20, 40, .96), rgba(5, 10, 22, .98));
  border: 1px solid rgba(96, 172, 240, .22);
  box-shadow: 0 40px 100px rgba(0,0,0,.6), inset 0 1px 0 rgba(255,255,255,.05);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 20px), calc(100% - 20px) 100%, 0 100%);
  animation: sheet-in .35s var(--ease-out);
}
@keyframes sheet-in { from { opacity: 0; transform: translateY(12px) scale(.99); } }
.sheet-head { display: flex; justify-content: space-between; align-items: flex-start; padding-bottom: 18px; border-bottom: 1px solid rgba(57,245,255,.14); }
.sheet-kicker { font-family: var(--mono); font-size: 8px; letter-spacing: .35em; color: var(--cyan); }
.sheet-head h2, .pause-panel h2, .gameover-panel h2 { margin: 6px 0 0; font-size: clamp(30px, 4.4vw, 50px); line-height: .9; letter-spacing: .05em; font-weight: 900; }
.sheet-close { width: 38px; height: 38px; border: 1px solid rgba(130,190,255,.2); color: #8da9c9; font-size: 14px; }
.sheet-close:hover { color: var(--cyan); border-color: var(--cyan); }
.sheet-columns { display: grid; grid-template-columns: 1.05fr .95fr; gap: clamp(20px, 3vw, 42px); margin: 22px 0; }
.move-list { display: flex; flex-direction: column; }
.move-row { display: flex; justify-content: space-between; gap: 16px; align-items: baseline; padding: 10px 2px; border-bottom: 1px dashed rgba(120, 170, 220, .12); }
.move-keys { flex: 0 0 auto; font-family: var(--mono); font-size: 9px; letter-spacing: .08em; color: var(--cyan-soft); }
.move-keys i { color: rgba(130,170,210,.35); font-style: normal; }
.move-name { font-family: var(--mono); font-size: 8.5px; letter-spacing: .02em; color: #8ca6c5; text-align: right; }
.tips-list { display: flex; flex-direction: column; gap: 8px; }
.tip-card { padding: 12px 14px; background: rgba(7, 14, 28, .7); border-left: 2px solid var(--cyan); }
.tip-card.red { border-color: var(--red); }
.tip-card.gold { border-color: var(--gold); }
.tip-card.cyan { border-color: var(--cyan); }
.tip-card.dim { border-color: rgba(120, 160, 210, .4); }
.tip-chip { font-family: var(--mono); font-size: 7.5px; letter-spacing: .16em; color: #d5ecff; }
.tip-card p { margin: 5px 0 0; font-family: var(--mono); font-size: 8.5px; line-height: 1.6; color: #809ab9; }
.sheet-cta { width: min(330px, 100%); margin: 4px auto 0; }

/* ---------- pause ---------- */
.pause-screen { background: rgba(2, 6, 14, .72); backdrop-filter: blur(10px); }
.pause-panel {
  width: min(440px, 92vw);
  padding: clamp(24px, 4vw, 40px);
  text-align: center;
  background: linear-gradient(150deg, rgba(11, 21, 42, .96), rgba(5, 10, 22, .98));
  border: 1px solid rgba(96, 172, 240, .22);
  box-shadow: 0 40px 100px rgba(0,0,0,.65);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 18px), calc(100% - 18px) 100%, 0 100%);
}
.pause-stats { display: flex; justify-content: center; gap: 0; margin: 24px 0 26px; border-top: 1px solid rgba(57,245,255,.13); border-bottom: 1px solid rgba(57,245,255,.13); }
.pause-stats div { flex: 1; padding: 13px 8px; }
.pause-stats div + div { border-left: 1px solid rgba(57,245,255,.1); }
.pause-stats span { display: block; font-family: var(--mono); font-size: 7px; letter-spacing: .18em; color: #7f99b9; }
.pause-stats b { display: block; margin-top: 4px; font-size: 23px; font-weight: 900; color: var(--cyan-soft); }
.pause-actions { display: flex; flex-direction: column; gap: 8px; }
.pause-note { margin: 15px 0 0; font-family: var(--mono); font-size: 7.5px; letter-spacing: .15em; color: rgba(125,151,184,.55); }

/* ---------- game over ---------- */
.gameover-screen { background: radial-gradient(ellipse at 50% 40%, rgba(30, 5, 18, .42), rgba(2, 5, 12, .94) 78%); backdrop-filter: blur(5px); }
.gameover-panel {
  width: min(580px, 94vw);
  padding: clamp(24px, 4vw, 42px);
  text-align: center;
  background: linear-gradient(155deg, rgba(15, 17, 38, .97), rgba(6, 8, 18, .98));
  border: 1px solid rgba(255, 64, 120, .25);
  border-top: 2px solid rgba(255, 59, 95, .65);
  box-shadow: 0 50px 120px rgba(0,0,0,.72), 0 0 80px rgba(255, 40, 90, .06);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%);
  animation: sheet-in .4s var(--ease-out);
}
.gameover-kicker { font-family: var(--mono); font-size: 8px; letter-spacing: .35em; color: #ff6c8e; }
.gameover-panel h2 { font-size: clamp(46px, 6.6vw, 78px); color: #fff; text-shadow: 0 0 50px rgba(255,59,78,.3); -webkit-text-stroke: 1px rgba(255,90,120,.3); }
.gameover-copy { max-width: 400px; margin: 10px auto 0; font-family: var(--mono); font-size: 9.5px; line-height: 1.7; color: #9d91ad; }
.go-stats { display: flex; margin: 22px 0; border-top: 1px solid rgba(255,100,140,.15); border-bottom: 1px solid rgba(255,100,140,.15); }
.go-stats div { flex: 1; padding: 12px 5px; }
.go-stats div + div { border-left: 1px solid rgba(255,100,140,.1); }
.go-stats span { display: block; font-family: var(--mono); font-size: 6.5px; letter-spacing: .16em; color: #8b8298; }
.go-stats b { display: block; margin-top: 4px; font-size: clamp(18px, 2.4vw, 24px); color: #ffdce4; }
.gameover-actions { display: flex; gap: 9px; margin-top: 18px; }
.gameover-actions .btn { flex: 1; min-height: 52px; }
.gameover-actions .btn-primary { background: linear-gradient(100deg, #ff5b86, #ff2964 55%, #e0004d); color: #1a0008; border-color: rgba(255,180,200,.6); box-shadow: 0 0 34px rgba(255,45,100,.22); }
.gameover-actions .btn-primary .btn-label { font-size: 17px; }
.gameover-note { margin: 12px 0 0; font-family: var(--mono); font-size: 7px; letter-spacing: .08em; color: rgba(155,140,170,.65); }
.revive-offer {
  margin-top: 4px;
  padding: 15px 16px 17px;
  text-align: left;
  background: linear-gradient(120deg, rgba(32, 22, 6, .45), rgba(8, 14, 26, .6));
  border: 1px solid rgba(255,211,77,.28);
  border-left: 2px solid var(--gold);
  animation: offer-glow 2.2s ease-in-out infinite;
}
@keyframes offer-glow { 50% { border-color: rgba(255,211,77,.5); box-shadow: inset 0 0 30px rgba(255,211,77,.04); } }
.offer-head { display: flex; justify-content: space-between; align-items: center; gap: 10px; }
.offer-tag { font-family: var(--mono); font-size: 7px; letter-spacing: .18em; color: var(--gold); }
.offer-deaths { font-family: var(--mono); font-size: 7px; letter-spacing: .1em; color: #d4a95f; }
.revive-offer > p { margin: 9px 0 11px; font-family: var(--mono); font-size: 9.5px; line-height: 1.55; color: #d6cab4; }
.revive-offer strong { color: var(--gold); }
.btn-revive {
  width: 100%;
  min-height: 56px;
  color: #241800;
  background: linear-gradient(100deg, #ffe47a, #ffc42d 50%, #ff9f1a);
  border: 1px solid rgba(255,245,190,.6);
  box-shadow: 0 0 34px rgba(255,196,45,.16);
}
.btn-revive .btn-label { font-size: 15px; letter-spacing: .12em; }
.btn-revive .btn-sub { font-family: var(--mono); font-size: 7px; letter-spacing: .16em; opacity: .65; }
.btn-revive:hover { filter: brightness(1.08); box-shadow: 0 0 45px rgba(255,196,45,.3); }
.offer-fineprint { display: block; margin-top: 8px; font-family: var(--mono); font-size: 6.5px; line-height: 1.5; letter-spacing: .03em; color: rgba(190,170,130,.6); }

/* ---------- ad ---------- */
.ad-screen { background: rgba(2, 5, 12, .92); backdrop-filter: blur(8px); }
.ad-panel {
  width: min(680px, 94vw);
  padding: 18px;
  background: #070b14;
  border: 1px solid rgba(255,211,77,.3);
  box-shadow: 0 50px 120px rgba(0,0,0,.8);
}
.ad-topline { display: flex; justify-content: space-between; align-items: center; padding: 0 4px 12px; font-family: var(--mono); font-size: 8px; letter-spacing: .24em; color: #bda869; }
.ad-countdown { display: grid; place-items: center; width: 27px; height: 27px; border: 1px solid rgba(255,211,77,.4); color: var(--gold); font-size: 11px; }
.ad-creative {
  position: relative;
  min-height: min(330px, 42vh);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  text-align: center;
  background:
    radial-gradient(circle at 50% 45%, rgba(255, 199, 46, .17), transparent 52%),
    repeating-linear-gradient(115deg, rgba(255,255,255,.025) 0 1px, transparent 1px 18px),
    linear-gradient(150deg, #1a1405, #080b13 60%, #0b1220);
  border: 1px solid rgba(255,211,77,.13);
}
.ad-badge { font-family: var(--mono); font-size: 8px; letter-spacing: .55em; color: var(--gold); border: 1px solid rgba(255,211,77,.35); padding: 5px 12px; }
.ad-creative h2 { position: relative; z-index: 2; margin: 18px 0 10px; font-size: clamp(38px, 6vw, 64px); line-height: .84; letter-spacing: .02em; color: #fff3c4; text-shadow: 0 0 40px rgba(255,190,40,.24); }
.ad-creative p { position: relative; z-index: 2; max-width: 330px; margin: 0; font-family: var(--mono); font-size: 9px; line-height: 1.7; color: #9e9272; }
.ad-brand { position: absolute; z-index: 2; bottom: 12px; font-family: var(--mono); font-size: 6.5px; letter-spacing: .18em; color: rgba(190,170,120,.5); }
.ad-orbit { position: absolute; width: 330px; height: 330px; border: 1px solid rgba(255,211,77,.1); border-radius: 50%; animation: ad-orbit 12s linear infinite; }
.ad-orbit::before, .ad-orbit::after { content: ""; position: absolute; border: 1px solid rgba(255,211,77,.08); border-radius: 50%; }
.ad-orbit::before { inset: 38px; }
.ad-orbit::after { inset: 76px; background: radial-gradient(circle, rgba(255,211,77,.08), transparent 70%); }
@keyframes ad-orbit { to { transform: rotate(360deg); } }
.ad-progress { height: 2px; margin: 14px 0; background: rgba(255,255,255,.08); overflow: hidden; }
.ad-progress i { display: block; height: 100%; width: 0%; background: linear-gradient(90deg, #ffb300, #fff4b8); box-shadow: 0 0 10px rgba(255,211,77,.7); }
.ad-actions { display: flex; gap: 8px; }
.ad-actions .btn { flex: 1; }
.ad-actions .btn-primary { min-height: 46px; background: linear-gradient(100deg, #ffe47a, #ffc42d 55%, #ff9f1a); color: #241800; }
.ad-actions .btn-primary .btn-label { font-size: 15px; }

/* ---------- rotate hint / boot error ---------- */
.rotate-hint {
  position: absolute;
  z-index: 60;
  left: 50%;
  bottom: calc(10px + env(safe-area-inset-bottom));
  transform: translateX(-50%);
  display: none;
  align-items: center;
  gap: 7px;
  padding: 6px 12px;
  background: rgba(4, 9, 20, .82);
  border: 1px solid rgba(57,245,255,.18);
  font-family: var(--mono);
  font-size: 7px;
  letter-spacing: .08em;
  color: #86a2c2;
  pointer-events: none;
}
.rotate-hint span { color: var(--cyan); font-size: 12px; }
.rotate-hint p { margin: 0; }

.boot-error {
  position: absolute;
  z-index: 100;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 40px;
  text-align: center;
  background: #05070f;
