export const TAU = Math.PI * 2;

export const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => (v - a) / (b - a);
export const rand = (min = 0, max = 1) => min + Math.random() * (max - min);
export const randInt = (min, max) => Math.floor(rand(min, max + 1));
export const pick = (array) => array[Math.floor(Math.random() * array.length)];
export const chance = (probability) => Math.random() < probability;
export const sign = (value) => (value < 0 ? -1 : value > 0 ? 1 : 0);
export const approach = (value, target, delta) => {
  if (value < target) return Math.min(value + delta, target);
  if (value > target) return Math.max(value - delta, target);
  return target;
};
export const damp = (value, target, smoothing, dt) => lerp(value, target, 1 - Math.exp(-smoothing * dt));
export const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);
export const easeInCubic = (t) => t * t * t;
export const easeOutQuint = (t) => 1 - Math.pow(1 - t, 5);
export const easeInOutQuad = (t) => (t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2);
export const easeOutBack = (t) => {
  const c1 = 1.70158;
  const c3 = c1 + 1;
  return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
};
export const span = (t, start, end) => clamp((t - start) / (end - start), 0, 1);
export const pulse = (t, frequency = 1) => 0.5 + 0.5 * Math.sin(t * TAU * frequency);
export const formatTime = (seconds) => {
  const total = Math.max(0, Math.floor(seconds));
  const minutes = Math.floor(total / 60).toString().padStart(2, '0');
  const secs = (total % 60).toString().padStart(2, '0');
  return `${minutes}:${secs}`;
};
export const randomId = () => Math.random().toString(36).slice(2, 10);

export function rectsOverlap(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}

export function pointDirection(fromX, fromY, toX, toY) {
  const dx = toX - fromX;
  const dy = toY - fromY;
  const length = Math.hypot(dx, dy) || 1;
  return { x: dx / length, y: dy / length, length, angle: Math.atan2(dy, dx) };
}

export function hexToRgba(hex, alpha = 1) {
  const value = hex.replace('#', '');
  const full = value.length === 3 ? value.split('').map((c) => c + c).join('') : value;
  const number = parseInt(full, 16);
  const r = (number >> 16) & 255;
  const g = (number >> 8) & 255;
  const b = number & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

import { clamp, rand } from './utils.js';

/**
 * Tiny procedural audio engine. No external assets, no network requests.
 * Sounds are synthesized on demand so the whole game stays one static bundle.
 */
export class AudioEngine {
  constructor() {
    this.context = null;
    this.master = null;
    this.compressor = null;
    this.noiseBuffer = null;
    this.muted = false;
    try {
      this.muted = localStorage.getItem('neon-fist-muted') === '1';
    } catch {
      this.muted = false;
    }
  }

  ensure() {
    if (this.context) {
      if (this.context.state === 'suspended') this.context.resume().catch(() => {});
      return true;
    }
    const AudioContext = window.AudioContext || window.webkitAudioContext;
    if (!AudioContext) return false;
    try {
      this.context = new AudioContext();
      this.master = this.context.createGain();
      this.master.gain.value = this.muted ? 0 : 0.55;
      this.compressor = this.context.createDynamicsCompressor();
      this.compressor.threshold.value = -18;
      this.compressor.knee.value = 22;
      this.compressor.ratio.value = 8;
      this.compressor.attack.value = 0.003;
      this.compressor.release.value = 0.22;
      this.master.connect(this.compressor).connect(this.context.destination);
      this.noiseBuffer = this.createNoiseBuffer();
      return true;
    } catch {
      this.context = null;
      return false;
    }
  }

  createNoiseBuffer() {
    const length = this.context.sampleRate * 1.2;
    const buffer = this.context.createBuffer(1, length, this.context.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < length; i += 1) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  setMuted(muted) {
    this.muted = muted;
    try { localStorage.setItem('neon-fist-muted', muted ? '1' : '0'); } catch { /* ignore */ }
    if (this.master && this.context) {
      this.master.gain.cancelScheduledValues(this.context.currentTime);
      this.master.gain.setTargetAtTime(muted ? 0 : 0.55, this.context.currentTime, 0.03);
    }
  }

  toggleMuted() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  now() {
    return this.context ? this.context.currentTime : 0;
  }

  tone({ frequency = 220, endFrequency = frequency, duration = 0.15, type = 'sine', volume = 0.3, attack = 0.004, delay = 0, detune = 0 }) {
    if (!this.context || this.muted) return;
    const t0 = this.now() + delay;
    const osc = this.context.createOscillator();
    const gain = this.context.createGain();
    osc.type = type;
    osc.detune.value = detune;
    osc.frequency.setValueAtTime(Math.max(20, frequency), t0);
    osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFrequency), t0 + duration);
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0001, volume), t0 + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    osc.connect(gain).connect(this.master);
    osc.start(t0);
    osc.stop(t0 + duration + 0.02);
  }

  noise({ duration = 0.12, volume = 0.25, filter = 1400, filterEnd = filter, type = 'bandpass', q = 0.8, delay = 0 }) {
    if (!this.context || this.muted || !this.noiseBuffer) return;
    const t0 = this.now() + delay;
    const source = this.context.createBufferSource();
    source.buffer = this.noiseBuffer;
    const filterNode = this.context.createBiquadFilter();
    filterNode.type = type;
    filterNode.Q.value = q;
    filterNode.frequency.setValueAtTime(filter, t0);
    filterNode.frequency.exponentialRampToValueAtTime(Math.max(60, filterEnd), t0 + duration);
    const gain = this.context.createGain();
    gain.gain.setValueAtTime(0.0001, t0);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0001, volume), t0 + 0.005);
    gain.gain.exponentialRampToValueAtTime(0.0001, t0 + duration);
    source.connect(filterNode).connect(gain).connect(this.master);
    source.start(t0);
    source.stop(t0 + duration + 0.02);
  }

  click() {
    if (!this.ensure()) return;
    this.tone({ frequency: 410, endFrequency: 640, duration: 0.06, type: 'triangle', volume: 0.11 });
  }

  ui() {
    if (!this.ensure()) return;
    this.tone({ frequency: 640, endFrequency: 980, duration: 0.09, type: 'sine', volume: 0.1 });
    this.tone({ frequency: 980, endFrequency: 1400, duration: 0.12, type: 'sine', volume: 0.05, delay: 0.04 });
  }

  whoosh(strength = 1) {
    if (!this.ensure()) return;
    this.noise({ duration: 0.16 + strength * 0.08, volume: 0.07 + strength * 0.04, filter: 700, filterEnd: 2400, q: 1.4 });
  }

  hitLight() {
    if (!this.ensure()) return;
    this.noise({ duration: 0.075, volume: 0.24, filter: 2600, filterEnd: 600, type: 'highpass', q: 0.6 });
    this.tone({ frequency: 180, endFrequency: 70, duration: 0.1, type: 'square', volume: 0.1 });
  }

  hitHeavy() {
    if (!this.ensure()) return;
    this.noise({ duration: 0.19, volume: 0.38, filter: 1800, filterEnd: 120, type: 'lowpass', q: 0.8 });
    this.tone({ frequency: 155, endFrequency: 38, duration: 0.3, type: 'sine', volume: 0.32 });
    this.tone({ frequency: 74, endFrequency: 30, duration: 0.36, type: 'triangle', volume: 0.25 });
  }

  shield() {
    if (!this.ensure()) return;
    this.tone({ frequency: 1250, endFrequency: 640, duration: 0.16, type: 'square', volume: 0.07 });
    this.tone({ frequency: 1870, endFrequency: 1320, duration: 0.12, type: 'sine', volume: 0.1 });
    this.noise({ duration: 0.08, volume: 0.1, filter: 3200, filterEnd: 2000, type: 'highpass' });
  }

  grab() {
    if (!this.ensure()) return;
    this.noise({ duration: 0.1, volume: 0.16, filter: 600, filterEnd: 1600, q: 2 });
    this.tone({ frequency: 220, endFrequency: 330, duration: 0.07, type: 'triangle', volume: 0.08 });
  }

  throwEnemy() {
    if (!this.ensure()) return;
    this.noise({ duration: 0.32, volume: 0.2, filter: 350, filterEnd: 2200, q: 0.7 });
    this.tone({ frequency: 110, endFrequency: 250, duration: 0.24, type: 'sawtooth', volume: 0.08 });
  }

  jump() {
    if (!this.ensure()) return;
    this.tone({ frequency: 210, endFrequency: 430, duration: 0.11, type: 'sine', volume: 0.08 });
    this.noise({ duration: 0.06, volume: 0.05, filter: 900, filterEnd: 2600 });
  }

  land() {
    if (!this.ensure()) return;
    this.noise({ duration: 0.12, volume: 0.15, filter: 400, filterEnd: 90, type: 'lowpass' });
    this.tone({ frequency: 90, endFrequency: 45, duration: 0.12, type: 'sine', volume: 0.12 });
  }

  slam() {
    if (!this.ensure()) return;
    this.noise({ duration: 0.38, volume: 0.4, filter: 900, filterEnd: 70, type: 'lowpass', q: 1 });
    this.tone({ frequency: 68, endFrequency: 26, duration: 0.45, type: 'sine', volume: 0.4 });
  }

  electric(duration = 0.5) {
    if (!this.ensure()) return;
    this.tone({ frequency: 1800, endFrequency: 120, duration: duration * 0.8, type: 'sawtooth', volume: 0.09 });
    this.tone({ frequency: 93, endFrequency: 58, duration, type: 'square', volume: 0.06, detune: -12 });
    for (let i = 0; i < 5; i += 1) {
      this.tone({
        frequency: rand(900, 2600),
        endFrequency: rand(180, 900),
        duration: rand(0.04, 0.11),
        type: 'square',
        volume: 0.04,
        delay: i * 0.045,
      });
    }
    this.noise({ duration: duration * 0.9, volume: 0.12, filter: 3000, filterEnd: 400, type: 'bandpass', q: 1.6 });
  }

  special() {
    if (!this.ensure()) return;
    this.tone({ frequency: 60, endFrequency: 600, duration: 0.7, type: 'sawtooth', volume: 0.08 });
    this.tone({ frequency: 880, endFrequency: 110, duration: 0.55, type: 'square', volume: 0.06, delay: 0.08 });
    this.noise({ duration: 0.6, volume: 0.18, filter: 500, filterEnd: 6000, q: 1.2 });
    this.slam();
  }

  hurt() {
    if (!this.ensure()) return;
    this.noise({ duration: 0.16, volume: 0.24, filter: 1200, filterEnd: 240, type: 'lowpass' });
    this.tone({ frequency: 160, endFrequency: 55, duration: 0.2, type: 'sawtooth', volume: 0.12 });
  }

  death() {
    if (!this.ensure()) return;
    this.tone({ frequency: 280, endFrequency: 32, duration: 0.95, type: 'sawtooth', volume: 0.16 });
    this.noise({ duration: 0.8, volume: 0.18, filter: 1600, filterEnd: 70, type: 'lowpass' });
  }

  wave() {
    if (!this.ensure()) return;
    this.tone({ frequency: 146, endFrequency: 146, duration: 0.36, type: 'triangle', volume: 0.08 });
    this.tone({ frequency: 220, endFrequency: 220, duration: 0.5, type: 'triangle', volume: 0.06, delay: 0.11 });
    this.tone({ frequency: 293, endFrequency: 293, duration: 0.62, type: 'triangle', volume: 0.05, delay: 0.22 });
  }

  combo(step = 0) {
    if (!this.ensure()) return;
    const scale = [392, 440, 523, 587, 659, 784, 880, 1046];
    const frequency = scale[clamp(step, 0, scale.length - 1)];
    this.tone({ frequency, endFrequency: frequency * 1.02, duration: 0.07, type: 'sine', volume: 0.045 });
  }

  revive() {
    if (!this.ensure()) return;
    [330, 440, 554, 660].forEach((frequency, index) => {
      this.tone({ frequency, duration: 0.24, type: 'sine', volume: 0.07, delay: index * 0.07 });
    });
  }
}

const KEY_BINDINGS = {
  ArrowLeft: 'left',
  KeyA: 'left',
  ArrowRight: 'right',
  KeyD: 'right',
  ArrowDown: 'down',
  KeyS: 'down',
  ArrowUp: 'jump',
  KeyW: 'jump',
  Space: 'jump',
  KeyJ: 'light',
  KeyZ: 'light',
  KeyK: 'heavy',
  KeyX: 'heavy',
  KeyL: 'grab',
  KeyC: 'grab',
  KeyU: 'special',
  KeyV: 'special',
  KeyE: 'special',
};

const GAME_KEYS = new Set(Object.keys(KEY_BINDINGS));

export class Input {
  constructor() {
    this.sources = new Map();
    this.pressed = new Set();
    this.visualButtons = new Map();
    this.pauseListeners = new Set();
    this.enabled = true;
    this.bindKeyboard();
    this.bindTouch();
  }

  onPause(callback) {
    this.pauseListeners.add(callback);
  }

  bindKeyboard() {
    window.addEventListener('keydown', (event) => {
      if (event.code === 'KeyP' || event.code === 'Escape') {
        if (!event.repeat) {
          event.preventDefault();
          for (const callback of this.pauseListeners) callback();
        }
        return;
      }
      const action = KEY_BINDINGS[event.code];
      if (!action) return;
      event.preventDefault();
      if (event.repeat) return;
      const source = `key:${event.code}`;
      this.sources.set(source, action);
      this.pressed.add(action);
      this.flash(action);
    });

    window.addEventListener('keyup', (event) => {
      const action = KEY_BINDINGS[event.code];
      if (!action) return;
      this.sources.delete(`key:${event.code}`);
    });

    window.addEventListener('blur', () => this.clear());
    document.addEventListener('visibilitychange', () => {
      if (document.hidden) this.clear();
    });
  }

  bindTouch() {
    const controls = document.getElementById('controls');
    if (!controls) return;

    controls.querySelectorAll('[data-hold], [data-press]').forEach((button) => {
      const hold = button.dataset.hold;
      const press = button.dataset.press;
      const action = hold || press;
      if (!action) return;
      this.visualButtons.set(action, button);

      const pointerDown = (event) => {
        if (!this.enabled) return;
        event.preventDefault();
        event.stopPropagation();
        const source = `ptr:${event.pointerId}`;
        this.sources.set(source, action);
        if (press) {
          this.pressed.add(press);
          this.flash(press);
        }
        button.classList.add('active');
        try { button.setPointerCapture(event.pointerId); } catch { /* ignore */ }
      };

      const pointerUp = (event) => {
        event.preventDefault();
        const source = `ptr:${event.pointerId}`;
        this.sources.delete(source);
        button.classList.remove('active');
      };

      button.addEventListener('pointerdown', pointerDown, { passive: false });
      button.addEventListener('pointerup', pointerUp, { passive: false });
      button.addEventListener('pointercancel', pointerUp, { passive: false });
      button.addEventListener('lostpointercapture', pointerUp, { passive: false });
      button.addEventListener('contextmenu', (event) => event.preventDefault());
    });

    controls.addEventListener('contextmenu', (event) => event.preventDefault());
    controls.addEventListener('pointerdown', (event) => event.preventDefault(), { passive: false });
  }

  flash(action) {
    const button = this.visualButtons.get(action);
    if (!button) return;
    button.classList.add('active');
    window.clearTimeout(button._flashTimer);
    button._flashTimer = window.setTimeout(() => {
      if (!this.isDown(action)) button.classList.remove('active');
    }, 110);
  }

  isDown(action) {
    for (const value of this.sources.values()) {
      if (value === action) return true;
    }
    return false;
  }

  wasPressed(action) {
    return this.pressed.has(action);
  }

  get move() {
    return (this.isDown('right') ? 1 : 0) - (this.isDown('left') ? 1 : 0);
  }

  endFrame() {
    this.pressed.clear();
    for (const [action, button] of this.visualButtons) {
      if (!this.isDown(action)) button.classList.remove('active');
    }
  }

  clear() {
    this.sources.clear();
    this.pressed.clear();
    for (const button of this.visualButtons.values()) button.classList.remove('active');
  }

  setEnabled(enabled) {
    this.enabled = enabled;
    if (!enabled) this.clear();
  }
}

import { TAU, clamp, rand, easeOutCubic, easeOutBack, pick } from './utils.js';

const MAX_PARTICLES = 440;

export class FX {
  constructor() {
    this.particles = [];
    this.rings = [];
    this.texts = [];
    this.bolts = [];
    this.arcs = [];
    this.flashes = [];
    this.screen = { alpha: 0, color: '#ffffff', decay: 1 };
    this.time = 0;
  }

  reset() {
    this.particles.length = 0;
    this.rings.length = 0;
    this.texts.length = 0;
    this.bolts.length = 0;
    this.arcs.length = 0;
    this.flashes.length = 0;
    this.screen.alpha = 0;
  }

  addParticle(particle) {
    if (this.particles.length >= MAX_PARTICLES) this.particles.shift();
    this.particles.push(particle);
  }

  burst(x, y, options = {}) {
    const {
      count = 12,
      color = '#66f5ff',
      speed = 380,
      angle = null,
      spread = Math.PI,
      gravity = 900,
      size = 3,
      life = 0.45,
      shape = 'spark',
      drag = 0.92,
    } = options;
    const baseAngle = angle === null ? rand(0, TAU) : angle;
    for (let i = 0; i < count; i += 1) {
      const a = baseAngle + rand(-spread / 2, spread / 2);
      const velocity = rand(speed * 0.35, speed);
      this.addParticle({
        type: shape,
        x: x + rand(-3, 3),
        y: y + rand(-3, 3),
        px: x,
        py: y,
        vx: Math.cos(a) * velocity,
        vy: Math.sin(a) * velocity,
        gravity,
        drag,
        size: rand(size * 0.45, size),
        color,
        life: rand(life * 0.55, life),
        maxLife: life,
        rot: rand(0, TAU),
        rotVel: rand(-12, 12),
      });
    }
  }

  dust(x, y, count = 8, direction = 0, color = '#7f9dc8') {
    for (let i = 0; i < count; i += 1) {
      const a = -Math.PI / 2 + rand(-0.9, 0.9) + (direction ? direction * 0.35 : 0);
      const speed = rand(30, 145);
      this.addParticle({
        type: 'dust',
        x: x + rand(-12, 12),
        y: y + rand(-3, 2),
        px: x,
        py: y,
        vx: Math.cos(a) * speed + direction * rand(10, 60),
        vy: Math.sin(a) * speed * 0.55,
        gravity: -80,
        drag: 0.9,
        size: rand(3, 9),
        color,
        life: rand(0.35, 0.75),
        maxLife: 0.75,
        rot: 0,
        rotVel: 0,
      });
    }
  }

  shards(x, y, count = 6, color = '#8ffbff', direction = 0) {
    for (let i = 0; i < count; i += 1) {
      this.addParticle({
        type: 'shard',
        x,
        y,
        px: x,
        py: y,
        vx: direction * rand(70, 350) + rand(-100, 100),
        vy: rand(-360, -120),
        gravity: 1400,
        drag: 0.98,
        size: rand(4, 11),
        color,
        life: rand(0.4, 0.8),
        maxLife: 0.8,
        rot: rand(0, TAU),
        rotVel: rand(-10, 10),
      });
    }
  }

  trail(x, y, color = '#39f5ff', size = 5, life = 0.28) {
    this.addParticle({
      type: 'trail',
      x,
      y,
      px: x,
      py: y,
      vx: rand(-8, 8),
      vy: rand(-8, 8),
      gravity: 0,
      drag: 1,
      size,
      color,
      life,
      maxLife: life,
      rot: 0,
      rotVel: 0,
    });
  }

  ring(x, y, options = {}) {
    const {
      color = '#39f5ff',
      maxRadius = 90,
      life = 0.4,
      width = 3,
      fill = false,
      squash = 0.45,
      delay = 0,
    } = options;
    this.rings.push({ x, y, r: 3, maxRadius, life, maxLife: life, width, color, fill, squash, delay });
  }

  text(x, y, value, options = {}) {
    const {
      color = '#ffffff',
      size = 19,
      life = 0.85,
      vy = -80,
      vx = 0,
      stroke = 'rgba(0,5,15,.85)',
      weight = 900,
      pop = true,
      glow = true,
    } = options;
    this.texts.push({
      x, y, value: String(value), color, size, life, maxLife: life,
      vy, vx, stroke, weight, pop, glow,
    });
  }

  bolt(x1, y1, x2, y2, options = {}) {
    const { color = '#8ffbff', life = 0.16, width = 2.2, segments = 8, jitter = 16 } = options;
    const points = [{ x: x1, y: y1 }];
    for (let i = 1; i < segments; i += 1) {
      const t = i / segments;
      points.push({
        x: x1 + (x2 - x1) * t + rand(-jitter, jitter),
        y: y1 + (y2 - y1) * t + rand(-jitter, jitter),
      });
    }
    points.push({ x: x2, y: y2 });
    this.bolts.push({ points, color, life, maxLife: life, width });
  }

  arc(x, y, options = {}) {
    const {
      angle = 0,
      radius = 70,
      spread = Math.PI * 0.8,
      color = '#8ffbff',
      life = 0.2,
      width = 5,
      inner = 0.25,
    } = options;
    this.arcs.push({ x, y, angle, radius, spread, color, life, maxLife: life, width, inner });
  }

  flash(x, y, radius = 60, color = '#e8ffff', life = 0.18) {
    this.flashes.push({ x, y, radius, color, life, maxLife: life });
  }

  screenFlash(color = '#ffffff', alpha = 0.25, decay = 4.5) {
    this.screen.color = color;
    this.screen.alpha = Math.max(this.screen.alpha, alpha);
    this.screen.decay = decay;
  }

  impact(x, y, angle, power = 1, color = '#8ffbff') {
    const strength = clamp(power, 0.35, 2.4);
    this.flash(x, y, 34 + 45 * strength, color, 0.12 + strength * 0.035);
    this.ring(x, y, { color, maxRadius: 60 + 55 * strength, life: 0.32, width: 2 + strength * 1.4, squash: 0.65 });
    this.burst(x, y, {
      count: Math.round(6 + 10 * strength),
      color,
      speed: 260 + 220 * strength,
      angle,
      spread: 1.8,
      gravity: 850,
      size: 2.6 + strength,
      life: 0.35 + strength * 0.1,
    });
    this.arc(x - Math.cos(angle) * 10, y - Math.sin(angle) * 10, {
      angle,
      radius: 26 + 34 * strength,
      spread: 1.9,
      color,
      life: 0.14,
      width: 2 + strength * 2.4,
      inner: 0.15,
    });
  }

  update(dt) {
    this.time += dt;
    for (let i = this.particles.length - 1; i >= 0; i -= 1) {
      const p = this.particles[i];
      p.life -= dt;
      if (p.life <= 0) {
        this.particles.splice(i, 1);
        continue;
      }
      p.px = p.x;
      p.py = p.y;
      p.vx *= Math.pow(p.drag, dt * 60);
      p.vy += p.gravity * dt;
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.rot += p.rotVel * dt;
      if (p.type === 'shard' && p.y > 0) {
        // shards are cut short by the caller's world floor via bounds; keep them cheap
      }
    }

    for (let i = this.rings.length - 1; i >= 0; i -= 1) {
      const ring = this.rings[i];
      if (ring.delay > 0) {
        ring.delay -= dt;
        continue;
      }
      ring.life -= dt;
      ring.r += ((ring.maxRadius - ring.r) * 10) * dt;
      if (ring.life <= 0) this.rings.splice(i, 1);
    }

    for (let i = this.texts.length - 1; i >= 0; i -= 1) {
      const text = this.texts[i];
      text.life -= dt;
      if (text.life <= 0) {
        this.texts.splice(i, 1);
        continue;
      }
      text.x += text.vx * dt;
      text.y += text.vy * dt;
      text.vy += 150 * dt;
    }

    for (let i = this.bolts.length - 1; i >= 0; i -= 1) {
      this.bolts[i].life -= dt;
      if (this.bolts[i].life <= 0) this.bolts.splice(i, 1);
    }

    for (let i = this.arcs.length - 1; i >= 0; i -= 1) {
      this.arcs[i].life -= dt;
      if (this.arcs[i].life <= 0) this.arcs.splice(i, 1);
    }

    for (let i = this.flashes.length - 1; i >= 0; i -= 1) {
      const flash = this.flashes[i];
      flash.life -= dt;
      if (flash.life <= 0) this.flashes.splice(i, 1);
    }

    this.screen.alpha = Math.max(0, this.screen.alpha - this.screen.decay * dt);
  }

  draw(ctx, groundY) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';

    for (const flash of this.flashes) {
      const t = 1 - flash.life / flash.maxLife;
      const radius = flash.radius * (0.4 + easeOutCubic(t) * 1.1);
      const gradient = ctx.createRadialGradient(flash.x, flash.y, 0, flash.x, flash.y, radius);
      gradient.addColorStop(0, flash.color);
      gradient.addColorStop(0.25, `${flash.color}99`);
      gradient.addColorStop(1, `${flash.color}00`);
      ctx.globalAlpha = (1 - t) * 0.8;
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.arc(flash.x, flash.y, radius, 0, TAU);
      ctx.fill();
    }

    for (const ring of this.rings) {
      const t = 1 - ring.life / ring.maxLife;
      ctx.globalAlpha = Math.max(0, 1 - t) * 0.8;
      ctx.strokeStyle = ring.color;
      ctx.lineWidth = ring.width * (1 - t * 0.5);
      ctx.beginPath();
      ctx.ellipse(ring.x, ring.y, ring.r, ring.r * ring.squash, 0, 0, TAU);
      if (ring.fill) {
        ctx.fillStyle = `${ring.color}18`;
        ctx.fill();
      }
      ctx.stroke();
    }

    for (const arc of this.arcs) {
      const t = 1 - arc.life / arc.maxLife;
      ctx.globalAlpha = (1 - t) * 0.9;
      ctx.strokeStyle = arc.color;
      ctx.lineWidth = arc.width * (1 - t * 0.6);
      ctx.beginPath();
      const inner = arc.radius * arc.inner;
      ctx.arc(arc.x, arc.y, arc.radius, arc.angle - arc.spread / 2, arc.angle + arc.spread / 2);
      ctx.stroke();
      ctx.globalAlpha *= 0.3;
      ctx.beginPath();
      ctx.arc(arc.x, arc.y, inner, arc.angle - arc.spread / 2, arc.angle + arc.spread / 2);
      ctx.stroke();
    }

    for (const p of this.particles) {
      const a = clamp(p.life / p.maxLife, 0, 1);
      ctx.globalAlpha = a;
      if (p.type === 'spark') {
        ctx.strokeStyle = p.color;
        ctx.lineWidth = p.size * 0.7;
        ctx.beginPath();
        ctx.moveTo(p.x - p.vx * 0.022, p.y - p.vy * 0.022);
        ctx.lineTo(p.x, p.y);
        ctx.stroke();
      } else if (p.type === 'trail') {
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * a, 0, TAU);
        ctx.fill();
      } else if (p.type === 'shard') {
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate(p.rot);
        ctx.fillStyle = p.color;
        ctx.fillRect(-p.size * 0.5, -p.size * 0.1, p.size, p.size * 0.2);
        ctx.restore();
      } else if (p.type === 'dust') {
        ctx.fillStyle = p.color;
        ctx.globalAlpha = a * 0.28;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * (1.4 - a * 0.5), 0, TAU);
        ctx.fill();
      } else if (p.type === 'ember') {
        ctx.fillStyle = p.color;
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size * a, 0, TAU);
        ctx.fill();
      }
    }

    for (const bolt of this.bolts) {
      const a = clamp(bolt.life / bolt.maxLife, 0, 1);
      ctx.globalAlpha = a;
      ctx.strokeStyle = bolt.color;
      ctx.lineWidth = bolt.width;
      ctx.beginPath();
      ctx.moveTo(bolt.points[0].x, bolt.points[0].y);
      for (let i = 1; i < bolt.points.length; i += 1) {
        ctx.lineTo(bolt.points[i].x, bolt.points[i].y);
      }
      ctx.stroke();
      ctx.globalAlpha = a * 0.35;
      ctx.lineWidth = bolt.width * 4;
      ctx.stroke();
    }

    ctx.globalCompositeOperation = 'source-over';
    for (const text of this.texts) {
      const t = 1 - text.life / text.maxLife;
      const pop = text.pop ? (t < 0.18 ? easeOutBack(t / 0.18) : 1) : 1;
      const alpha = t > 0.72 ? 1 - (t - 0.72) / 0.28 : 1;
      ctx.save();
      ctx.translate(text.x, text.y);
      ctx.scale(pop, pop);
      ctx.globalAlpha = clamp(alpha, 0, 1);
      ctx.font = `${text.weight} ${text.size}px "Bahnschrift", "Arial Black", "Liberation Sans", sans-serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      if (text.glow && ctx.shadowBlur !== undefined) {
        ctx.shadowColor = text.color;
        ctx.shadowBlur = 12;
      }
      ctx.lineWidth = Math.max(3, text.size * 0.16);
      ctx.strokeStyle = text.stroke;
      ctx.strokeText(text.value, 0, 0);
      ctx.fillStyle = text.color;
      ctx.fillText(text.value, 0, 0);
      ctx.restore();
    }

    ctx.restore();
  }

  drawScreen(ctx, width, height) {
    if (this.screen.alpha <= 0.001) return;
    ctx.save();
    ctx.globalAlpha = clamp(this.screen.alpha, 0, 0.7);
    ctx.fillStyle = this.screen.color;
    ctx.fillRect(0, 0, width, height);
    ctx.restore();
  }
}

import { TAU, clamp, rand, randInt, pick, pulse } from './utils.js';

function seeded(seed) {
  let value = seed % 2147483647;
  if (value <= 0) value += 2147483646;
  return () => {
    value = (value * 16807) % 2147483647;
    return (value - 1) / 2147483646;
  };
}

export class Scene {
  constructor() {
    this.w = 0;
    this.h = 0;
    this.groundY = 0;
    this.left = 0;
    this.right = 0;
    this.time = 0;
    this.stars = [];
    this.far = [];
    this.mid = [];
    this.rain = [];
    this.embers = [];
    this.cracks = [];
    this.puddles = [];
    this.cables = [];
    this.wallPulse = { left: 0, right: 0 };
    this.lightning = 0;
    this.nextLightning = rand(8, 20);
  }

  resize(width, height, groundY, left, right) {
    this.w = width;
    this.h = height;
    this.groundY = groundY;
    this.left = left;
    this.right = right;
    const random = seeded(Math.round(width * 13 + height * 7));
    const horizon = groundY - 8;

    this.stars = Array.from({ length: 72 }, () => ({
      x: random() * width,
      y: random() * horizon * 0.62,
      r: 0.4 + random() * 1.2,
      a: 0.18 + random() * 0.55,
      twinkle: random() * TAU,
    }));

    this.far = this.makeCity(random, horizon, 17, 48, 170, width * 0.3);
    this.mid = this.makeCity(random, horizon, 12, 62, 250, width * 0.18);
    this.rain = Array.from({ length: Math.round(clamp(width / 16, 40, 110)) }, () => ({
      x: random() * width,
      y: random() * height,
      len: 7 + random() * 17,
      speed: 260 + random() * 320,
      alpha: 0.04 + random() * 0.13,
    }));
    this.embers = Array.from({ length: Math.round(clamp(width / 28, 18, 46)) }, () => ({
      x: random() * width,
      y: groundY - random() * height * 0.55,
      r: 0.5 + random() * 1.4,
      speed: 5 + random() * 16,
      drift: random() * TAU,
      alpha: 0.08 + random() * 0.3,
      hue: random() > 0.6 ? 'cyan' : random() > 0.4 ? 'pink' : 'gold',
    }));
    this.cracks = Array.from({ length: 9 }, () => ({
      x: left + random() * (right - left),
      y: groundY + 18 + random() * (height - groundY - 20),
      len: 18 + random() * 60,
      angle: random() * TAU,
      fork: random() > 0.5,
    }));
    this.puddles = Array.from({ length: 5 }, () => ({
      x: left + random() * (right - left),
      y: groundY + 25 + random() * Math.max(30, height - groundY - 60),
      rx: 34 + random() * 90,
      ry: 5 + random() * 11,
      color: pick(['#2a7dff', '#ff3ea5', '#39f5ff']),
      alpha: 0.08 + random() * 0.09,
    }));
    this.cables = [
      { x1: -20, y1: height * 0.12, x2: width * 0.52, y2: height * 0.2, sag: 26 + random() * 24 },
      { x1: width * 0.38, y1: height * 0.06, x2: width + 20, y2: height * 0.16, sag: 18 + random() * 34 },
      { x1: width * 0.72, y1: -10, x2: width * 1.04, y2: height * 0.34, sag: 22 },
    ];
  }

  makeCity(random, horizon, count, minWidth, maxHeight, spread) {
    const buildings = [];
    let x = -30;
    for (let i = 0; i < count; i += 1) {
      const width = minWidth * (0.55 + random() * 1.15);
      const height = 40 + Math.pow(random(), 1.7) * maxHeight;
      const building = {
        x,
        y: horizon - height,
        w: width,
        h: height,
        seed: Math.floor(random() * 100000),
        antenna: random() > 0.68,
        tank: random() > 0.82,
        sign: random() > 0.78,
      };
      buildings.push(building);
      x += width + 2 + random() * 13;
    }
    const total = x;
    const scale = (this.w + 60) / total;
    for (const building of buildings) {
      building.x *= scale;
      building.w *= scale * (0.92 + random() * 0.15);
      building.h *= 0.7 + (spread / this.w) * 0.25;
      building.y = horizon - building.h;
    }
    return buildings;
  }

  pulseWall(side, strength = 0.6) {
    if (side === 'left') this.wallPulse.left = Math.max(this.wallPulse.left, strength);
    if (side === 'right') this.wallPulse.right = Math.max(this.wallPulse.right, strength);
  }

  update(dt) {
    this.time += dt;
    const heightSpan = Math.max(120, this.groundY);
    for (const drop of this.rain) {
      drop.y += drop.speed * dt;
      drop.x -= drop.speed * 0.12 * dt;
      if (drop.y > this.h + 20) {
        drop.y = -20;
        drop.x = rand(0, this.w + 100);
      }
      if (drop.x < -30) drop.x = this.w + 20;
    }
    for (const ember of this.embers) {
      ember.y -= ember.speed * dt;
      ember.x += Math.sin(this.time * 0.7 + ember.drift) * 8 * dt;
      if (ember.y < this.groundY - heightSpan) {
        ember.y = this.groundY + rand(-10, 20);
        ember.x = rand(0, this.w);
      }
    }
    this.wallPulse.left = Math.max(0, this.wallPulse.left - dt * 1.7);
    this.wallPulse.right = Math.max(0, this.wallPulse.right - dt * 1.7);
    this.lightning = Math.max(0, this.lightning - dt * 3.2);
    this.nextLightning -= dt;
    if (this.nextLightning <= 0) {
      this.nextLightning = rand(11, 26);
      this.lightning = 1;
    }
  }

  draw(ctx) {
    const { w, h, groundY, left, right } = this;
    const horizon = groundY - 6;
    const sway = 0;

    // Sky
    const sky = ctx.createLinearGradient(0, 0, 0, groundY);
    sky.addColorStop(0, '#020409');
    sky.addColorStop(0.42, '#061020');
    sky.addColorStop(0.72, '#0a1b36');
    sky.addColorStop(0.9, '#122a4a');
    sky.addColorStop(1, '#173257');
    ctx.fillStyle = sky;
    ctx.fillRect(0, 0, w, groundY + 2);

    // Atmospheric bands
    const haze = ctx.createLinearGradient(0, horizon - h * 0.36, 0, horizon);
    haze.addColorStop(0, 'rgba(24, 89, 150, 0)');
    haze.addColorStop(0.6, 'rgba(22, 92, 150, 0.08)');
    haze.addColorStop(1, 'rgba(57, 160, 220, 0.14)');
    ctx.fillStyle = haze;
    ctx.fillRect(0, horizon - h * 0.36, w, h * 0.36);

    // Stars
    for (const star of this.stars) {
      const twinkle = 0.55 + Math.sin(this.time * 1.2 + star.twinkle) * 0.45;
      ctx.globalAlpha = star.a * twinkle;
      ctx.fillStyle = star.x > w * 0.55 ? '#c8f6ff' : '#d8e6ff';
      ctx.beginPath();
      ctx.arc(star.x + sway, star.y, star.r, 0, TAU);
      ctx.fill();
    }
    ctx.globalAlpha = 1;

    // Moon
    this.drawMoon(ctx, w * 0.76, h * 0.155, clamp(w * 0.044, 30, 64));

    // Lightning flash in distant clouds
    if (this.lightning > 0) {
      ctx.save();
      ctx.globalAlpha = this.lightning * 0.18;
      ctx.fillStyle = '#a8e6ff';
      ctx.fillRect(0, 0, w, horizon);
      ctx.restore();
    }

    // Far skyline
    this.drawSkyline(ctx, this.far, '#061020', 'rgba(76, 180, 255, 0.2)', 0.25);
    this.drawCables(ctx);

    // Mid skyline
    this.drawSkyline(ctx, this.mid, '#040b16', 'rgba(255, 185, 96, 0.22)', 0.55);
    this.drawNeonSigns(ctx);

    // Fog / horizon glow
    const fog = ctx.createLinearGradient(0, horizon - 70, 0, horizon + 8);
    fog.addColorStop(0, 'rgba(30, 108, 178, 0)');
    fog.addColorStop(0.7, 'rgba(30, 108, 178, 0.1)');
    fog.addColorStop(1, 'rgba(44, 146, 214, 0.18)');
    ctx.fillStyle = fog;
    ctx.fillRect(0, horizon - 70, w, 78);

    this.drawFloor(ctx);
    this.drawWalls(ctx);
    this.drawRain(ctx);

    // Floating embers
    for (const ember of this.embers) {
      const color = ember.hue === 'cyan' ? 'rgba(100, 240, 255,' : ember.hue === 'pink' ? 'rgba(255, 100, 180,' : 'rgba(255, 200, 110,';
      ctx.fillStyle = `${color}${ember.alpha})`;
      ctx.beginPath();
      ctx.arc(ember.x, ember.y, ember.r, 0, TAU);
      ctx.fill();
    }

    // Ambient vignette glow near arena
    const arenaGlow = ctx.createRadialGradient(w / 2, groundY, 20, w / 2, groundY, w * 0.62);
    arenaGlow.addColorStop(0, 'rgba(60, 180, 255, 0.055)');
    arenaGlow.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.fillStyle = arenaGlow;
    ctx.fillRect(0, groundY - h * 0.5, w, h * 0.5 + 20);
  }

  drawMoon(ctx, x, y, radius) {
    ctx.save();
    const glow = ctx.createRadialGradient(x, y, radius * 0.2, x, y, radius * 3.4);
    glow.addColorStop(0, 'rgba(160, 230, 255, 0.16)');
    glow.addColorStop(0.4, 'rgba(110, 190, 255, 0.06)');
    glow.addColorStop(1, 'rgba(60, 130, 255, 0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(x, y, radius * 3.4, 0, TAU);
    ctx.fill();

    ctx.globalCompositeOperation = 'lighter';
    const body = ctx.createRadialGradient(x - radius * 0.3, y - radius * 0.3, radius * 0.1, x, y, radius);
    body.addColorStop(0, 'rgba(230, 252, 255, 0.95)');
    body.addColorStop(0.6, 'rgba(158, 222, 244, 0.82)');
    body.addColorStop(1, 'rgba(84, 142, 182, 0.5)');
    ctx.fillStyle = body;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, TAU);
    ctx.fill();

    ctx.globalAlpha = 0.18;
    ctx.fillStyle = '#4b7a9d';
    const craters = [
      [-0.28, -0.15, 0.22],
      [0.2, 0.24, 0.16],
      [0.36, -0.34, 0.1],
      [-0.05, 0.42, 0.09],
    ];
    for (const [cx, cy, cr] of craters) {
      ctx.beginPath();
      ctx.arc(x + cx * radius, y + cy * radius, cr * radius, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  }

  drawSkyline(ctx, buildings, color, windowColor, heightScale) {
    for (const building of buildings) {
      ctx.fillStyle = color;
      ctx.fillRect(building.x, building.y, building.w, building.h + 10);

      // Top edge highlight
      ctx.fillStyle = 'rgba(90, 180, 255, 0.12)';
      ctx.fillRect(building.x, building.y, building.w, 1);

      if (building.antenna) {
        ctx.strokeStyle = 'rgba(80, 140, 200, 0.35)';
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(building.x + building.w * 0.6, building.y);
        ctx.lineTo(building.x + building.w * 0.6, building.y - 12 - building.h * 0.08);
        ctx.stroke();
        if (Math.sin(this.time * 2 + building.seed) > 0.2) {
          ctx.fillStyle = 'rgba(255, 70, 80, 0.8)';
          ctx.fillRect(building.x + building.w * 0.6 - 1, building.y - 14 - building.h * 0.08, 2, 2);
        }
      }

      if (building.tank) {
        ctx.fillStyle = 'rgba(5, 13, 26, 0.85)';
        const tw = building.w * 0.3;
        ctx.fillRect(building.x + building.w * 0.2, building.y - 10, tw, 10);
        ctx.fillRect(building.x + building.w * 0.23, building.y - 2, 2, 12);
        ctx.fillRect(building.x + building.w * 0.2 + tw - 4, building.y - 2, 2, 12);
      }

      const random = seeded(building.seed);
      const cols = Math.max(1, Math.floor(building.w / 13));
      const rows = Math.max(1, Math.floor(building.h / 16));
      const winW = Math.max(1.5, building.w / cols * 0.36);
      const winH = Math.max(1.4, building.h / rows * 0.3);
      ctx.fillStyle = windowColor;
      for (let row = 0; row < rows; row += 1) {
        for (let col = 0; col < cols; col += 1) {
          if (random() > 0.78) {
            const x = building.x + (col + 0.32) * (building.w / cols);
            const y = building.y + (row + 0.34) * (building.h / rows);
            ctx.globalAlpha = 0.25 + random() * 0.65;
            ctx.fillRect(x, y, winW, winH);
          }
        }
      }
      ctx.globalAlpha = 1;
    }
  }

  drawCables(ctx) {
    for (const cable of this.cables) {
      const midX = (cable.x1 + cable.x2) / 2;
      const midY = (cable.y1 + cable.y2) / 2 + cable.sag;
      ctx.strokeStyle = 'rgba(2, 4, 8, 0.85)';
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(cable.x1, cable.y1);
      ctx.quadraticCurveTo(midX, midY, cable.x2, cable.y2);
      ctx.stroke();
      for (let i = 1; i < 5; i += 1) {
        const t = i / 5;
        const x = (1 - t) * (1 - t) * cable.x1 + 2 * (1 - t) * t * midX + t * t * cable.x2;
        const y = (1 - t) * (1 - t) * cable.y1 + 2 * (1 - t) * t * midY + t * t * cable.y2;
        ctx.fillStyle = i % 2 ? 'rgba(57, 245, 255, 0.5)' : 'rgba(255, 62, 165, 0.4)';
        ctx.beginPath();
        ctx.arc(x, y + 4, 1.4, 0, TAU);
        ctx.fill();
      }
    }
  }

  drawNeonSigns(ctx) {
    const { w, groundY } = this;
    const bob = Math.sin(this.time * 1.4) * 2;

    // Vertical magenta kanji-style sign
    this.drawVerticalSign(ctx, w * 0.135, groundY - 322 + bob, 42, 142, ['雷', '光', '拳'], '#ff3ea5', 0.85);
    // Vertical cyan sign
    this.drawVerticalSign(ctx, w * 0.845, groundY - 260 - bob, 34, 108, ['N', 'E', 'O', 'N'], '#39f5ff', 0.5);

    // Horizontal billboard
    const bx = w * 0.62;
    const by = groundY - 270;
    ctx.save();
    ctx.globalAlpha = 0.6;
    ctx.fillStyle = 'rgba(4, 8, 16, 0.9)';
    ctx.fillRect(bx, by, 132, 34);
    ctx.strokeStyle = 'rgba(255, 211, 77, 0.35)';
    ctx.lineWidth = 1;
    ctx.strokeRect(bx + 0.5, by + 0.5, 131, 33);
    ctx.font = '800 12px "Bahnschrift", "Arial Black", sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = 'rgba(255, 211, 77, 0.85)';
    ctx.shadowColor = 'rgba(255, 180, 40, 0.8)';
    ctx.shadowBlur = 12;
    ctx.fillText('FIGHT / 24H', bx + 66, by + 18);
    ctx.restore();

    // Small red panes
    for (let i = 0; i < 3; i += 1) {
      ctx.fillStyle = 'rgba(255, 60, 90, 0.22)';
      const x = w * (0.29 + i * 0.035);
      ctx.fillRect(x, groundY - 185 - i * 9, 4, 4);
    }
  }

  drawVerticalSign(ctx, x, y, width, height, glyphs, color, alpha) {
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.fillStyle = 'rgba(3, 6, 13, 0.92)';
    ctx.fillRect(x, y, width, height);
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.shadowColor = color;
    ctx.shadowBlur = 12;
    ctx.strokeRect(x + 0.5, y + 0.5, width - 1, height - 1);
    ctx.font = `700 ${width * 0.58}px "Bahnschrift", "Arial Black", "Noto Sans CJK JP", sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = color;
    const step = height / glyphs.length;
    glyphs.forEach((glyph, index) => {
      const flicker = Math.sin(this.time * 9 + index * 2.3) > 0.94 ? 0.3 : 1;
      ctx.globalAlpha = alpha * flicker;
      ctx.fillText(glyph, x + width / 2, y + step * (index + 0.55));
    });
    ctx.restore();
  }

  drawFloor(ctx) {
    const { w, h, groundY, left, right } = this;

    // Floor base
    const floor = ctx.createLinearGradient(0, groundY, 0, h);
    floor.addColorStop(0, '#10192b');
    floor.addColorStop(0.12, '#0a1221');
    floor.addColorStop(0.65, '#060b15');
    floor.addColorStop(1, '#03060d');
    ctx.fillStyle = floor;
    ctx.fillRect(0, groundY, w, h - groundY);

    // Warm reflected light from city
    const reflected = ctx.createLinearGradient(0, groundY, 0, h);
    reflected.addColorStop(0, 'rgba(52, 130, 200, 0.13)');
    reflected.addColorStop(0.5, 'rgba(24, 82, 150, 0.03)');
    reflected.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.fillStyle = reflected;
    ctx.fillRect(0, groundY, w, h - groundY);

    // Puddles
    for (const puddle of this.puddles) {
      const gradient = ctx.createRadialGradient(puddle.x, puddle.y, 2, puddle.x, puddle.y, puddle.rx);
      gradient.addColorStop(0, `${puddle.color}${Math.round(puddle.alpha * 255).toString(16).padStart(2, '0')}`);
      gradient.addColorStop(1, `${puddle.color}00`);
      ctx.fillStyle = gradient;
      ctx.beginPath();
      ctx.ellipse(puddle.x, puddle.y, puddle.rx, puddle.ry, 0, 0, TAU);
      ctx.fill();
    }

    // Perspective floor seams
    ctx.strokeStyle = 'rgba(93, 165, 230, 0.055)';
    ctx.lineWidth = 1;
    const vanishingX = w / 2;
    for (let i = 0; i <= 14; i += 1) {
      const t = i / 14;
      const x = left - (w * 0.25) + t * (right - left + w * 0.5);
      ctx.beginPath();
      ctx.moveTo(vanishingX + (x - vanishingX) * 0.08, groundY + 2);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    for (let i = 1; i <= 5; i += 1) {
      const t = i / 6;
      const y = groundY + (h - groundY) * t * t;
      ctx.globalAlpha = 0.6;
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
    ctx.globalAlpha = 1;

    // Cracks
    ctx.strokeStyle = 'rgba(2, 4, 9, 0.8)';
    ctx.lineWidth = 1.3;
    for (const crack of this.cracks) {
      ctx.beginPath();
      ctx.moveTo(crack.x, crack.y);
      ctx.lineTo(crack.x + Math.cos(crack.angle) * crack.len, crack.y + Math.sin(crack.angle) * crack.len * 0.22);
      if (crack.fork) {
        ctx.moveTo(crack.x + Math.cos(crack.angle) * crack.len * 0.5, crack.y + Math.sin(crack.angle) * crack.len * 0.11);
        ctx.lineTo(crack.x + Math.cos(crack.angle + 0.6) * crack.len * 0.7, crack.y + Math.sin(crack.angle + 0.6) * crack.len * 0.2);
      }
      ctx.stroke();
    }

    // Ground edge line
    const edge = ctx.createLinearGradient(0, groundY, w, groundY);
    edge.addColorStop(0, 'rgba(57, 245, 255, 0.1)');
    edge.addColorStop(0.18, 'rgba(57, 245, 255, 0.7)');
    edge.addColorStop(0.5, 'rgba(140, 250, 255, 0.92)');
    edge.addColorStop(0.82, 'rgba(57, 245, 255, 0.7)');
    edge.addColorStop(1, 'rgba(57, 245, 255, 0.1)');
    ctx.save();
    ctx.shadowColor = 'rgba(57, 245, 255, 0.7)';
    ctx.shadowBlur = 16;
    ctx.fillStyle = edge;
    ctx.fillRect(left - 10, groundY - 1, right - left + 20, 2);
    ctx.restore();

    // Hazard edge strips
    this.drawHazard(ctx, left - 40, groundY + 7, 42, 7);
    this.drawHazard(ctx, right, groundY + 7, 42, 7);

    // Floor reflection of neon
    const centerGlow = ctx.createRadialGradient(w / 2, groundY + 14, 10, w / 2, groundY + 14, w * 0.34);
    centerGlow.addColorStop(0, 'rgba(68, 220, 255, 0.1)');
    centerGlow.addColorStop(1, 'rgba(68, 220, 255, 0)');
    ctx.fillStyle = centerGlow;
    ctx.beginPath();
    ctx.ellipse(w / 2, groundY + 22, w * 0.34, 34, 0, 0, TAU);
    ctx.fill();
  }

  drawHazard(ctx, x, y, width, height) {
    ctx.save();
    ctx.beginPath();
    ctx.rect(x, y, width, height);
    ctx.clip();
    ctx.fillStyle = 'rgba(255, 203, 54, 0.22)';
    ctx.fillRect(x, y, width, height);
    ctx.fillStyle = 'rgba(8, 10, 14, 0.7)';
    for (let i = -height; i < width + height; i += 12) {
      ctx.beginPath();
      ctx.moveTo(x + i, y + height);
      ctx.lineTo(x + i + height, y);
      ctx.lineTo(x + i + height + 6, y);
      ctx.lineTo(x + i + 6, y + height);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }

  drawWalls(ctx) {
    const { w, groundY, left, right } = this;

    // Physical wall blocks on both sides (outside the playable arena)
    const wallGradient = ctx.createLinearGradient(0, 0, left, 0);
    wallGradient.addColorStop(0, 'rgba(4, 8, 16, 0.96)');
    wallGradient.addColorStop(1, 'rgba(9, 18, 34, 0.85)');
    ctx.fillStyle = wallGradient;
    ctx.fillRect(0, groundY - 420, left, 424);
    const wallGradientR = ctx.createLinearGradient(right, 0, w, 0);
    wallGradientR.addColorStop(0, 'rgba(9, 18, 34, 0.85)');
    wallGradientR.addColorStop(1, 'rgba(4, 8, 16, 0.96)');
    ctx.fillStyle = wallGradientR;
    ctx.fillRect(right, groundY - 420, w - right, 424);

    // Wall panels & rivets
    ctx.strokeStyle = 'rgba(120, 170, 220, 0.07)';
    ctx.lineWidth = 1;
    for (let y = groundY - 400; y < groundY; y += 44) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(left, y);
      ctx.moveTo(right, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }

    // Energy barrier edges
    this.drawBarrier(ctx, left, groundY, 'left', this.wallPulse.left);
    this.drawBarrier(ctx, right, groundY, 'right', this.wallPulse.right);

    // Vertical neon rails
    const railLength = Math.min(360, groundY - 40);
    ctx.save();
    ctx.shadowColor = 'rgba(57,245,255,.8)';
    ctx.shadowBlur = 14;
    const railGradient = ctx.createLinearGradient(0, groundY - railLength, 0, groundY);
    railGradient.addColorStop(0, 'rgba(57,245,255,0)');
    railGradient.addColorStop(0.55, 'rgba(57,245,255,.4)');
    railGradient.addColorStop(1, 'rgba(180,255,255,.9)');
    ctx.fillStyle = railGradient;
    ctx.fillRect(left - 2, groundY - railLength, 2, railLength);
    ctx.fillRect(right, groundY - railLength, 2, railLength);
    ctx.restore();

    // Wall graffiti / signage
    ctx.save();
    ctx.translate(left + 13, groundY - 115);
    ctx.rotate(-Math.PI / 2);
    ctx.font = '900 10px "Bahnschrift", "Arial Black", sans-serif';
    ctx.letterSpacing = '4px';
    ctx.fillStyle = 'rgba(255, 62, 165, 0.35)';
    ctx.fillText('NO EXIT', 0, 0);
    ctx.restore();

    ctx.save();
    ctx.translate(right - 15, groundY - 150);
    ctx.rotate(Math.PI / 2);
    ctx.font = '900 9px "Bahnschrift", "Arial Black", sans-serif';
    ctx.fillStyle = 'rgba(57, 245, 255, 0.3)';
    ctx.fillText('ARENA LIMIT', 0, 0);
    ctx.restore();
  }

  drawBarrier(ctx, x, groundY, side, pulseAmount) {
    const height = 200;
    const dir = side === 'left' ? 1 : -1;
    const base = 0.06 + pulseAmount * 0.5;
    ctx.save();
    const gradient = ctx.createLinearGradient(x, groundY - height, x, groundY);
    gradient.addColorStop(0, `rgba(57,245,255,0)`);
    gradient.addColorStop(0.7, `rgba(57,245,255,${base * 0.5})`);
    gradient.addColorStop(1, `rgba(120,250,255,${base})`);
    ctx.fillStyle = gradient;
    const width = 22 + pulseAmount * 24;
    ctx.fillRect(x - (side === 'right' ? width : 0), groundY - height, width, height);

    // Energy scan lines
    ctx.strokeStyle = `rgba(120, 250, 255, ${0.08 + pulseAmount * 0.6})`;
    ctx.lineWidth = 1;
    for (let i = 0; i < 6; i += 1) {
      const offset = ((this.time * 60 + i * 34) % height);
      const y = groundY - offset;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x + dir * (24 + pulseAmount * 30), y - 4);
      ctx.stroke();
    }

    if (pulseAmount > 0.1) {
      ctx.strokeStyle = `rgba(160, 252, 255, ${pulseAmount * 0.8})`;
      ctx.lineWidth = 2;
      ctx.shadowColor = '#39f5ff';
      ctx.shadowBlur = 18;
      ctx.beginPath();
      for (let i = 0; i <= 12; i += 1) {
        const y = groundY - (i / 12) * height;
        const jitter = Math.sin(this.time * 50 + i * 2.7) * pulseAmount * 8;
        if (i === 0) ctx.moveTo(x + jitter, y);
        else ctx.lineTo(x + jitter, y);
      }
      ctx.stroke();
    }
    ctx.restore();
  }

  drawRain(ctx) {
    ctx.save();
    ctx.strokeStyle = 'rgba(140, 205, 255, 0.4)';
    ctx.lineWidth = 0.8;
    for (const drop of this.rain) {
      ctx.globalAlpha = drop.alpha;
      ctx.beginPath();
      ctx.moveTo(drop.x, drop.y);
      ctx.lineTo(drop.x - drop.len * 0.14, drop.y + drop.len);
      ctx.stroke();
    }
    ctx.restore();
  }

  drawForeground(ctx) {
    const { w, h, groundY } = this;
    // Low foreground haze
    const foreground = ctx.createLinearGradient(0, h - 100, 0, h);
    foreground.addColorStop(0, 'rgba(2, 4, 10, 0)');
    foreground.addColorStop(1, 'rgba(1, 3, 8, 0.62)');
    ctx.fillStyle = foreground;
    ctx.fillRect(0, h - 100, w, 100);

    // Rear guardrail, subtle silhouette
    ctx.strokeStyle = 'rgba(4, 8, 15, 0.9)';
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(0, groundY + 74);
    ctx.lineTo(w, groundY + 74);
    ctx.stroke();
    ctx.strokeStyle = 'rgba(57, 245, 255, 0.06)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, groundY + 66);
    ctx.lineTo(w, groundY + 66);
    ctx.stroke();
    for (let x = 22; x < w; x += 118) {
      ctx.strokeStyle = 'rgba(3, 6, 12, 0.8)';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(x, groundY + 62);
      ctx.lineTo(x, groundY + 76);
      ctx.stroke();
    }
  }
}

import { TAU, clamp, lerp, easeOutCubic, easeOutQuint, easeInCubic, span } from './utils.js';

const BASE_HIP = -54;
const TORSO = 43;
const NECK = 51;
const HEAD_RADIUS = 13;
const UPPER_ARM = 24;
const FOREARM = 23;
const THIGH = 28;
const SHIN = 28;

function basePose() {
  return {
    hipX: 0,
    hipY: BASE_HIP,
    lean: 0.03,
    headTilt: 0,
    armFront: [0.2, 0.06],
    armBack: [-0.15, 0.1],
    legFront: [0.18, -0.15],
    legBack: [-0.18, 0.13],
    rotation: 0,
    rotationPivot: -58,
    scarf: 0,
    headScale: 1,
  };
}

function poseFor(char) {
  const pose = basePose();
  const t = char.animTime;
  const state = char.state;
  const p = char.stateDuration > 0 ? clamp(char.stateTime / char.stateDuration, 0, 1) : 0;

  if (state === 'idle') {
    const breath = Math.sin(t * 2.8) * 0.9;
    pose.hipY = BASE_HIP + breath * 0.35;
    pose.lean = 0.03 + Math.sin(t * 2.8) * 0.008;
    pose.armFront = [0.22 + Math.sin(t * 2.8) * 0.035, 0.05];
    pose.armBack = [-0.14 - Math.sin(t * 2.8) * 0.035, 0.13];
    pose.headTilt = Math.sin(t * 1.7) * 0.03;
  } else if (state === 'run') {
    const phase = t * 13.2;
    const swing = Math.sin(phase);
    pose.hipY = BASE_HIP - 7 + Math.abs(Math.cos(phase)) * 2.2;
    pose.lean = 0.22;
    pose.headTilt = 0.06;
    pose.legFront = [0.72 * swing, -0.42 - Math.max(0, -swing) * 0.55];
    pose.legBack = [-0.72 * swing, -0.42 - Math.max(0, swing) * 0.55];
    pose.armFront = [-0.85 * swing, -0.85 * swing + 0.85];
    pose.armBack = [0.85 * swing, 0.85 * swing + 0.85];
    pose.scarf = clamp(-swing, 0, 1);
  } else if (state === 'jump' || state === 'fall') {
    const rising = state === 'jump';
    pose.hipY = BASE_HIP - 4;
    pose.lean = rising ? 0.14 : -0.05;
    pose.legFront = rising ? [0.85, -0.72] : [0.5, -0.35];
    pose.legBack = rising ? [-0.35, 0.45] : [-0.45, 0.35];
    pose.armFront = rising ? [0.85, 1.25] : [0.55, 0.8];
    pose.armBack = rising ? [-0.55, -0.85] : [-0.7, -0.5];
    pose.scarf = 1;
  } else if (state === 'crouch') {
    pose.hipY = -36;
    pose.lean = 0.36;
    pose.headTilt = 0.13;
    pose.legFront = [1.02, 0.72];
    pose.legBack = [-0.98, -0.7];
    pose.armFront = [0.55, 1.2];
    pose.armBack = [-0.25, -0.7];
    pose.headScale = 1.02;
  } else if (state === 'wall') {
    pose.hipY = BASE_HIP - 1;
    pose.lean = -0.18;
    pose.legFront = [0.5, 0.12];
    pose.legBack = [-0.22, 0.42];
    pose.armFront = [1.05, 1.45];
    pose.armBack = [-1.75, -1.35];
    pose.headTilt = -0.1;
    pose.scarf = 0.5;
  } else if (state === 'attack' || state === 'heavy') {
    const kind = char.attackKind || state;
    const strike = kind === 'heavy' ? span(p, 0.42, 0.58) : span(p, 0.18, 0.42);
    const recover = kind === 'heavy' ? span(p, 0.62, 1) : span(p, 0.5, 1);
    const windup = kind === 'heavy' ? span(p, 0, 0.4) : span(p, 0, 0.18);
    const extend = easeOutCubic(strike) * (1 - easeInCubic(recover));
    const coil = easeOutCubic(windup) * (1 - easeOutCubic(strike));
    const alternate = (char.attackChain || 0) % 2;
    const isFront = alternate === 0;
    const punchAngle = kind === 'heavy' ? 1.5 : 1.56;
    const windAngle = kind === 'heavy' ? -1.25 : -0.85;

    pose.lean = 0.08 + coil * -0.2 + extend * 0.3;
    pose.hipY = BASE_HIP + extend * 2;
    const punchingArm = [lerp(windAngle, punchAngle, extend), lerp(windAngle + 0.6, punchAngle, extend)];
    const guardArm = [lerp(-0.1, -0.55, extend), lerp(0.5, -0.2, extend)];
    if (isFront) {
      pose.armFront = punchingArm;
      pose.armBack = guardArm;
    } else {
      pose.armBack = punchingArm;
      pose.armFront = guardArm;
    }
    if (kind === 'heavy') {
      pose.hipY = BASE_HIP + 1;
      pose.legFront = [0.35 + extend * 0.2, -0.15];
      pose.legBack = [-0.45 - extend * 0.25, 0.1];
      pose.rotation = 0;
      pose.headTilt = 0.08;
    } else {
      pose.legFront = [0.22, -0.2];
      pose.legBack = [-0.25, 0.14];
    }
    pose.scarf = extend;
  } else if (state === 'dragon') {
    const rise = easeOutQuint(span(p, 0.12, 0.58));
    const land = easeInCubic(span(p, 0.7, 1));
    pose.hipY = BASE_HIP + 8 - rise * 4 + land * 2;
    pose.lean = -0.25 + rise * 0.1;
    pose.armFront = [lerp(-0.5, 2.55, rise), lerp(0.2, 2.62, rise)];
    pose.armBack = [lerp(-0.8, -0.25, rise), lerp(-1.3, -0.7, rise)];
    pose.legFront = [0.15 + rise * 0.4, -0.4 - rise * 0.3];
    pose.legBack = [-0.4, 0.55];
    pose.headTilt = -0.08 * rise;
    pose.scarf = 1;
  } else if (state === 'spin') {
    pose.rotation = char.spinAngle || 0;
    pose.rotationPivot = -58;
    pose.hipY = BASE_HIP - 6;
    pose.lean = 0.16;
    pose.armFront = [1.55, 1.75];
    pose.armBack = [-1.5, -1.72];
    pose.legFront = [0.75, 0.35];
    pose.legBack = [-0.9, -0.5];
    pose.scarf = 1;
  } else if (state === 'dive') {
    pose.rotation = 0.42;
    pose.rotationPivot = -60;
    pose.hipY = BASE_HIP - 2;
    pose.lean = 0.22;
    pose.armFront = [1.8, 2.15];
    pose.armBack = [-1.4, -1.05];
    pose.legFront = [1.22, 1.5];
    pose.legBack = [-0.8, -0.35];
    pose.headTilt = 0.1;
    pose.scarf = 1;
  } else if (state === 'grab' || state === 'airgrab') {
    pose.hipY = BASE_HIP - 1;
    pose.lean = 0.15;
    pose.armFront = [1.5, 1.62];
    pose.armBack = [1.1, 1.5];
    pose.legFront = [0.35, -0.3];
    pose.legBack = [-0.4, 0.2];
    pose.headTilt = 0.04;
  } else if (state === 'throw') {
    const wind = span(p, 0, 0.24);
    const launch = span(p, 0.24, 0.48);
    const follow = span(p, 0.55, 1);
    pose.lean = 0.1 - easeOutCubic(wind) * 0.3 + easeOutCubic(launch) * 0.55 - follow * 0.2;
    pose.armFront = [lerp(-1.2, 1.75, easeOutQuint(launch)), lerp(-0.8, 1.7, easeOutQuint(launch))];
    pose.armBack = [-0.6, -0.2];
    pose.legFront = [0.35 + launch * 0.25, -0.2];
    pose.legBack = [-0.5, 0.2];
    pose.headTilt = 0.1;
    pose.scarf = 1;
  } else if (state === 'suplex') {
    pose.rotation = lerp(0.05, -0.55, easeOutCubic(span(p, 0, 0.5)));
    pose.rotationPivot = -58;
    pose.hipY = BASE_HIP;
    pose.lean = 0.35;
    pose.armFront = [2.5, 2.8];
    pose.armBack = [2.35, 2.7];
    pose.legFront = [0.75, 0.5];
    pose.legBack = [-0.5, -0.2];
    pose.headTilt = 0.1;
    pose.scarf = 1;
  } else if (state === 'special') {
    const charge = easeOutCubic(span(p, 0, 0.18));
    const kick = easeOutCubic(span(p, 0.14, 0.42));
    const settle = easeInCubic(span(p, 0.72, 1));
    pose.hipY = BASE_HIP - 14 * kick + settle * 6;
    pose.lean = -0.18 + kick * 0.45;
    pose.rotation = charge * 0.06;
    pose.armFront = [lerp(-1.0, -0.35, kick), lerp(0.8, 1.1, kick)];
    pose.armBack = [lerp(1.2, -1.4, kick), lerp(1.5, -1.0, kick)];
    pose.legFront = [lerp(0.2, 1.55, kick), lerp(-0.2, 1.62, kick)];
    pose.legBack = [lerp(-0.3, -0.55, kick), lerp(0.1, -0.25, kick)];
    pose.headTilt = 0.12;
    pose.scarf = 1;
  } else if (state === 'hurt') {
    const recoil = 1 - easeOutCubic(span(p, 0, 0.7));
    pose.hipY = BASE_HIP + recoil * 3;
    pose.lean = -0.45 * recoil;
    pose.armFront = [-0.8, -1.25];
    pose.armBack = [-1.1, -1.5];
    pose.legFront = [0.5, 0.25];
    pose.legBack = [-0.35, -0.15];
    pose.headTilt = -0.18 * recoil;
  } else if (state === 'ragdoll' || state === 'dead') {
    const flail = t * 18 + (char.seed || 0);
    pose.hipY = BASE_HIP;
    pose.lean = 0.1;
    pose.rotation = char.rot || 0;
    pose.rotationPivot = -58;
    pose.armFront = [0.8 + Math.sin(flail) * 0.7, 1.2 + Math.sin(flail + 1.7) * 0.9];
    pose.armBack = [-0.9 + Math.sin(flail + 2.1) * 0.65, -1.4 + Math.sin(flail + 0.8) * 0.8];
    pose.legFront = [0.65 + Math.sin(flail + 1.2) * 0.55, 0.25 + Math.sin(flail + 2.6) * 0.6];
    pose.legBack = [-0.7 + Math.sin(flail + 2.5) * 0.5, -0.25 + Math.sin(flail + 0.3) * 0.55];
  } else if (state === 'grabbed') {
    const struggle = Math.sin(t * 24 + (char.seed || 0));
    pose.hipY = -52;
    pose.lean = -0.15 + struggle * 0.08;
    pose.armFront = [1.1 + struggle * 0.4, 1.8 + struggle * 0.3];
    pose.armBack = [-1.2 - struggle * 0.3, -1.8 - struggle * 0.2];
    pose.legFront = [0.7 + struggle * 0.25, 0.9];
    pose.legBack = [-0.6 + struggle * 0.25, 0.7];
    pose.headTilt = -0.15;
  } else if (state === 'taunt') {
    pose.hipY = BASE_HIP;
    pose.lean = -0.08;
    pose.armFront = [2.3, 2.8];
    pose.armBack = [-0.4, -0.1];
    pose.legFront = [0.25, -0.2];
    pose.legBack = [-0.25, 0.15];
    pose.headTilt = -0.08;
  }

  return pose;
}

function pointFrom(origin, angle, length) {
  return {
    x: origin.x + Math.sin(angle) * length,
    y: origin.y + Math.cos(angle) * length,
  };
}

function buildSkeleton(char, pose) {
  const hip = { x: pose.hipX, y: pose.hipY };
  const chest = { x: hip.x + pose.lean * 20, y: hip.y - TORSO * 0.66 };
  const neck = { x: hip.x + pose.lean * TORSO, y: hip.y - NECK };
  const head = { x: neck.x + pose.lean * 11 + pose.headTilt * 8, y: neck.y - 16 };
  const shoulder = { x: neck.x, y: neck.y + 1 };

  const kneeF = pointFrom(hip, pose.legFront[0], THIGH);
  const footF = pointFrom(kneeF, pose.legFront[1], SHIN);
  const kneeB = pointFrom(hip, pose.legBack[0], THIGH);
  const footB = pointFrom(kneeB, pose.legBack[1], SHIN);

  const elbowF = pointFrom(shoulder, pose.armFront[0], UPPER_ARM);
  const handF = pointFrom(elbowF, pose.armFront[1], FOREARM);
  const elbowB = pointFrom(shoulder, pose.armBack[0], UPPER_ARM);
  const handB = pointFrom(elbowB, pose.armBack[1], FOREARM);

  return { hip, chest, neck, head, shoulder, kneeF, footF, kneeB, footB, elbowF, handF, elbowB, handB };
}

function polyline(ctx, points, width, color, alpha = 1) {
  ctx.globalAlpha = alpha;
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(points[0].x, points[0].y);
  for (let i = 1; i < points.length; i += 1) ctx.lineTo(points[i].x, points[i].y);
  ctx.stroke();
  ctx.globalAlpha = 1;
}

function drawLimb(ctx, a, b, c, width, color, outline, alpha, jointColor) {
  ctx.globalAlpha = alpha;
  ctx.strokeStyle = outline;
  ctx.lineWidth = width + 4.5;
  ctx.beginPath();
  ctx.moveTo(a.x, a.y);
  ctx.lineTo(b.x, b.y);
  ctx.lineTo(c.x, c.y);
  ctx.stroke();

  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.beginPath();
  ctx.moveTo(a.x, a.y);
  ctx.lineTo(b.x, b.y);
  ctx.lineTo(c.x, c.y);
  ctx.stroke();

  if (jointColor) {
    ctx.fillStyle = jointColor;
    ctx.beginPath();
    ctx.arc(b.x, b.y, width * 0.46, 0, TAU);
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

export function drawStickman(ctx, char, view = {}) {
  const scale = char.scale || 1;
  const groundY = view.groundY || 0;
  const heightAbove = Math.max(0, groundY - char.y);
  const shadowScale = clamp(1 - heightAbove / 430, 0.3, 1);
  const airborne = char.y < groundY - 1 || (!char.onGround && char.state !== 'ragdoll' && char.state !== 'dead');

  // Ground shadow
  if (char.state !== 'grabbed') {
    ctx.save();
    ctx.globalAlpha = 0.35 * shadowScale;
    ctx.fillStyle = '#00040c';
    ctx.beginPath();
    ctx.ellipse(char.x, groundY + 2, 28 * scale * shadowScale, 6.2 * scale * shadowScale, 0, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  if (char.state === 'dead' && char.alpha <= 0.01) return;

  const palette = char.palette;
  const flash = char.flash > 0;
  const main = flash ? '#ffffff' : palette.main;
  const light = flash ? '#ffffff' : palette.light;
  const dark = palette.outline;
  const accent = flash ? '#ffffff' : palette.accent;
  const pose = poseFor(char);
  const joints = buildSkeleton(char, pose);
  const alpha = char.alpha === undefined ? 1 : char.alpha;

  // Aura / glow behind body
  if (char.aura !== false) {
    const auraRadius = 56 * scale * (char.auraScale || 1);
    const aura = ctx.createRadialGradient(char.x, char.y - 58 * scale, 2, char.x, char.y - 58 * scale, auraRadius);
    aura.addColorStop(0, `${palette.glow}${char.player ? '38' : '18'}`);
    aura.addColorStop(1, `${palette.glow}00`);
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.fillStyle = aura;
    ctx.globalAlpha = alpha;
    ctx.beginPath();
    ctx.arc(char.x, char.y - 58 * scale, auraRadius, 0, TAU);
    ctx.fill();
    ctx.restore();
  }

  ctx.save();
  ctx.translate(char.x, char.y);
  ctx.scale((char.facing || 1) * scale, scale);
  ctx.globalAlpha = alpha;
  if (pose.rotation) {
    ctx.translate(0, pose.rotationPivot);
    ctx.rotate(pose.rotation);
    ctx.translate(0, -pose.rotationPivot);
  }

  // Energy scarf / ribbon for the player
  if (char.scarf !== false && (char.player || char.state === 'special')) {
    const speed = clamp(Math.abs(char.vx || 0) / 360, 0, 1);
    const wave = Math.sin((char.animTime || 0) * 8) * 4;
    const length = 34 + speed * 34;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = accent;
    ctx.lineWidth = 4;
    ctx.shadowColor = accent;
    ctx.shadowBlur = 14;
    ctx.beginPath();
    ctx.moveTo(joints.neck.x - 2, joints.neck.y + 7);
    ctx.quadraticCurveTo(-16 - speed * 12, joints.neck.y + 16 + wave * 0.4, -length, joints.neck.y + 24 + wave);
    ctx.stroke();
    ctx.strokeStyle = light;
    ctx.lineWidth = 1.6;
    ctx.stroke();
    ctx.restore();
  }

  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';

  const bodyWidth = char.heavy ? 7.2 : 6.2;
  const backAlpha = char.state === 'dead' ? 0.65 : 0.82;

  // Back arm & leg
  drawLimb(ctx, joints.shoulder, joints.elbowB, joints.handB, bodyWidth * 0.82, dark, dark, backAlpha);
  drawLimb(ctx, joints.hip, joints.kneeB, joints.footB, bodyWidth * 0.98, palette.back, dark, backAlpha);

  // Torso
  ctx.save();
  ctx.strokeStyle = dark;
  ctx.lineWidth = bodyWidth + 5;
  ctx.beginPath();
  ctx.moveTo(joints.hip.x, joints.hip.y);
  ctx.lineTo(joints.chest.x, joints.chest.y);
  ctx.lineTo(joints.neck.x, joints.neck.y);
  ctx.stroke();
  if (char.player) {
    ctx.strokeStyle = main;
    ctx.lineWidth = bodyWidth + 1;
    ctx.shadowColor = palette.glow;
    ctx.shadowBlur = 13;
  } else {
    ctx.strokeStyle = main;
    ctx.lineWidth = bodyWidth;
    ctx.shadowColor = palette.glow;
    ctx.shadowBlur = 7;
  }
  ctx.beginPath();
  ctx.moveTo(joints.hip.x, joints.hip.y);
  ctx.lineTo(joints.chest.x, joints.chest.y);
  ctx.lineTo(joints.neck.x, joints.neck.y);
  ctx.stroke();
  ctx.restore();

  // Chest core light
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.fillStyle = accent;
  ctx.globalAlpha = 0.5 + Math.sin((char.animTime || 0) * 5) * 0.12;
  ctx.beginPath();
  ctx.arc(joints.chest.x + 2, joints.chest.y + 1, char.heavy ? 3.4 : 2.6, 0, TAU);
  ctx.fill();
  ctx.restore();

  // Front leg
  drawLimb(ctx, joints.hip, joints.kneeF, joints.footF, bodyWidth * 1.04, main, dark, 1, accent);

  // Head
  ctx.save();
  ctx.translate(joints.head.x, joints.head.y);
  ctx.rotate(pose.headTilt * 0.5);
  ctx.scale(pose.headScale, pose.headScale);
  ctx.fillStyle = char.player ? 'rgba(3, 22, 32, 0.95)' : 'rgba(8, 6, 12, 0.95)';
  ctx.strokeStyle = dark;
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(0, 0, HEAD_RADIUS + 2.2, 0, TAU);
  ctx.fill();
  ctx.stroke();

  ctx.shadowColor = palette.glow;
  ctx.shadowBlur = char.player ? 16 : 8;
  ctx.strokeStyle = light;
  ctx.lineWidth = 2.1;
  ctx.beginPath();
  ctx.arc(0, 0, HEAD_RADIUS, 0, TAU);
  ctx.stroke();

  // Visor / eye
  ctx.shadowBlur = 10;
  ctx.fillStyle = light;
  if (char.player) {
    ctx.beginPath();
    ctx.roundRect(1.5, -3.8, 8.5, 2.6, 1.3);
    ctx.fill();
  } else if (char.heavy) {
    ctx.beginPath();
    ctx.moveTo(-4.5, -3.5);
    ctx.lineTo(6.5, -1.5);
    ctx.lineTo(-4.5, 1.2);
    ctx.closePath();
    ctx.fill();
  } else {
    ctx.beginPath();
    ctx.arc(4.2, -2.2, 1.9, 0, TAU);
    ctx.fill();
  }
  ctx.restore();

  // Front arm
  drawLimb(ctx, joints.shoulder, joints.elbowF, joints.handF, bodyWidth, main, dark, 1, accent);

  // Hand energy for player attacks
  if (char.player && (char.state === 'attack' || char.state === 'heavy' || char.state === 'dragon' || char.state === 'throw')) {
    const progress = char.stateDuration ? char.stateTime / char.stateDuration : 0;
    if (progress > 0.25 && progress < 0.75) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      const glow = ctx.createRadialGradient(joints.handF.x, joints.handF.y, 0, joints.handF.x, joints.handF.y, 18);
      glow.addColorStop(0, 'rgba(220,255,255,.9)');
      glow.addColorStop(0.3, 'rgba(57,245,255,.5)');
      glow.addColorStop(1, 'rgba(57,245,255,0)');
      ctx.fillStyle = glow;
      ctx.beginPath();
      ctx.arc(joints.handF.x, joints.handF.y, 18, 0, TAU);
      ctx.fill();
      ctx.restore();
    }
  }

  // Heavy armor shield
  if (char.armored && char.state !== 'ragdoll' && char.state !== 'dead' && char.state !== 'grabbed') {
    const pulse = 0.5 + Math.sin((char.animTime || 0) * 3.4) * 0.2;
    ctx.save();
    ctx.translate(0, -64);
    ctx.strokeStyle = `rgba(255, 211, 77, ${0.2 + pulse * 0.25})`;
    ctx.fillStyle = `rgba(255, 211, 77, ${(char.shieldFlash > 0 ? 0.18 : 0.035) + pulse * 0.02})`;
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    for (let i = 0; i < 6; i += 1) {
      const angle = (Math.PI / 3) * i - Math.PI / 2;
      const x = Math.cos(angle) * 38;
      const y = Math.sin(angle) * 53;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.closePath();
    ctx.fill();
    ctx.stroke();
    if (char.shieldFlash > 0) {
      ctx.globalAlpha = char.shieldFlash;
      ctx.strokeStyle = '#fff6c8';
      ctx.lineWidth = 2.4;
      ctx.stroke();
    }
    ctx.restore();
  }

  // Electric arcs around player when charged / special
  if (char.player && (char.state === 'special' || char.charged)) {
    const count = char.state === 'special' ? 4 : 2;
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    ctx.strokeStyle = 'rgba(140,250,255,.8)';
    ctx.lineWidth = 1.2;
    for (let i = 0; i < count; i += 1) {
      const angle = (char.animTime || 0) * 9 + i * 2.1;
      const radius = 28 + (i % 2) * 10;
      ctx.beginPath();
      ctx.moveTo(Math.cos(angle) * radius, -62 + Math.sin(angle) * radius * 0.8);
      ctx.lineTo(Math.cos(angle + 0.7) * (radius + 9), -62 + Math.sin(angle + 0.7) * (radius + 9));
      ctx.lineTo(Math.cos(angle + 1.2) * radius, -62 + Math.sin(angle + 1.2) * radius * 0.8);
      ctx.stroke();
    }
    ctx.restore();
  }

  ctx.restore();

  // Status UI above enemies
  if (!char.player && char.state !== 'dead' && char.state !== 'grabbed') {
    const barW = char.heavy ? 58 : 43;
    const y = char.y - (char.heavy ? 176 : 148) * scale;
    const x = char.x;
    if (char.state !== 'ragdoll') {
      ctx.save();
      ctx.globalAlpha = 0.85;
      ctx.fillStyle = 'rgba(2, 5, 12, 0.82)';
      ctx.fillRect(x - barW / 2 - 1, y - 1, barW + 2, 6);
      const health = clamp(char.hp / char.maxHp, 0, 1);
      ctx.fillStyle = char.heavy ? '#ffd34d' : '#ff445c';
      ctx.shadowColor = char.heavy ? '#ffd34d' : '#ff445c';
      ctx.shadowBlur = 7;
      ctx.fillRect(x - barW / 2, y, barW * health, 4);
      if (char.heavy) {
        ctx.strokeStyle = 'rgba(255,211,77,.5)';
        ctx.lineWidth = 1;
        ctx.strokeRect(x - barW / 2 - 0.5, y - 0.5, barW + 1, 5);
      }
      ctx.restore();
    }

    if (char.state === 'windup') {
      const bob = Math.sin((char.animTime || 0) * 17) * 2;
      ctx.save();
      ctx.globalAlpha = 0.9;
      ctx.font = '900 19px "Bahnschrift", "Arial Black", sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = char.heavy ? '#ffd34d' : '#ff5566';
      ctx.shadowColor = char.heavy ? '#ffb800' : '#ff2040';
      ctx.shadowBlur = 14;
      ctx.fillText('!', x, y - 18 + bob);
      ctx.restore();
    }
  }
}

import { TAU, clamp, approach, easeOutCubic, rand } from './utils.js';

const PALETTE = {
  main: '#39f5ff',
  light: '#e2ffff',
  accent: '#78d9ff',
  glow: '#39f5ff',
  outline: 'rgba(1, 9, 20, 0.96)',
  back: '#178bb8',
};

export class Player {
  constructor(game, x) {
    this.game = game;
    this.unit = game.unit;
    this.player = true;
    this.isPlayer = true;
    this.id = 'player';
    this.x = x;
    this.y = game.groundY;
    this.vx = 0;
    this.vy = 0;
    this.facing = 1;
    this.scale = 1.06 * this.unit;
    this.maxHp = 100;
    this.hp = 100;
    this.battery = 0;
    this.onGround = true;
    this.state = 'idle';
    this.stateTime = 0;
    this.stateDuration = 0;
    this.animTime = 0;
    this.attackKind = null;
    this.attackChain = 0;
    this.chainTimer = 0;
    this.attackHitSet = new Set();
    this.attackLungeApplied = false;
    this.wallSide = null;
    this.wallTimer = 0;
    this.invuln = 0;
    this.flash = 0;
    this.alpha = 1;
    this.alive = true;
    this.grabTarget = null;
    this.grabTimer = 0;
    this.grabThrowReady = false;
    this.suplexTarget = null;
    this.suplexSlammed = false;
    this.specialWaveDone = false;
    this.specialHits = new Set();
    this.diveHits = new Set();
    this.diveBounces = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.bestCombo = 0;
    this.trailTimer = 0;
    this.landedFrom = 0;
    this.palette = PALETTE;
    this.charged = false;
    this.aura = true;
    this.auraScale = 1;
    this.seed = 7;
    this.radius = 16 * this.unit;
    this.lastState = 'idle';
    this.stunTimer = 0;
  }

  get moveSpeed() {
    return 355 * this.unit;
  }

  get airSpeed() {
    return 300 * this.unit;
  }

  get gravity() {
    return 2180 * this.unit;
  }

  get height() {
    return 140 * this.scale;
  }

  setState(name, duration = 0) {
    this.lastState = this.state;
    this.state = name;
    this.stateTime = 0;
    this.stateDuration = duration;
  }

  addBattery(amount) {
    if (amount <= 0) return;
    const wasCharged = this.battery >= 100;
    this.battery = clamp(this.battery + amount, 0, 100);
    this.charged = this.battery >= 100;
    if (!wasCharged && this.charged) {
      this.game.audio.charged?.();
      this.game.ui.flashBattery();
      this.game.fx.ring(this.x, this.y - 68 * this.unit, {
        color: '#ffd34d',
        maxRadius: 82 * this.unit,
        life: 0.5,
        width: 2.5,
        squash: 0.45,
      });
      this.game.fx.text(this.x, this.y - 160 * this.unit, 'BATERÍA AL 100%', {
        color: '#ffd34d',
        size: 13,
        life: 1.1,
        vy: -35,
      });
    }
  }

  heal(amount) {
    this.hp = clamp(this.hp + amount, 0, this.maxHp);
  }

  resetPosition(x) {
    this.x = x;
    this.y = this.game.groundY;
    this.vx = 0;
    this.vy = 0;
    this.onGround = true;
    this.state = 'idle';
    this.stateTime = 0;
    this.stateDuration = 0;
    this.grabTarget = null;
    this.suplexTarget = null;
    this.wallSide = null;
    this.invuln = 2;
  }

  revive() {
    this.alive = true;
    this.hp = Math.max(1, Math.round(this.maxHp * 0.5));
    this.battery = Math.max(this.battery, 35);
    this.charged = this.battery >= 100;
    this.y = this.game.groundY;
    this.vx = 0;
    this.vy = 0;
    this.onGround = true;
    this.state = 'idle';
    this.stateTime = 0;
    this.stateDuration = 0;
    this.invuln = 2.5;
    this.alpha = 1;
    this.flash = 0;
    this.grabTarget = null;
    this.suplexTarget = null;
    this.combo = 0;
    this.comboTimer = 0;
  }

  update(dt, input) {
    if (!this.alive) {
      this.updateDead(dt);
      return;
    }

    this.animTime += dt;
    this.stateTime += dt;
    this.invuln = Math.max(0, this.invuln - dt);
    this.flash = Math.max(0, this.flash - dt);
    this.chainTimer = Math.max(0, this.chainTimer - dt);
    this.comboTimer = Math.max(0, this.comboTimer - dt);
    this.auraScale = 1 + (this.charged ? Math.sin(this.animTime * 5) * 0.08 : 0);
    if (this.comboTimer <= 0 && this.combo > 0) {
      this.combo = 0;
      this.game.ui.setCombo(0, 0);
    }

    // Timed visual invulnerability flicker
    if (this.invuln > 0 && this.state !== 'special') {
      this.alpha = 0.55 + Math.abs(Math.sin(this.animTime * 28)) * 0.45;
    } else {
      this.alpha = 1;
    }

    this.updateStateLogic(dt, input);
    this.handleInput(dt, input);
    this.updatePhysics(dt, input);
    this.updateAttackHits();
    this.updateHeldEnemy();
    this.updateVisualTrail(dt);

    if (this.state === 'wall') {
      this.game.showContextTip('<b>SALTO DE PARED</b> · pulsa SALTO para la patada descendente', 0.18);
    }
  }

  updateStateLogic(dt, input) {
    const state = this.state;

    if (state === 'wall') {
      this.wallTimer -= dt;
      if (this.wallTimer <= 0 || (this.wallSide === 'left' && input.move > 0) || (this.wallSide === 'right' && input.move < 0)) {
        this.leaveWall();
      }
    }

    if (state === 'grab') {
      this.grabTimer -= dt;
      if (!this.grabTarget || this.grabTarget.state === 'dead' || this.grabTarget.hp <= 0) {
        this.releaseGrab();
      } else if (this.grabTimer <= 0) {
        this.releaseGrab();
      }
      const throwPressed = input.wasPressed('light') || input.wasPressed('heavy') || input.wasPressed('grab') || input.wasPressed('down');
      if (this.grabTarget && throwPressed) {
        this.throwGrab();
      }
      return;
    }

    if (state === 'suplex') {
      this.updateSuplex(dt);
      return;
    }

    if (state === 'special') {
      this.updateSpecial(dt);
      return;
    }

    if (state === 'hurt') {
      if (this.stateTime >= this.stateDuration) {
        this.setState(this.onGround ? 'idle' : 'fall');
      }
      return;
    }

    if (state === 'attack' || state === 'heavy' || state === 'dragon' || state === 'spin' || state === 'throw') {
      const progress = this.stateDuration > 0 ? this.stateTime / this.stateDuration : 1;
      if (this.stateTime >= this.stateDuration) {
        this.chainTimer = 0.68;
        this.setState(this.onGround ? 'idle' : 'fall');
        this.vx *= 0.35;
        this.attackHitSet.clear();
        return;
      }
      // allow a cancel into the next attack or jump late in the recovery
      if (progress < 0.55) return;
    }

    // Crouch handling
    if (this.onGround && input.isDown('down') && ['idle', 'run', 'crouch'].includes(this.state)) {
      if (this.state !== 'crouch') this.setState('crouch');
      this.vx = approach(this.vx, 0, 2800 * this.unit * dt);
      return;
    }
    if (this.state === 'crouch' && !input.isDown('down')) {
      this.setState('idle');
    }
  }

  handleInput(dt, input) {
    if (this.state === 'hurt' || this.state === 'dead' || this.state === 'grab' || this.state === 'suplex') return;
    if (this.state === 'special') return;

    if (this.state === 'wall') {
      if (input.wasPressed('jump')) {
        this.wallJump();
      }
      return;
    }

    // Wall jump can also be triggered if the player is pressed against a wall midair
    if (!this.onGround && (input.wasPressed('jump')) && this.nearWall()) {
      this.wallJump(true);
      return;
    }

    const attacking = ['attack', 'heavy', 'dragon', 'spin', 'throw'].includes(this.state);
    const canAct = ['idle', 'run', 'crouch', 'jump', 'fall', 'dive'].includes(this.state) || attacking;
    if (!canAct) return;

    if (input.wasPressed('special') && this.battery >= 100) {
      this.startSpecial();
      return;
    }

    if (input.wasPressed('grab')) {
      if (this.tryGrab()) return;
      if (!attacking) {
        this.setState('attack', 0.22);
        this.attackKind = 'grabWhiff';
        this.attackHitSet.clear();
        this.game.audio.whoosh(0.5);
      }
      return;
    }

    if (input.wasPressed('jump')) {
      if (this.onGround || this.state === 'crouch') {
        this.jump();
        return;
      }
    }

    if (input.wasPressed('heavy')) {
      if (!this.onGround) {
        this.startAttack('airspin');
      } else if (input.isDown('down')) {
        this.startAttack('dragon');
      } else {
        this.startAttack('heavy');
      }
      return;
    }

    if (input.wasPressed('light')) {
      this.startAttack('light');
    }
  }

  jump() {
    if (!this.onGround) return;
    this.vy = -800 * this.unit;
    this.onGround = false;
    this.setState('jump');
    this.vx = clamp(this.vx * 0.7, -this.moveSpeed, this.moveSpeed);
    this.game.audio.jump();
    this.game.fx.dust(this.x, this.y, 5, 0, '#58c8ff');
    this.game.fx.ring(this.x, this.y, { color: '#39f5ff', maxRadius: 28, life: 0.24, width: 1.4, squash: 0.35 });
  }

  nearWall() {
    const margin = 10 * this.unit;
    return this.x <= this.game.left + this.radius + margin || this.x >= this.game.right - this.radius - margin;
  }

  enterWall(side) {
    if (!this.onGround) return;
    this.wallSide = side;
    this.wallTimer = 1.05;
    this.setState('wall', 1.05);
    this.vx = 0;
    this.facing = side === 'left' ? 1 : -1;
    this.game.showContextTip('<b>SALTO DE PARED</b> · pulsa SALTO para la patada descendente', 2.2);
    this.game.audio.grab();
    const wallX = side === 'left' ? this.game.left : this.game.right;
    this.game.fx.burst(wallX, this.y - 72 * this.unit, {
      count: 8,
      color: '#39f5ff',
      speed: 240,
      angle: side === 'left' ? 0 : Math.PI,
      spread: 1.7,
      gravity: 500,
      size: 2.4,
      life: 0.35,
    });
  }

  leaveWall() {
    if (this.state !== 'wall') return;
    this.setState('idle');
    this.wallSide = null;
    this.wallTimer = 0;
    if (this.x <= this.game.left + this.radius) this.x += 3 * this.unit;
    if (this.x >= this.game.right - this.radius) this.x -= 3 * this.unit;
  }

  wallJump(midair = false) {
    const side = this.wallSide || (this.x < this.game.width / 2 ? 'left' : 'right');
    const toward = side === 'left' ? 1 : -1;
    this.facing = toward;
    this.vy = -640 * this.unit;
    this.vx = toward * 560 * this.unit;
    if (midair) this.y = Math.min(this.y, this.game.groundY - 12);
    this.onGround = false;
    this.wallSide = null;
    this.setState('dive', 4);
    this.diveHits.clear();
    this.diveBounces = 0;
    this.invuln = Math.max(this.invuln, 0.55);
    this.game.audio.whoosh(1.6);
    this.game.audio.jump();
    this.game.fx.ring(this.x, this.y - 55 * this.unit, {
      color: '#d8ffff',
      maxRadius: 74 * this.unit,
      life: 0.3,
      width: 2.6,
      squash: 0.8,
    });
    this.game.fx.burst(this.x, this.y - 55 * this.unit, {
      count: 16,
      color: '#39f5ff',
      speed: 420,
      angle: toward > 0 ? -0.6 : Math.PI + 0.6,
      spread: 1.5,
      gravity: 600,
      size: 3,
      life: 0.45,
    });
    this.game.shake(9, 0.2);
    this.game.hitstop(0.045);
    this.game.ui.banner('PATADA DE REBOTE', 'SALTO DE PARED · IMPACTO DESCENDENTE', 'kicker', 0.7);
  }

  startAttack(kind) {
    const air = !this.onGround;
    let duration = 0.26;
    if (kind === 'light') {
      this.attackChain = this.chainTimer > 0 ? (this.attackChain + 1) % 3 : 0;
      duration = [0.24, 0.23, 0.34][this.attackChain];
      this.setState('attack', duration);
      this.facing = this.facing || 1;
      // small forward step
      this.vx = this.facing * (air ? 80 : 170) * this.unit;
    } else if (kind === 'heavy') {
      this.attackChain = 0;
      duration = 0.46;
      this.setState('heavy', duration);
      this.vx = this.facing * 210 * this.unit;
    } else if (kind === 'dragon') {
      this.attackChain = 0;
      duration = 0.64;
      this.setState('dragon', duration);
      this.vy = -280 * this.unit;
      this.onGround = false;
      this.vx = this.facing * 110 * this.unit;
    } else if (kind === 'airspin') {
      this.attackChain = 0;
      duration = 0.52;
      this.setState('spin', duration);
      this.spinAngle = 0;
      this.vx *= 0.55;
    }
    this.attackKind = kind;
    this.attackHitSet.clear();
    this.attackLungeApplied = false;
    this.game.audio.whoosh(kind === 'heavy' || kind === 'dragon' ? 1.5 : 0.8);
    if (kind === 'dragon') {
      this.game.fx.ring(this.x, this.y, { color: '#ffd34d', maxRadius: 54, life: 0.3, width: 2, squash: 0.35 });
      this.game.fx.burst(this.x, this.y, { count: 9, color: '#ffe47a', speed: 220, angle: -Math.PI / 2, spread: 1.1, gravity: 240, size: 2.4, life: 0.4 });
    }
  }

  updateAttackHits() {
    const state = this.state;
    if (!['attack', 'heavy', 'dragon', 'spin', 'dive'].includes(state)) return;
    const progress = this.stateDuration > 0 ? this.stateTime / this.stateDuration : 1;
    if (state === 'attack' && this.attackKind === 'grabWhiff') return;

    let active = false;
    if (state === 'attack') active = progress > 0.2 && progress < 0.58;
    else if (state === 'heavy') active = progress > 0.32 && progress < 0.65;
    else if (state === 'dragon') active = progress > 0.16 && progress < 0.58;
    else if (state === 'spin') active = progress > 0.08 && progress < 0.72;
    else if (state === 'dive') active = true;
    if (!active) return;

    const unit = this.unit;
    const enemies = this.game.enemies;
    for (const enemy of enemies) {
      if (!enemy || enemy.state === 'dead' || enemy.state === 'grabbed' || this.attackHitSet.has(enemy.id)) continue;

      let hit = false;
      let damage = 0;
      let vx = 0;
      let vy = 0;
      let kind = 'light';
      let batteryGain = 0;
      let hitY = this.y - 66 * unit;

      if (state === 'attack') {
        const reach = (this.attackChain === 2 ? 88 : 76) * unit;
        const hitX = this.x + this.facing * reach * 0.5;
        if (Math.abs(enemy.x - hitX) < reach * 0.5 + 20 * unit && enemy.y > this.y - 150 * unit && enemy.y < this.y + 34 * unit) {
          hit = true;
          if (this.attackChain === 2) {
            damage = 13;
            vx = this.facing * 690 * unit;
            vy = -540 * unit;
            kind = 'finisher';
            batteryGain = 7;
          } else {
            damage = 7 + this.attackChain;
            vx = this.facing * (240 + this.attackChain * 90) * unit;
            vy = -190 * unit;
            kind = 'light';
            batteryGain = 4;
          }
          hitY = enemy.y - 64 * unit;
        }
      } else if (state === 'heavy') {
        const reach = 102 * unit;
        const hitX = this.x + this.facing * reach * 0.48;
        if (Math.abs(enemy.x - hitX) < reach * 0.5 + 22 * unit && enemy.y > this.y - 160 * unit && enemy.y < this.y + 36 * unit) {
          hit = true;
          damage = 19;
          vx = this.facing * 760 * unit;
          vy = -570 * unit;
          kind = 'heavy';
          batteryGain = 9;
          hitY = enemy.y - 62 * unit;
        }
      } else if (state === 'dragon') {
        const reach = 88 * unit;
        const hitX = this.x + this.facing * reach * 0.35;
        if (Math.abs(enemy.x - hitX) < reach * 0.65 + 18 * unit && enemy.y > this.y - 230 * unit && enemy.y < this.y + 44 * unit) {
          hit = true;
          damage = 27;
          vx = this.facing * 210 * unit;
          vy = -1120 * unit;
          kind = 'dragon';
          batteryGain = 13;
          hitY = enemy.y - 66 * unit;
        }
      } else if (state === 'spin') {
        const radius = 126 * unit;
        if (Math.abs(enemy.x - this.x) < radius + 18 * unit && enemy.y > this.y - 150 * unit && enemy.y < this.y + 40 * unit) {
          hit = true;
          damage = 16;
          vx = (enemy.x < this.x ? -1 : 1) * 620 * unit;
          vy = -410 * unit;
          kind = 'spin';
          batteryGain = 6;
          hitY = enemy.y - 62 * unit;
        }
      } else if (state === 'dive') {
        if (Math.abs(enemy.x - this.x) < 92 * unit && enemy.y > this.y - 45 * unit && enemy.y < this.y + 220 * unit) {
          hit = true;
          damage = 34;
          vx = (enemy.x < this.x ? -1 : 1) * 420 * unit;
          vy = 690 * unit;
          kind = 'dive';
          batteryGain = 15;
          hitY = enemy.y - 54 * unit;
        }
      }

      if (!hit) continue;
      this.attackHitSet.add(enemy.id);

      const landed = this.game.hitEnemy(enemy, {
        damage,
        kind,
        vx,
        vy,
        batteryGain,
        source: 'player',
        hitX: enemy.x,
        hitY,
        dramatic: kind !== 'light',
        allowArmorBreak: ['dragon', 'dive'].includes(state),
      });

      if (landed) {
        const hitAngle = Math.atan2(hitY - (this.y - 70 * unit), enemy.x - this.x);
        this.game.fx.impact(enemy.x, hitY, hitAngle, kind === 'heavy' || kind === 'dragon' || kind === 'dive' ? 1.5 : 1, kind === 'dragon' ? '#ffe47a' : '#8ffbff');
        this.game.hitstop(kind === 'heavy' || kind === 'dragon' ? 0.075 : kind === 'dive' ? 0.09 : 0.035);
        this.game.shake(kind === 'dive' ? 13 : kind === 'dragon' ? 11 : 5, 0.18);
        this.game.audio[kind === 'dive' || kind === 'dragon' ? 'hitHeavy' : 'hitLight']();

        if (state === 'dive') {
          this.diveBounces += 1;
          if (this.diveBounces < 3) {
            this.vy = -430 * unit;
            this.vx *= 0.82;
          }
        }
      }
    }
  }

  updateSpecial(dt) {
    const progress = this.stateDuration > 0 ? this.stateTime / this.stateDuration : 1;
    this.attackHitSet.clear();
    this.invuln = Math.max(this.invuln, 0.1);

    if (progress > 0.1 && progress < 0.86) {
      this.vx = this.facing * 280 * this.unit;
    } else {
      this.vx *= 0.82;
    }

    if (progress > 0.08 && progress < 0.92) {
      const unit = this.unit;
      for (const enemy of this.game.enemies) {
        if (!enemy || enemy.state === 'dead' || enemy.state === 'grabbed' || this.specialHits.has(enemy.id)) continue;
        const inFront = (enemy.x - this.x) * this.facing > -34 * unit;
        if (Math.abs(enemy.x - this.x) < 185 * unit && inFront && enemy.y > this.y - 180 * unit && enemy.y < this.y + 60 * unit) {
          this.specialHits.add(enemy.id);
          const hitY = enemy.y - 66 * unit;
          const landed = this.game.hitEnemy(enemy, {
            damage: 36,
            kind: 'special',
            vx: this.facing * 910 * this.unit,
            vy: -680 * this.unit,
            batteryGain: 0,
            source: 'player',
            hitX: enemy.x,
            hitY,
            dramatic: true,
            allowArmorBreak: true,
          });
          if (landed) {
            this.game.fx.bolt(this.x + this.facing * 40 * unit, this.y - 72 * unit, enemy.x, hitY, {
              color: '#bffcff',
              life: 0.2,
              width: 2.6,
              segments: 9,
              jitter: 22 * unit,
            });
            this.game.fx.impact(enemy.x, hitY, 0, 2, '#bffcff');
            this.game.audio.electric(0.3);
            this.game.shake(8, 0.14);
          }
        }
      }
      // Electric aura ticks
      if (Math.random() < 0.45) {
        const angle = rand(0, TAU);
        this.game.fx.bolt(
          this.x + Math.cos(angle) * 26 * unit,
          this.y - 68 * unit + Math.sin(angle) * 26 * unit,
          this.x + Math.cos(angle) * 120 * unit,
          this.y - 68 * unit + Math.sin(angle) * 90 * unit,
          { color: '#8ffbff', life: 0.12, width: 1.4, segments: 5, jitter: 13 * unit },
        );
      }
    }

    if (progress > 0.42 && !this.specialWaveDone) {
      this.specialWaveDone = true;
      const unit = this.unit;
      this.game.fx.ring(this.x, this.y - 50 * unit, {
        color: '#bffcff',
        maxRadius: 240 * unit,
        life: 0.6,
        width: 5,
        squash: 0.55,
      });
      this.game.fx.screenFlash('#bffcff', 0.22, 3);
      this.game.shake(20, 0.35);
      this.game.audio.special();
      for (const enemy of this.game.enemies) {
        if (!enemy || enemy.state === 'dead' || enemy.state === 'grabbed' || this.specialHits.has(enemy.id)) continue;
        if (Math.abs(enemy.x - this.x) < 245 * unit && Math.abs(enemy.y - this.y) < 180 * unit) {
          this.specialHits.add(enemy.id);
          this.game.hitEnemy(enemy, {
            damage: 18,
            kind: 'specialWave',
            vx: (enemy.x < this.x ? -1 : 1) * 760 * unit,
            vy: -540 * unit,
            batteryGain: 0,
            source: 'player',
            dramatic: true,
            allowArmorBreak: true,
          });
        }
      }
    }

    if (this.stateTime >= this.stateDuration) {
      this.setState(this.onGround ? 'idle' : 'fall');
      this.specialHits.clear();
      this.specialWaveDone = false;
      this.invuln = Math.max(this.invuln, 0.4);
      this.vx *= 0.3;
      this.game.endSlowMo();
    }
  }

  startSpecial() {
    this.battery = 0;
    this.charged = false;
    this.setState('special', 1.36);
    this.specialHits.clear();
    this.specialWaveDone = false;
    this.attackHitSet.clear();
    this.invuln = 2.1;
    this.facing = this.facing || 1;
    this.vx = 0;
    this.game.startSlowMo(2.8);
    this.game.audio.special();
    this.game.audio.electric(1.2);
    this.game.fx.screenFlash('#bffcff', 0.3, 2.5);
    this.game.fx.ring(this.x, this.y - 62 * this.unit, {
      color: '#39f5ff',
      maxRadius: 170 * this.unit,
      life: 0.55,
      width: 4,
      squash: 0.65,
    });
    this.game.fx.burst(this.x, this.y - 62 * this.unit, {
      count: 28,
      color: '#bffcff',
      speed: 620,
      spread: TAU,
      gravity: 100,
      size: 3.6,
      life: 0.65,
      shape: 'spark',
    });
    this.game.shake(18, 0.45);
    this.game.ui.banner('BULLET TIME', 'PATADA ELÉCTRICA · 40% DE VELOCIDAD', 'kicker', 1.1);
    this.game.ui.flashBattery();
  }

  updateSuplex(dt) {
    const target = this.suplexTarget;
    if (!target || target.state === 'dead') {
      this.setState(this.onGround ? 'idle' : 'fall');
      this.suplexTarget = null;
      return;
    }
    this.vx *= 0.9;
    if (this.stateTime > 0.16) {
      this.vy = Math.max(this.vy, 900 * this.unit);
      this.onGround = false;
    }
    const progress = this.stateTime / this.stateDuration;
    target.x = this.x - this.facing * 8 * this.unit;
    target.y = this.y + 18 * this.unit;
    target.facing = this.facing;

    if (!this.suplexSlammed && (progress > 0.46 || this.y >= this.game.groundY - 1)) {
      this.suplexSlammed = true;
      this.slamSuplex();
    }

    if (this.stateTime >= this.stateDuration) {
      this.setState(this.onGround ? 'idle' : 'fall');
      this.suplexTarget = null;
    }
  }

  slamSuplex() {
    const target = this.suplexTarget;
    const unit = this.unit;
    this.y = this.game.groundY;
    this.vy = 0;
    this.onGround = true;
    this.vx = 0;
    target.state = 'ragdoll';
    target.grabbedBy = null;
    target.ragdollTimer = 0.9;
    target.vy = -260 * unit;
    target.vx = (target.x < this.x ? -1 : 1) * 300 * unit;
    target.rotVel = rand(-14, 14);
    target.blackout = 0.35;
    this.game.hitEnemy(target, {
      damage: 29,
      kind: 'suplex',
      vx: (target.x < this.x ? -1 : 1) * 260 * unit,
      vy: -240 * unit,
      batteryGain: 18,
      source: 'player',
      dramatic: true,
      allowArmorBreak: true,
      silent: true,
      hitY: target.y - 30,
    });
    for (const enemy of this.game.enemies) {
      if (!enemy || enemy === target || enemy.state === 'dead' || enemy.state === 'grabbed') continue;
      const distance = Math.abs(enemy.x - this.x);
      if (distance < 190 * unit && Math.abs(enemy.y - this.y) < 120 * unit) {
        this.game.hitEnemy(enemy, {
          damage: 20,
          kind: 'suplexAoe',
          vx: (enemy.x < this.x ? -1 : 1) * (360 + (190 * unit - distance)) * unit,
          vy: -460 * unit,
          batteryGain: 7,
          source: 'player',
          dramatic: true,
          allowArmorBreak: true,
          hitY: enemy.y - 45 * unit,
        });
      }
    }
    this.game.fx.ring(this.x, this.game.groundY, {
      color: '#8ffbff',
      maxRadius: 240 * unit,
      life: 0.62,
      width: 6,
      squash: 0.22,
    });
    this.game.fx.dust(this.x, this.game.groundY, 26, 0, '#9cc8ff');
    this.game.fx.shards(this.x, this.game.groundY, 12, '#8ffbff', this.facing);
    this.game.fx.screenFlash('#ffffff', 0.16, 5);
    this.game.audio.slam();
    this.game.shake(24, 0.45);
    this.game.hitstop(0.1);
    this.game.ui.banner('SUPLEX SÍSMICO', 'DAÑO EN ÁREA · 190 PX', 'kicker', 0.85);
    this.game.player.bestCombo = Math.max(this.game.player.bestCombo, this.game.player.combo);
  }

  tryGrab() {
    const unit = this.unit;
    if (!this.onGround) {
      let candidate = null;
      let best = Infinity;
      for (const enemy of this.game.enemies) {
        if (!enemy || enemy.state === 'dead' || enemy.state === 'grabbed') continue;
        const dx = Math.abs(enemy.x - this.x);
        const dy = enemy.y - this.y;
        if (dx < 125 * unit && dy > -180 * unit && dy < 110 * unit) {
          const score = dx + Math.abs(dy) * 0.35;
          if (score < best) {
            best = score;
            candidate = enemy;
          }
        }
      }
      if (candidate) {
        this.startSuplex(candidate);
        return true;
      }
      return false;
    }

    let candidate = null;
    let best = Infinity;
    for (const enemy of this.game.enemies) {
      if (!enemy || enemy.state === 'dead' || enemy.state === 'grabbed') continue;
      const dx = enemy.x - this.x;
      const dy = Math.abs(enemy.y - this.y);
      const inFront = dx * this.facing >= -16 * unit;
      if (inFront && Math.abs(dx) < 88 * unit && dy < 80 * unit) {
        const score = Math.abs(dx);
        if (score < best) {
          best = score;
          candidate = enemy;
        }
      }
    }
    if (!candidate) return false;

    this.grabTarget = candidate;
    candidate.state = 'grabbed';
    candidate.grabbedBy = this;
    candidate.stateTime = 0;
    candidate.vx = 0;
    candidate.vy = 0;
    candidate.onGround = false;
    this.setState('grab', 1.4);
    this.grabTimer = 1.25;
    this.vx = 0;
    this.game.audio.grab();
    this.game.fx.ring(candidate.x, candidate.y - 60 * unit, {
      color: candidate.heavy ? '#ffd34d' : '#ff3ea5',
      maxRadius: 52,
      life: 0.3,
      width: 2,
      squash: 0.8,
    });
    this.game.showContextTip('<b>AGARRE</b> · pulsa RÁPIDO, FUERTE o AGARRE para lanzarlo', 2.2);
    return true;
  }

  startSuplex(target) {
    this.suplexTarget = target;
    this.suplexSlammed = false;
    target.state = 'grabbed';
    target.grabbedBy = this;
    target.vx = 0;
    target.vy = 0;
    target.onGround = false;
    this.setState('suplex', 0.78);
    this.vy = 250 * this.unit;
    this.vx = 0;
    this.game.audio.grab();
    this.game.audio.whoosh(1.4);
    this.game.showContextTip('<b>AGARRE AÉREO</b> · suplex devastador en camino', 1.4);
  }

  throwGrab() {
    const target = this.grabTarget;
    if (!target) return;
    const unit = this.unit;
    target.state = 'ragdoll';
    target.grabbedBy = null;
    target.grabbedBy = null;
    target.thrown = true;
    target.thrownBy = 'player';
    target.ragdollTimer = 1.1;
    target.vx = this.facing * 1120 * unit;
    target.vy = -360 * unit;
    target.rotVel = rand(-18, -9) * this.facing;
    target.hp = Math.max(0, target.hp - 16);
    target.flash = 0.2;
    target.onGround = false;
    target.hitCooldown = 0.08;
    this.game.audio.throwEnemy();
    this.game.audio.hitHeavy();
    this.game.fx.impact(target.x, target.y - 55 * unit, this.facing > 0 ? 0 : Math.PI, 1.3, '#ffb3d9');
    this.game.fx.text(target.x, target.y - 130 * unit, '¡LANZADO!', { color: '#ff9ecf', size: 13, life: 0.65, vy: -30 });
    this.game.shake(8, 0.2);
    this.game.hitstop(0.04);
    this.grabTarget = null;
    this.grabTimer = 0;
    this.setState('throw', 0.4);
    this.vx = this.facing * 70 * unit;
    this.game.showContextTip('', 0);
  }

  releaseGrab() {
    if (this.grabTarget) {
      const target = this.grabTarget;
      target.state = target.hp > 0 ? 'idle' : 'dead';
      target.grabbedBy = null;
      target.onGround = true;
      target.y = this.game.groundY;
      target.x = clamp(target.x, this.game.left + 20, this.game.right - 20);
      target.vx = (target.x < this.x ? -1 : 1) * 160 * this.unit;
      target.vy = 0;
      this.grabTarget = null;
    }
    this.grabTimer = 0;
    if (this.state === 'grab') this.setState('idle');
  }

  updateHeldEnemy() {
    if (!this.grabTarget) return;
    const target = this.grabTarget;
    if (target.state !== 'grabbed') {
      this.grabTarget = null;
      return;
    }
    const unit = this.unit;
    target.x = this.x + this.facing * 45 * unit;
    target.y = this.y - 62 * unit;
    target.facing = -this.facing;
    target.stateTime += 0;
  }

  updatePhysics(dt, input) {
    const unit = this.unit;
    const grounded = this.onGround;
    const state = this.state;
    const locked = ['attack', 'heavy', 'dragon', 'spin', 'throw', 'hurt', 'grab', 'suplex', 'special', 'wall', 'dive'].includes(state);

    if (!locked) {
      if (grounded) {
        const targetSpeed = this.state === 'crouch' ? 0 : input.move * this.moveSpeed;
        this.vx = approach(this.vx, targetSpeed, (targetSpeed !== 0 ? 3900 : 2700) * unit * dt);
        if (input.move !== 0) this.facing = input.move > 0 ? 1 : -1;
        if (Math.abs(this.vx) > 24 && this.state !== 'crouch') {
          if (this.state !== 'run') this.setState('run');
        } else if (this.state === 'run') {
          this.setState('idle');
        }
      } else {
        this.vx = approach(this.vx, input.move * this.airSpeed, 1400 * unit * dt);
        if (input.move !== 0) this.facing = input.move > 0 ? 1 : -1;
      }
    } else if (state === 'attack' || state === 'heavy') {
      // keep momentum but bleed it
      this.vx *= Math.pow(0.03, dt);
    } else if (state === 'hurt') {
      this.vx *= Math.pow(0.2, dt);
    } else if (state === 'dive') {
      this.vx = approach(this.vx, this.facing * 520 * unit, 900 * unit * dt);
    } else if (state === 'special') {
      // handled in updateSpecial
    } else {
      this.vx *= Math.pow(0.02, dt);
    }

    // Gravity
    if (!this.onGround) {
      this.vy += this.gravity * dt;
      if (state === 'suplex') this.vy += 1500 * unit * dt;
      if (state === 'dive') this.vy += 900 * unit * dt;
      if (state === 'dragon') this.vy += 300 * unit * dt;
    }

    // Integrate
    this.x += this.vx * dt;
    this.y += this.vy * dt;

    const minX = this.game.left + this.radius;
    const maxX = this.game.right - this.radius;
    if (this.x < minX) {
      this.x = minX;
      if (this.vx < -160 && !this.onGround) this.game.scene.pulseWall('left', 0.5);
      this.vx = 0;
      if (this.onGround && state !== 'wall' && !locked && input.move < 0) this.enterWall('left');
    } else if (this.x > maxX) {
      this.x = maxX;
      if (this.vx > 160 && !this.onGround) this.game.scene.pulseWall('right', 0.5);
      this.vx = 0;
      if (this.onGround && state !== 'wall' && !locked && input.move > 0) this.enterWall('right');
    }

    // Ceiling
    const ceilingY = this.game.ceilingY;
    if (this.y - 128 * this.scale < ceilingY) {
      this.y = ceilingY + 128 * this.scale;
      if (this.vy < 0) {
        this.vy = 0;
        this.game.fx.burst(this.x, this.y, { count: 5, color: '#39f5ff', speed: 90, angle: Math.PI / 2, spread: 1.2, gravity: 500, size: 2, life: 0.3 });
      }
    }

    // Ground
    if (this.y >= this.game.groundY) {
      const wasAirborne = !this.onGround;
      this.y = this.game.groundY;
      if (wasAirborne) {
        if (this.vy > 380) {
          this.game.fx.dust(this.x, this.game.groundY, 8, 0, '#88b7e7');
          this.game.audio.land();
          this.game.shake(clamp(this.vy / 120, 2, 7), 0.16);
        }
        if (state === 'dive') {
          this.diveLand();
        } else if (state === 'special') {
          // continue special on ground
        } else if (state === 'suplex') {
          // keep suplexing
        } else if (state === 'jump' || state === 'fall') {
          this.setState('idle');
        }
      }
      this.vy = 0;
      this.onGround = true;
    } else {
      this.onGround = false;
      if (this.state === 'idle' || this.state === 'run' || this.state === 'crouch') {
        this.setState('fall');
      }
    }

    // Wall cling visual detection
    if (this.onGround && (this.x <= minX + 0.6 || this.x >= maxX - 0.6) && !locked) {
      if ((this.x <= minX + 0.6 && input.move < 0) || (this.x >= maxX - 0.6 && input.move > 0)) {
        this.enterWall(this.x <= minX + 0.6 ? 'left' : 'right');
      }
    }
  }

  diveLand() {
    const unit = this.unit;
    this.setState('idle');
    this.vx *= 0.2;
    this.onGround = true;
    this.diveHits.clear();
    this.game.fx.ring(this.x, this.game.groundY, {
      color: '#8ffbff',
      maxRadius: 190 * unit,
      life: 0.5,
      width: 4,
      squash: 0.2,
    });
    this.game.fx.dust(this.x, this.game.groundY, 20, 0, '#9cc8ff');
    this.game.audio.slam();
    this.game.shake(16, 0.3);
    this.game.hitstop(0.06);
    for (const enemy of this.game.enemies) {
      if (!enemy || enemy.state === 'dead' || enemy.state === 'grabbed') continue;
      if (Math.abs(enemy.x - this.x) < 190 * unit && Math.abs(enemy.y - this.game.groundY) < 80 * unit) {
        this.game.hitEnemy(enemy, {
          damage: 18,
          kind: 'diveLand',
          vx: (enemy.x < this.x ? -1 : 1) * 680 * unit,
          vy: -520 * unit,
          batteryGain: 6,
          source: 'player',
          dramatic: true,
          allowArmorBreak: true,
          hitY: enemy.y - 40 * unit,
        });
      }
    }
  }

  updateVisualTrail(dt) {
    this.trailTimer -= dt;
    const fast = Math.abs(this.vx) > 220 || this.state === 'dive' || this.state === 'special' || this.state === 'suplex';
    if (fast && this.trailTimer <= 0) {
      this.trailTimer = this.state === 'special' ? 0.02 : 0.035;
      this.game.fx.trail(
        this.x - this.facing * 12 * this.unit + rand(-4, 4),
        this.y - (58 + rand(-18, 18)) * this.unit,
        this.state === 'special' ? '#bffcff' : '#39f5ff',
        this.state === 'special' ? 7 : 4.4,
        this.state === 'special' ? 0.4 : 0.24,
      );
      if (this.state === 'special' || this.state === 'dive') {
        this.game.fx.burst(this.x, this.y - 60 * this.unit, {
          count: 1,
          color: '#bffcff',
          speed: 80,
          spread: TAU,
          gravity: 0,
          size: 2,
          life: 0.2,
        });
      }
    }

    if (this.onGround && Math.abs(this.vx) > 300 && this.state === 'run' && this.trailTimer <= 0) {
      this.game.fx.dust(this.x - this.facing * 10, this.game.groundY, 1, -this.facing, '#4b7ea6');
    }
  }

  takeDamage(amount, sourceX, options = {}) {
    if (!this.alive || this.invuln > 0 || this.state === 'special') return false;
    if (this.state === 'dive' && options.ignoreInvuln !== true) return false;
    this.hp = clamp(this.hp - amount, 0, this.maxHp);
    this.flash = 0.18;
    this.invuln = 0.82;
    this.combo = 0;
    this.comboTimer = 0;
    this.game.ui.setCombo(0, 0);
    this.state = 'hurt';
    this.stateTime = 0;
    this.stateDuration = 0.34;
    this.vy = -260 * this.unit;
    this.vx = (this.x < sourceX ? -1 : 1) * 320 * this.unit;
    this.onGround = false;
    this.game.fx.text(this.x, this.y - 145 * this.unit, `-${Math.round(amount)}`, { color: '#ff7588', size: 17, life: 0.8, vy: -60 });
    this.game.fx.burst(this.x, this.y - 70 * this.unit, {
      count: 10,
      color: '#ff5577',
      speed: 300,
      spread: TAU,
      gravity: 900,
      size: 2.6,
      life: 0.4,
    });
    this.game.fx.screenFlash('#ff3050', 0.12, 6);
    this.game.audio.hurt();
    this.game.shake(10, 0.25);
    this.game.hitstop(0.045);
    if (this.hp <= 0) {
      this.die();
    }
    return true;
  }

  die() {
    this.alive = false;
    this.state = 'dead';
    this.stateTime = 0;
    this.stateDuration = 10;
    this.vy = -420 * this.unit;
    this.vx = -this.facing * 220 * this.unit;
    this.onGround = false;
    this.invuln = 999;
    this.rot = 0;
    this.rotVel = rand(-8, 8);
    this.game.onPlayerDeath();
  }

  updateDead(dt) {
    this.animTime += dt;
    this.flash = Math.max(0, this.flash - dt);
    this.vy += this.gravity * 0.55 * dt;
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.rot = (this.rot || 0) + (this.rotVel || 0) * dt;
    if (this.y >= this.game.groundY) {
      this.y = this.game.groundY;
      if (this.vy > 200) {
        this.vy *= -0.32;
        this.rotVel *= 0.6;
        this.game.fx.dust(this.x, this.game.groundY, 8, 0, '#7ea5ca');
      } else {
        this.vy = 0;
        this.vx *= 0.85;
        this.rotVel *= 0.8;
      }
    }
    this.x = clamp(this.x, this.game.left + 20, this.game.right - 20);
  }
}

import { TAU, clamp, rand, randInt, sign, approach, easeOutCubic } from './utils.js';

const PALETTES = {
  red: {
    main: '#ff4a5e',
    light: '#ffd0d6',
    accent: '#ff1744',
    back: '#9d1026',
    glow: '#ff3b4e',
    outline: 'rgba(26, 1, 6, 0.96)',
  },
  gold: {
    main: '#ffd34d',
    light: '#fff6c4',
    accent: '#ff9a1f',
    back: '#b47c12',
    glow: '#ffc400',
    outline: 'rgba(27, 17, 1, 0.96)',
  },
  green: {
    main: '#53ff9a',
    light: '#d4ffe6',
    accent: '#c9ff4d',
    back: '#157c4b',
    glow: '#53ff9a',
    outline: 'rgba(1, 24, 12, 0.96)',
  },
};

let NEXT_ID = 1;

export class Enemy {
  constructor(game, type, options = {}) {
    this.game = game;
    this.unit = game.unit;
    this.id = `enemy-${NEXT_ID++}`;
    this.type = type;
    this.heavy = type === 'heavy';
    this.variant = options.variant || (this.heavy ? 'gold' : 'red');
    this.player = false;
    this.isPlayer = false;
    this.scale = (this.heavy ? 1.2 : 0.98) * this.unit;
    this.radius = (this.heavy ? 20 : 15) * this.unit;
    this.maxHp = this.heavy ? 108 + game.wave * 7 : 34 + game.wave * 4;
    this.hp = this.maxHp;
    this.damage = this.heavy ? 12 + Math.min(5, game.wave * 0.4) : 6 + Math.min(3, game.wave * 0.25);
    this.attackRange = (this.heavy ? 96 : 72) * this.unit;
    this.speed = (this.heavy ? 92 : 160 + Math.random() * 22) * this.unit;
    this.windup = (this.heavy ? 0.72 : 0.34) * (options.variant ? 1 : 1);
    this.attackDuration = this.heavy ? 0.42 : 0.3;
    this.recovery = this.heavy ? 0.62 : 0.28;
    this.cooldown = rand(0.2, 0.9);
    this.x = options.x ?? game.width / 2;
    this.y = options.y ?? game.groundY;
    this.spawnSide = options.side || (Math.random() > 0.5 ? 'left' : 'right');
    this.spawnMode = options.spawnMode || 'walk';
    this.vx = 0;
    this.vy = 0;
    this.facing = this.spawnSide === 'left' ? 1 : -1;
    this.onGround = this.spawnMode !== 'drop';
    this.state = 'spawn';
    this.stateTime = 0;
    this.stateDuration = this.spawnMode === 'drop' ? 0 : 0.8;
    this.animTime = rand(0, 10);
    this.flash = 0;
    this.shieldFlash = 0;
    this.alpha = 1;
    this.rot = 0;
    this.rotVel = 0;
    this.ragdollTimer = 0;
    this.settleTimer = 0;
    this.deadTimer = 0;
    this.countedDead = false;
    this.armored = this.heavy;
    this.grabbedBy = null;
    this.thrown = false;
    this.hitCooldown = 0;
    this.hitSet = new Set();
    this.palette = PALETTES[this.variant] || PALETTES.red;
    this.seed = rand(0, 100);
    this.attackHit = false;
    this.lastHitKind = null;
    this.taunt = 0;
    this.armoredPulse = rand(0, TAU);
    this.deathY = 0;
    this.spawnRing = 0;
  }

  setState(name, duration = 0) {
    this.state = name;
    this.stateTime = 0;
    this.stateDuration = duration;
    if (name === 'ragdoll') {
      this.hitSet.clear();
      this.settleTimer = 0;
    }
  }

  get height() {
    return (this.heavy ? 165 : 140) * this.scale;
  }

  update(dt, player) {
    this.animTime += dt;
    this.stateTime += dt;
    this.flash = Math.max(0, this.flash - dt);
    this.shieldFlash = Math.max(0, this.shieldFlash - dt * 4);
    this.hitCooldown = Math.max(0, this.hitCooldown - dt);

    if (this.state === 'grabbed') {
      this.alpha = 1;
      return;
    }

    if (this.state === 'ragdoll' || this.state === 'dead') {
      this.updateRagdoll(dt);
      return;
    }

    if (this.state === 'spawn') {
      this.updateSpawn(dt, player);
      return;
    }

    if (this.state === 'hurt') {
      this.vx *= Math.pow(0.02, dt);
      this.gravity(dt);
      if (this.stateTime >= this.stateDuration) this.setState('approach');
      this.integrate(dt);
      return;
    }

    if (this.state === 'windup') {
      this.vx *= Math.pow(0.03, dt);
      this.facing = player.x >= this.x ? 1 : -1;
      this.gravity(dt);
      this.integrate(dt);
      if (this.stateTime >= this.stateDuration) {
        this.state = 'attack';
        this.stateTime = 0;
        this.stateDuration = this.attackDuration;
        this.attackHit = false;
        this.vx = this.facing * (this.heavy ? 170 : 360) * this.unit;
        this.game.audio.whoosh(this.heavy ? 1.1 : 0.5);
      }
      return;
    }

    if (this.state === 'attack') {
      this.updateAttack(dt, player);
      return;
    }

    if (this.state === 'recover') {
      this.vx *= Math.pow(0.02, dt);
      this.gravity(dt);
      this.integrate(dt);
      if (this.stateTime >= this.stateDuration) {
        this.cooldown = this.heavy ? rand(1.1, 1.8) : rand(0.55, 1.3);
        this.setState('approach');
      }
      return;
    }

    if (this.state === 'approach' || this.state === 'idle') {
      this.updateApproach(dt, player);
    }
  }

  gravity(dt) {
    if (!this.onGround) this.vy += 2100 * this.unit * dt;
  }

  integrate(dt) {
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    if (this.y >= this.game.groundY) {
      this.y = this.game.groundY;
      this.vy = 0;
      this.onGround = true;
    } else {
      this.onGround = false;
    }
    this.x = clamp(this.x, this.game.left - 30 * this.unit, this.game.right + 30 * this.unit);
  }

  updateSpawn(dt, player) {
    if (this.spawnMode === 'drop') {
      this.vy += 2600 * this.unit * dt;
      this.y += this.vy * dt;
      this.x += this.vx * dt;
      if (this.y >= this.game.groundY) {
        this.y = this.game.groundY;
        this.vy = 0;
        this.onGround = true;
        this.setState('approach');
        this.cooldown = 0.9;
        const color = this.palette.main;
        this.game.fx.ring(this.x, this.game.groundY, {
          color,
          maxRadius: 140 * this.unit,
          life: 0.55,
          width: 4,
          squash: 0.24,
        });
        this.game.fx.dust(this.x, this.game.groundY, 20, 0, '#a3c9e8');
        this.game.fx.shards(this.x, this.game.groundY, 8, color, 0);
        this.game.shake(12, 0.3);
        this.game.audio.slam();
        this.game.fx.text(this.x, this.y - 185 * this.unit, 'PESADO', {
          color,
          size: 15,
          life: 0.9,
          vy: -35,
        });
      }
      return;
    }

    const targetX = this.game.width / 2;
    const dir = targetX >= this.x ? 1 : -1;
    this.facing = dir;
    this.x += dir * this.speed * 1.25 * dt;
    this.vx = dir * this.speed;
    if (this.x > this.game.left + 65 * this.unit && this.x < this.game.right - 65 * this.unit) {
      this.setState('approach');
      this.cooldown = rand(0.15, 0.55);
    }
    if (this.stateTime > 2.5) this.setState('approach');
  }

  updateApproach(dt, player) {
    this.cooldown -= dt;
    const dx = player.x - this.x;
    const distance = Math.abs(dx);
    const dir = sign(dx) || 1;
    this.facing = dir;

    if (this.grabbedBy) return;

    const desired = this.attackRange * 0.82;
    if (distance > desired) {
      const speed = this.speed * (this.heavy ? 0.9 : 1);
      this.vx = approach(this.vx, dir * speed, 2600 * this.unit * dt);
      this.state = 'approach';
    } else {
      this.vx = approach(this.vx, 0, 2400 * this.unit * dt);
      if (this.cooldown <= 0) {
        this.setState('windup', this.windup);
        this.vx = 0;
        this.attackHit = false;
        this.game.audio.grab();
      }
    }

    // hop over a downed ally rarely
    if (this.onGround && Math.random() < 0.0007) this.vy = -350 * this.unit;

    this.gravity(dt);
    this.integrate(dt);
    if (this.onGround) {
      const phase = this.animTime * 10;
      if (Math.abs(this.vx) > 10) this.animTime += dt * 0.35;
      this.walkPhase = phase;
    }
  }

  updateAttack(dt, player) {
    const progress = this.stateTime / this.attackDuration;
    this.facing = player.x >= this.x ? 1 : -1;
    this.vx *= Math.pow(0.05, dt);
    this.gravity(dt);
    this.integrate(dt);
    if (!this.attackHit && progress > 0.28 && progress < 0.64) {
      const dx = player.x - this.x;
      const dy = Math.abs(player.y - this.y);
      const reach = this.attackRange + (this.heavy ? 34 : 22) * this.unit;
      if (Math.abs(dx) < reach && dy < 95 * this.unit && sign(dx) === this.facing) {
        this.attackHit = true;
        const landed = player.takeDamage(this.damage, this.x, { source: 'enemy' });
        if (landed) {
          this.game.fx.impact(player.x, player.y - 62 * this.unit, this.facing > 0 ? 0 : Math.PI, this.heavy ? 1.2 : 0.7, this.heavy ? '#ffd34d' : '#ff6c7d');
          this.game.fx.text(player.x, player.y - 135 * this.unit, this.heavy ? '¡PESADO!' : 'GOLPE', {
            color: this.heavy ? '#ffd34d' : '#ff9aa7',
            size: 12,
            life: 0.55,
            vy: -40,
          });
        }
      }
    }
    if (this.stateTime >= this.stateDuration) {
      this.setState('recover', this.recovery);
    }
  }

  takeHit(damage, kind, options = {}) {
    if (this.state === 'dead') return { hit: false };
    const absorbed = this.armored && !options.allowArmorBreak && ['light', 'heavy', 'spin', 'finisher'].includes(kind);
    if (absorbed) {
      this.shieldFlash = 1;
      this.game.audio.shield();
      this.game.fx.burst(this.x, this.y - 90 * this.unit, {
        count: 6,
        color: '#fff3b8',
        speed: 230,
        spread: TAU,
        gravity: 500,
        size: 2,
        life: 0.32,
      });
      this.game.fx.text(this.x, this.y - 178 * this.unit, 'INMUNE', {
        color: '#ffd34d',
        size: 13,
        life: 0.65,
        vy: -35,
      });
      this.game.showContextTip('<b>BLINDADO</b> · usa AGARRE, ESPECIAL, GOLPE DEL DRAGÓN o SALTO DE PARED', 1.6);
      return { hit: true, damaged: false, absorbed: true };
    }

    const wasAlive = this.hp > 0;
    this.hp = Math.max(0, this.hp - damage);
    this.flash = 0.16;
    this.lastHitKind = kind;
    if (options.batteryGain) this.game.player?.addBattery(options.batteryGain);
    if (this.hp > 0) {
      this.game.player?.comboHit(kind);
    }

    // Every armored enemy hit is a launch. Reds launch too, because ragdoll is the point.
    const launchVx = options.vx ?? 420 * this.unit;
    const launchVy = options.vy ?? -420 * this.unit;
    if (this.state === 'grabbed' && this.grabbedBy) this.grabbedBy.grabTarget = null;
    this.grabbedBy = null;
    this.state = this.hp > 0 ? 'ragdoll' : 'dead';
    this.stateTime = 0;
    this.stateDuration = this.hp > 0 ? 1 : 1.8;
    this.vy = launchVy;
    this.vx = launchVx;
    this.onGround = false;
    this.rotVel = rand(-15, 15) + launchVx * 0.018;
    this.ragdollTimer = 0;
    this.settleTimer = 0;
    this.deadTimer = 0;

    if (this.hp <= 0 && wasAlive) this.die();
    return { hit: true, damaged: true, killed: this.hp <= 0 };
  }

  die() {
    if (this.countedDead) return;
    this.countedDead = true;
    this.state = 'dead';
    this.stateTime = 0;
    this.stateDuration = 1.8;
    this.alpha = 1;
    this.rotVel = rand(-14, 14);
    this.game.registerKill(this);
    this.game.fx.burst(this.x, this.y - 70 * this.unit, {
      count: 18,
      color: this.palette.main,
      speed: 440,
      spread: TAU,
      gravity: 900,
      size: 3.2,
      life: 0.6,
      shape: 'shard',
    });
    this.game.fx.ring(this.x, this.y - 60 * this.unit, {
      color: this.palette.main,
      maxRadius: 80,
      life: 0.4,
      width: 2.4,
      squash: 0.8,
    });
    this.game.audio.death();
  }

  updateRagdoll(dt) {
    const gravity = 2180 * this.unit;
    this.vy += gravity * dt;
    this.x += this.vx * dt;
    this.y += this.vy * dt;
    this.rot += this.rotVel * dt;

    const minX = this.game.left + 8;
    const maxX = this.game.right - 8;
    if (this.x < minX) {
      this.x = minX;
      if (Math.abs(this.vx) > 190) {
        this.game.scene.pulseWall('left', clamp(Math.abs(this.vx) / 900, 0.2, 1));
        this.game.fx.burst(this.x, this.y - 55 * this.unit, {
          count: 12,
          color: this.palette.main,
          speed: 350,
          angle: 0,
          spread: 1.8,
          gravity: 800,
          size: 2.8,
          life: 0.4,
        });
        this.game.fx.ring(this.x, this.y - 55 * this.unit, { color: this.palette.main, maxRadius: 55, life: 0.3, width: 2, squash: 0.8 });
        this.game.shake(clamp(Math.abs(this.vx) / 80, 3, 11), 0.18);
        this.game.audio.hitHeavy();
      }
      this.vx = Math.abs(this.vx) * 0.68;
      this.rotVel *= -0.65;
    } else if (this.x > maxX) {
      this.x = maxX;
      if (Math.abs(this.vx) > 190) {
        this.game.scene.pulseWall('right', clamp(Math.abs(this.vx) / 900, 0.2, 1));
        this.game.fx.burst(this.x, this.y - 55 * this.unit, {
          count: 12,
          color: this.palette.main,
          speed: 350,
          angle: Math.PI,
          spread: 1.8,
          gravity: 800,
          size: 2.8,
          life: 0.4,
        });
        this.game.fx.ring(this.x, this.y - 55 * this.unit, { color: this.palette.main, maxRadius: 55, life: 0.3, width: 2, squash: 0.8 });
        this.game.shake(clamp(Math.abs(this.vx) / 80, 3, 11), 0.18);
        this.game.audio.hitHeavy();
      }
      this.vx = -Math.abs(this.vx) * 0.68;
      this.rotVel *= -0.65;
    }

    if (this.y >= this.game.groundY) {
      this.y = this.game.groundY;
      if (Math.abs(this.vy) > 220) {
        this.game.fx.dust(this.x, this.game.groundY, 9, sign(this.vx), '#86a9c8');
        this.game.fx.shards(this.x, this.game.groundY, 3, this.palette.main, sign(this.vx));
        this.game.audio.land();
        this.game.shake(clamp(Math.abs(this.vy) / 160, 2, 8), 0.16);
        this.vy = -Math.abs(this.vy) * (this.state === 'dead' ? 0.42 : 0.35);
        this.vx *= 0.76;
        this.rotVel *= 0.72;
      } else {
        this.vy = 0;
        this.vx *= Math.pow(0.04, dt);
        this.rotVel *= Math.pow(0.1, dt);
        this.onGround = true;
      }
    } else {
      this.onGround = false;
    }

    if (this.y < this.game.ceilingY + 40 * this.unit) {
      this.y = this.game.ceilingY + 40 * this.unit;
      if (this.vy < 0) {
        this.vy = Math.abs(this.vy) * 0.6;
        this.game.fx.ring(this.x, this.game.ceilingY + 35 * this.unit, {
          color: this.palette.main,
          maxRadius: 50,
          life: 0.25,
          width: 2,
          squash: 0.9,
        });
      }
    }

    this.checkEnemyCollisions();

    if (this.state === 'dead') {
      this.deadTimer += dt;
      if (this.onGround && this.deadTimer > 1.05) {
        this.alpha = Math.max(0, this.alpha - dt * 1.6);
        if (this.alpha <= 0) this.game.removeEnemy(this);
      }
    } else {
      const speed = Math.hypot(this.vx, this.vy);
      if (this.onGround && speed < 24) {
        this.settleTimer += dt;
        if (this.settleTimer > 0.72) this.getUp();
      } else {
        this.settleTimer = 0;
      }
    }
  }

  checkEnemyCollisions() {
    if (this.hitCooldown > 0) return;
    const speed = Math.hypot(this.vx, this.vy);
    if (speed < 300) return;
    for (const other of this.game.enemies) {
      if (!other || other === this || other.state === 'dead' || other.state === 'grabbed') continue;
      if (Math.hypot(other.x - this.x, other.y - this.y) > (this.radius + other.radius) * 1.9) continue;
      if (this.hitSet.has(other.id)) continue;
      this.hitSet.add(other.id);
      this.hitCooldown = 0.16;
      const dir = sign(this.vx) || 1;
      const damage = this.thrown ? 18 : 7;
      const result = this.game.hitEnemy(other, {
        damage,
        kind: this.thrown ? 'thrownBody' : 'bodySlam',
        vx: dir * 430 * this.unit,
        vy: -330 * this.unit,
        batteryGain: this.thrown ? 5 : 0,
        source: 'enemyCollision',
        dramatic: true,
        allowArmorBreak: this.thrown,
        hitY: other.y - 55 * this.unit,
      });
      if (result) {
        this.game.fx.impact(other.x, other.y - 55 * this.unit, dir > 0 ? 0 : Math.PI, 0.9, this.palette.main);
        this.game.shake(6, 0.16);
        this.game.audio.hitLight();
      }
    }
  }

  getUp() {
    if (this.hp <= 0) {
      this.state = 'dead';
      return;
    }
    this.state = 'approach';
    this.stateTime = 0;
    this.stateDuration = 0;
    this.rot = 0;
    this.rotVel = 0;
    this.vx = 0;
    this.vy = 0;
    this.y = this.game.groundY;
    this.hitCooldown = 0.35;
    this.cooldown = rand(0.45, 1.0);
    this.game.fx.dust(this.x, this.game.groundY, 5, 0, '#7d9fbe');
    this.game.fx.ring(this.x, this.game.groundY, { color: this.palette.main, maxRadius: 32, life: 0.25, width: 1.2, squash: 0.3 });
  }

  // Called by the player when held
  struggle() {
    this.stateTime += 0;
  }
}

import { clamp } from './utils.js';

export class UI {
  constructor(game) {
    this.game = game;
    this.el = {
      hud: document.getElementById('hud'),
      controls: document.getElementById('controls'),
      hpFill: document.getElementById('hpFill'),
      hpGhost: document.getElementById('hpGhost'),
      hpText: document.getElementById('hpText'),
      batteryFill: document.getElementById('batteryFill'),
      batteryText: document.getElementById('batteryText'),
      batteryMeter: document.getElementById('batteryMeter'),
      batteryState: document.getElementById('batteryState'),
      specialBtn: document.getElementById('specialBtn'),
      specialCharge: document.getElementById('specialCharge'),
      waveValue: document.getElementById('waveValue'),
      killValue: document.getElementById('killValue'),
      comboDisplay: document.getElementById('comboDisplay'),
      comboCount: document.getElementById('comboCount'),
      comboRank: document.getElementById('comboRank'),
      comboTimer: document.getElementById('comboTimer'),
      banner: document.getElementById('banner'),
      bannerKicker: document.getElementById('bannerKicker'),
      bannerTitle: document.getElementById('bannerTitle'),
      bannerSub: document.getElementById('bannerSub'),
      contextTip: document.getElementById('contextTip'),
      menuScreen: document.getElementById('menuScreen'),
      howScreen: document.getElementById('howScreen'),
      pauseScreen: document.getElementById('pauseScreen'),
      gameoverScreen: document.getElementById('gameoverScreen'),
      adScreen: document.getElementById('adScreen'),
      pauseWave: document.getElementById('pauseWave'),
      pauseKills: document.getElementById('pauseKills'),
      pauseCombo: document.getElementById('pauseCombo'),
      goKicker: document.getElementById('goKicker'),
      goTitle: document.getElementById('goTitle'),
      goCopy: document.getElementById('goCopy'),
      goWave: document.getElementById('goWave'),
      goKills: document.getElementById('goKills'),
      goCombo: document.getElementById('goCombo'),
      goTime: document.getElementById('goTime'),
      reviveOffer: document.getElementById('reviveOffer'),
      offerDeaths: document.getElementById('offerDeaths'),
      goAdNote: document.getElementById('goAdNote'),
      menuSoundBtn: document.getElementById('menuSoundBtn'),
      adProgress: document.getElementById('adProgress'),
      adCountdown: document.getElementById('adCountdown'),
      adSkip: document.getElementById('adSkip'),
      adClaim: document.getElementById('adClaim'),
      startBtn: document.getElementById('startBtn'),
      soundBtn: document.getElementById('soundBtn'),
    };
    this.contextTimer = 0;
    this.contextText = '';
    this.bannerToken = 0;
    this.comboHideTimer = null;
    this.bind();
    this.syncSound();
  }

  bind() {
    const click = (id, handler) => {
      const element = document.getElementById(id);
      if (!element) return;
      element.addEventListener('click', (event) => {
        event.preventDefault();
        this.game.audio.click();
        handler(event);
      });
    };

    click('startBtn', () => this.game.startRun());
    click('howBtn', () => this.game.openHow());
    click('howClose', () => this.game.closeHow());
    click('howBack', () => this.game.closeHow());
    click('pauseBtn', () => this.game.togglePause());
    click('resumeBtn', () => this.game.resume());
    click('pauseRestart', () => this.game.restart());
    click('pauseMenu', () => this.game.toMenu());
    click('retryBtn', () => this.game.retry());
    click('goMenuBtn', () => this.game.toMenu(true));
    click('reviveBtn', () => this.game.acceptRevive());
    click('adSkip', () => this.game.finishAd());
    click('adClaim', () => this.game.finishAd());
    click('soundBtn', () => this.game.toggleSound());
    click('menuSoundBtn', () => this.game.toggleSound());
  }

  syncSound() {
    const muted = this.game.audio.muted;
    document.body.classList.toggle('muted', muted);
    if (this.el.menuSoundBtn) this.el.menuSoundBtn.textContent = muted ? 'SONIDO: NO' : 'SONIDO: SÍ';
    const soundBtn = this.el.soundBtn;
    if (soundBtn) {
      soundBtn.setAttribute('aria-label', muted ? 'Activar sonido' : 'Silenciar sonido');
      soundBtn.setAttribute('aria-pressed', String(muted));
    }
  }

  showScreen(name) {
    const screens = {
      menu: this.el.menuScreen,
      how: this.el.howScreen,
      pause: this.el.pauseScreen,
      gameover: this.el.gameoverScreen,
      ad: this.el.adScreen,
    };
    for (const [key, element] of Object.entries(screens)) {
      if (!element) continue;
      element.classList.toggle('hidden', key !== name);
    }
    const inGame = !name;
    this.el.hud.classList.toggle('is-hidden', ['menu', 'how'].includes(name));
    this.el.hud.classList.toggle('is-dimmed', ['pause', 'gameover', 'ad'].includes(name));
    this.el.controls.classList.toggle('is-hidden', Boolean(name));
    if (name) {
      this.el.banner.classList.remove('show');
      this.el.contextTip.classList.remove('show');
      this.contextTimer = 0;
    }
    if (name === 'pause') {
      this.el.pauseWave.textContent = String(this.game.wave).padStart(2, '0');
      this.el.pauseKills.textContent = String(this.game.kills).padStart(2, '0');
      this.el.pauseCombo.textContent = String(this.game.player?.bestCombo || 0);
    }
    if (name === 'menu' || name === 'how') {
      this.el.comboDisplay.classList.remove('show');
    }
    if (name === 'gameover') {
      this.el.contextTip.classList.remove('show');
    }
    if (!inGame) this.game.input?.clear();
    this.game.input?.setEnabled(!name || name === 'pause');
  }

  update(dt) {
    const player = this.game.player;
    if (!player) return;
    const hpRatio = clamp(player.hp / player.maxHp, 0, 1);
    this.el.hpFill.style.transform = `scaleX(${hpRatio})`;
    this.el.hpGhost.style.transform = `scaleX(${hpRatio})`;
    this.el.hpText.textContent = String(Math.max(0, Math.ceil(player.hp)));
    this.el.hpFill.classList.toggle('low', hpRatio <= 0.3);
    this.el.hpGhost.style.transitionDelay = hpRatio < 0.3 ? '0s' : '.35s';

    const batteryRatio = clamp(player.battery / 100, 0, 1);
    this.el.batteryFill.style.transform = `scaleX(${batteryRatio})`;
    this.el.batteryText.textContent = `${Math.floor(player.battery)}%`;
    this.el.batteryMeter.classList.toggle('is-full', batteryRatio >= 1);
    this.el.batteryState.textContent = batteryRatio >= 1 ? 'LISTA' : batteryRatio > 0 ? 'CARGANDO' : 'VACÍA';
    this.el.batteryState.classList.toggle('ready', batteryRatio >= 1);
    this.el.specialBtn.classList.toggle('ready', batteryRatio >= 1);
    this.el.specialBtn.classList.toggle('locked', batteryRatio < 1);
    this.el.specialCharge.textContent = `${Math.floor(player.battery)}%`;
    this.el.specialBtn.style.setProperty('--charge', `${batteryRatio * 360}deg`);
    this.el.waveValue.textContent = String(this.game.wave).padStart(2, '0');
    this.el.killValue.textContent = String(this.game.kills).padStart(2, '0');

    if (this.contextTimer > 0) {
      this.contextTimer -= dt;
      if (this.contextTimer <= 0) this.el.contextTip.classList.remove('show');
    }
  }

  setWave(wave) {
    this.el.waveValue.textContent = String(wave).padStart(2, '0');
  }

  setKills(kills) {
    this.el.killValue.textContent = String(kills).padStart(2, '0');
  }

  comboHit(count, timerRatio) {
    const combo = this.el.comboDisplay;
    this.el.comboCount.textContent = String(count);
    let rank = 'EN RACHA';
    if (count >= 5) rank = 'IMPARABLE';
    if (count >= 10) rank = 'SALVAJE';
    if (count >= 18) rank = 'ANIME MODE';
    if (count >= 30) rank = 'LEYENDA NEÓN';
    this.el.comboRank.textContent = rank;
    this.el.comboTimer.style.transform = `scaleX(${clamp(timerRatio, 0, 1)})`;
    combo.classList.add('show');
    window.clearTimeout(this.comboHideTimer);
    this.comboHideTimer = window.setTimeout(() => combo.classList.remove('show'), 1500);
  }

  setCombo(count, timerRatio = 0) {
    if (count <= 0) {
      this.el.comboDisplay.classList.remove('show');
      return;
    }
    this.comboHit(count, timerRatio);
  }

  updateCombo(count, timerRatio) {
    if (count <= 0) {
      this.el.comboDisplay.classList.remove('show');
      return;
    }
    this.el.comboTimer.style.transform = `scaleX(${clamp(timerRatio, 0, 1)})`;
    window.clearTimeout(this.comboHideTimer);
    this.comboHideTimer = window.setTimeout(() => this.el.comboDisplay.classList.remove('show'), 1600);
  }

  banner(kicker, title, sub = '', variant = '', duration = 1.8) {
    this.bannerToken += 1;
    const token = this.bannerToken;
    const banner = this.el.banner;
    this.el.bannerKicker.textContent = kicker;
    this.el.bannerTitle.textContent = title;
    this.el.bannerSub.textContent = sub;
    banner.classList.remove('alert', 'danger');
    if (variant === 'alert') banner.classList.add('alert');
    if (variant === 'danger') banner.classList.add('danger');
    banner.classList.add('show');
    window.setTimeout(() => {
      if (token === this.bannerToken) banner.classList.remove('show');
    }, duration * 1000);
  }

  hideBanner() {
    this.bannerToken += 1;
    this.el.banner.classList.remove('show');
  }

  showContextTip(html, duration = 1.6) {
    if (!html) {
      this.el.contextTip.classList.remove('show');
      this.contextTimer = 0;
      this.contextText = '';
      return;
    }
    if (this.contextText !== html) {
      this.contextText = html;
      this.el.contextTip.innerHTML = html;
    }
    this.el.contextTip.classList.add('show');
    this.contextTimer = duration;
  }

  flashBattery() {
    this.el.batteryMeter.classList.remove('flash');
    // force reflow to replay the animation
    void this.el.batteryMeter.offsetWidth;
    this.el.batteryMeter.classList.add('flash');
    window.setTimeout(() => this.el.batteryMeter.classList.remove('flash'), 450);
  }

  showPause() {
    this.showScreen('pause');
  }

  showGameOver({ special, stats }) {
    this.el.goKicker.textContent = special ? 'SEGUNDA CAÍDA CONSECUTIVA' : 'FIN DEL COMBATE';
    this.el.goTitle.textContent = special ? 'LA ARENA TE LLAMA' : 'HAS CAÍDO';
    this.el.goCopy.textContent = special
      ? 'Dos caídas. El neón aún no ha terminado contigo. La decisión es tuya.'
      : 'La arena reclama otro nombre. Pero los neones siguen encendidos.';
    this.el.goWave.textContent = String(stats.wave).padStart(2, '0');
    this.el.goKills.textContent = String(stats.kills).padStart(2, '0');
    this.el.goCombo.textContent = String(stats.bestCombo || 0);
    this.el.goTime.textContent = stats.time;
    this.el.reviveOffer.classList.toggle('hidden', !special);
    this.el.offerDeaths.textContent = `${stats.deathCount} CAÍDAS CONSECUTIVAS`;
    this.el.goAdNote.classList.toggle('hidden', special);
    this.el.goAdNote.textContent = 'Sin anuncios en esta caída.';
    this.showScreen('gameover');
  }

  showAd() {
    this.el.adProgress.style.width = '0%';
    this.el.adCountdown.textContent = '5';
    this.el.adSkip.classList.remove('hidden');
    this.el.adClaim.classList.add('hidden');
    this.showScreen('ad');
  }

  updateAd(progress, secondsLeft) {
    this.el.adProgress.style.width = `${clamp(progress, 0, 1) * 100}%`;
    this.el.adCountdown.textContent = String(Math.max(0, Math.ceil(secondsLeft)));
    if (progress >= 1) {
      this.el.adSkip.classList.add('hidden');
      this.el.adClaim.classList.remove('hidden');
    }
  }

  showMenu() {
    this.showScreen('menu');
  }

  showHow() {
    this.showScreen('how');
  }
}

import { AudioEngine } from './audio.js';
import { FX } from './fx.js';
import { Input } from './input.js';
import { Scene } from './scene.js';
import { Player } from './player.js';
import { Enemy } from './enemy.js';
import { UI } from './ui.js';
import { drawStickman } from './stickman.js';
import { TAU, clamp, damp, formatTime, rand, randInt, pick, sign } from './utils.js';

export class Game {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d', { alpha: false });
    this.audio = new AudioEngine();
    this.fx = new FX();
    this.scene = new Scene();
    this.input = new Input();
    this.ui = new UI(this);

    this.state = 'menu';
    this.width = window.innerWidth;
    this.height = window.innerHeight;
    this.unit = 1;
    this.groundY = this.height * 0.76;
    this.ceilingY = 40;
    this.left = 40;
    this.right = this.width - 40;
    this.dpr = 1;

    this.enemies = [];
    this.player = null;
    this.wave = 1;
    this.kills = 0;
    this.deathCount = 0;
    this.specialGameOver = false;
    this.runTime = 0;
    this.waveState = 'fighting';
    this.waveClearTimer = 0;
    this.spawnQueue = [];
    this.spawnTimer = 0;
    this.spawnCap = 4;
    this.spawnSide = 'left';
    this.waveKills = 0;
    this.waveSpawned = 0;

    this.timeScale = 1;
    this.timeScaleTarget = 1;
    this.slowmoRemaining = 0;
    this.hitstopTimer = 0;
    this.shakeMagnitude = 0;
    this.shakeDuration = 0.001;
    this.shakeTimer = 0;
    this.shakeX = 0;
    this.shakeY = 0;
    this.realTime = 0;
    this.renderTime = 0;
    this.deathDelay = 0;
    this.pendingGameOver = false;
    this.adTimer = 0;
    this.adDuration = 5;
    this.adDone = false;
    this.lastTip = '';
    this.ambientTimer = 0;
    this.firstRun = true;

    this.resize();
    this.player = new Player(this, this.width * 0.5);
    this.player.facing = -1;
    this.input.onPause(() => {
      if (this.state === 'playing') this.togglePause();
      else if (this.state === 'paused') this.resume();
    });
    window.addEventListener('resize', () => this.resize());
    window.addEventListener('orientationchange', () => window.setTimeout(() => this.resize(), 120));
    this.ui.showMenu();
    this.scene.resize(this.width, this.height, this.groundY, this.left, this.right);
    window.__neonFist = this;
  }

  resize() {
    const rect = this.canvas.getBoundingClientRect();
    const width = Math.max(320, rect.width || window.innerWidth);
    const height = Math.max(320, rect.height || window.innerHeight);
    const dpr = Math.min(2, window.devicePixelRatio || 1);
    this.width = width;
    this.height = height;
    this.dpr = dpr;
    this.canvas.width = Math.round(width * dpr);
    this.canvas.height = Math.round(height * dpr);
    this.canvas.style.width = `${width}px`;
    this.canvas.style.height = `${height}px`;

    const portrait = width < 760 && height > width;
    const unit = clamp(Math.min(width / 1100, height / 680), 0.7, 1.22);
    this.unit = portrait ? clamp(width / 500, 0.72, 0.92) : unit;
    this.groundY = portrait
      ? height - clamp(height * 0.29, 230, 305)
      : height - clamp(height * 0.235, 140, 220);
    this.ceilingY = Math.max(18, height * 0.055);
    this.left = Math.max(24, width * 0.035);
    this.right = width - this.left;
    this.scene.resize(width, height, this.groundY, this.left, this.right);

    if (this.player) {
      this.player.unit = this.unit;
      this.player.scale = 1.06 * this.unit;
      this.player.radius = 16 * this.unit;
      this.player.x = clamp(this.player.x, this.left + this.player.radius, this.right - this.player.radius);
      if (this.player.onGround || this.player.state === 'idle') this.player.y = this.groundY;
    }
    for (const enemy of this.enemies) {
      enemy.unit = this.unit;
      enemy.scale = (enemy.heavy ? 1.2 : 0.98) * this.unit;
      enemy.radius = (enemy.heavy ? 20 : 15) * this.unit;
      enemy.x = clamp(enemy.x, this.left - 30 * this.unit, this.right + 30 * this.unit);
      if (enemy.onGround || enemy.state === 'approach' || enemy.state === 'idle') enemy.y = this.groundY;
    }
    if (this.state === 'menu' && this.player) {
      this.player.x = width * 0.5;
      this.player.y = this.groundY;
    }
  }

  // ---------------------------------------------------------------- flow

  startRun() {
    this.audio.ensure();
    this.ui.showScreen(null);
    this.state = 'playing';
    this.firstRun = false;
    this.kills = 0;
    this.wave = 1;
    this.runTime = 0;
    this.waveState = 'fighting';
    this.waveClearTimer = 0;
    this.spawnQueue = [];
    this.spawnTimer = 0.3;
    this.spawnCap = 4;
    this.spawnSide = 'left';
    this.waveKills = 0;
    this.waveSpawned = 0;
    this.specialGameOver = false;
    this.pendingGameOver = false;
    this.deathDelay = 0;
    this.timeScale = 1;
    this.timeScaleTarget = 1;
    this.slowmoRemaining = 0;
    this.hitstopTimer = 0;
    this.enemies.length = 0;
    this.fx.reset();
    this.player = new Player(this, this.width * 0.5);
    this.player.facing = 1;
    this.player.y = this.groundY;
    this.ui.setWave(1);
    this.ui.setKills(0);
    this.ui.setCombo(0, 0);
    this.ui.banner('OLEADA 01', 'SOBREVIVE', 'Los rojos atacan por ambos lados · usa la pared', '', 2.5);
    this.audio.wave();
    this.startWave(1, false);
    this.fx.ring(this.width * 0.5, this.groundY, {
      color: '#39f5ff',
      maxRadius: 160,
      life: 0.6,
      width: 3,
      squash: 0.25,
    });
  }

  restart() {
    if (this.specialGameOver) {
      this.deathCount = 0;
      this.specialGameOver = false;
    }
    this.startRun();
  }

  retry() {
    if (this.specialGameOver) {
      this.deathCount = 0;
      this.specialGameOver = false;
    }
    this.startRun();
  }

  toMenu(fromGameOver = false) {
    if (fromGameOver && this.specialGameOver) {
      this.deathCount = 0;
      this.specialGameOver = false;
    }
    this.state = 'menu';
    this.enemies.length = 0;
    this.fx.reset();
    this.spawnQueue = [];
    this.waveState = 'fighting';
    this.pendingGameOver = false;
    this.timeScale = 1;
    this.timeScaleTarget = 1;
    this.slowmoRemaining = 0;
    this.player = new Player(this, this.width * 0.5);
    this.player.facing = -1;
    this.player.y = this.groundY;
    this.player.alpha = 0.85;
    this.ui.showMenu();
    this.ui.setCombo(0, 0);
  }

  togglePause() {
    if (this.state === 'playing') {
      this.state = 'paused';
      this.ui.showPause();
      this.ui.showContextTip('', 0);
    } else if (this.state === 'paused') {
      this.resume();
    }
  }

  resume() {
    if (this.state !== 'paused') return;
    this.state = 'playing';
    this.ui.showScreen(null);
    this.input.clear();
  }

  openHow() {
    if (this.state !== 'menu') return;
    this.ui.showHow();
  }

  closeHow() {
    if (this.state !== 'menu') return;
    this.ui.showMenu();
  }

  toggleSound() {
    this.audio.ensure();
    this.audio.toggleMuted();
    this.ui.syncSound();
    if (!this.audio.muted) this.audio.ui();
  }

  // ---------------------------------------------------------------- waves

  startWave(wave, announce = true) {
    this.wave = wave;
    this.waveState = 'fighting';
    this.waveClearTimer = 0;
    this.waveKills = 0;
    this.waveSpawned = 0;
    this.spawnCap = Math.min(7, 3 + Math.floor(wave / 2));
    this.spawnTimer = announce ? 0.75 : 0.32;

    const quota = 4 + wave * 2;
    const heavies = wave >= 2 ? Math.min(4, 1 + Math.floor((wave - 2) / 2)) : 0;
    const types = [];
    for (let i = 0; i < quota; i += 1) types.push('red');
    for (let i = 0; i < heavies; i += 1) {
      const index = Math.min(types.length, 1 + i * 2);
      types.splice(index, 0, 'heavy');
    }
    this.spawnQueue = types.map((type, index) => ({
      type,
      variant: type === 'heavy' ? (index % 2 === 0 ? 'gold' : 'green') : 'red',
    }));
    this.ui.setWave(wave);
    if (announce) {
      const title = wave === 1 ? 'SOBREVIVE' : wave === 2 ? 'REFUERZOS' : pick(['SIN PAUSA', 'MÁS RÁPIDO', 'LA ARENA ARDE', 'SIGUE EN PIE']);
      const sub = wave === 2
        ? 'Llegan los blindados: agarra, lanza o usa la pared'
        : wave >= 3
          ? `${quota} enemigos · ${heavies} blindados · sin descanso`
          : 'Los rojos atacan por ambos lados · usa la pared';
      this.ui.banner(`OLEADA ${String(wave).padStart(2, '0')}`, title, sub, wave >= 4 ? 'alert' : '', 2.3);
      this.audio.wave();
    }
  }

  spawnEnemy(type, variant) {
    const heavy = type === 'heavy';
    const side = this.spawnSide;
    this.spawnSide = side === 'left' ? 'right' : 'left';
    let enemy;
    if (heavy) {
      const x = clamp(this.player.x + rand(-250, 250) * this.unit, this.left + 90 * this.unit, this.right - 90 * this.unit);
      enemy = new Enemy(this, type, {
        variant,
        side,
        spawnMode: 'drop',
        x,
        y: -40,
      });
      this.fx.ring(x, this.groundY, {
        color: enemy.palette.main,
        maxRadius: 110 * this.unit,
        life: 0.75,
        width: 3,
        squash: 0.24,
        delay: 0.38,
      });
      this.fx.text(x, this.groundY - 200 * this.unit, 'PESADO ENTRANDO', {
        color: enemy.palette.main,
        size: 11,
        life: 0.9,
        vy: -22,
      });
      this.audio.whoosh(1.5);
    } else {
      const x = side === 'left' ? this.left - 42 * this.unit : this.right + 42 * this.unit;
      enemy = new Enemy(this, type, { variant: 'red', side, spawnMode: 'walk', x });
    }
    this.enemies.push(enemy);
    this.waveSpawned += 1;
  }

  get aliveEnemies() {
    return this.enemies.filter((enemy) => enemy && !enemy.countedDead && enemy.state !== 'dead');
  }

  updateWaves(dt) {
    if (this.state !== 'playing' || this.pendingGameOver) return;
    if (this.waveState === 'cleared') {
      this.waveClearTimer -= dt;
      if (this.waveClearTimer <= 0) {
        this.startWave(this.wave + 1, true);
        this.player?.heal(8);
      }
      return;
    }

    if (this.spawnQueue.length > 0) {
      this.spawnTimer -= dt;
      const alive = this.aliveEnemies.length;
      if (this.spawnTimer <= 0 && alive < this.spawnCap) {
        const next = this.spawnQueue.shift();
        this.spawnEnemy(next.type, next.variant);
        this.spawnTimer = clamp(0.95 - this.wave * 0.035, 0.38, 0.95) * rand(0.82, 1.18);
      }
    }

    if (this.spawnQueue.length === 0 && this.aliveEnemies.length === 0) {
      this.waveState = 'cleared';
      this.waveClearTimer = 2.35;
      this.ui.banner(
        `OLEADA ${String(this.wave).padStart(2, '0')} LIMPIA`,
        'SIGUE EN PIE',
        `+8 HP · BATERÍA +12 · siguiente oleada`,
        'alert',
        2.1,
      );
      this.player?.heal(8);
      this.player?.addBattery(12);
      this.audio.wave();
      this.fx.ring(this.player.x, this.groundY, {
        color: '#ffd34d',
        maxRadius: 190 * this.unit,
        life: 0.65,
        width: 3,
        squash: 0.25,
      });
    }
  }

  // ---------------------------------------------------------------- combat

  hitEnemy(enemy, options = {}) {
    if (!enemy || enemy.state === 'dead' || enemy.countedDead) return false;
    const result = enemy.takeHit(options.damage ?? 10, options.kind || 'light', options);
    if (!result.hit) return false;
    if (result.absorbed) {
      this.shake(3, 0.12);
      return false;
    }
    const hitX = options.hitX ?? enemy.x;
    const hitY = options.hitY ?? enemy.y - 65 * this.unit;
    if (!options.silent && options.damage > 0) {
      const color = options.kind === 'dragon' ? '#ffd34d'
        : options.kind === 'special' || options.kind === 'specialWave' ? '#aefcff'
          : options.kind === 'throw' || options.kind === 'thrownBody' ? '#ff9ecf'
            : options.kind === 'dive' ? '#bffcff'
              : '#ffffff';
      this.fx.text(hitX + rand(-6, 6), hitY - 16, `-${Math.round(options.damage)}`, {
        color,
        size: options.dramatic ? 20 : 15,
        life: 0.7,
        vy: -72,
        vx: rand(-22, 22),
      });
    }
    if (result.killed) {
      this.fx.text(hitX, hitY - 64, 'K.O.', {
        color: '#ffd34d',
        size: 30,
        life: 1.1,
        vy: -44,
      });
      this.fx.screenFlash('#ffffff', 0.12, 5);
      this.shake(10, 0.24);
    }
    return true;
  }

  registerKill(enemy) {
    this.kills += 1;
    this.waveKills += 1;
    this.ui.setKills(this.kills);
    this.audio.combo(Math.min(9, 4 + Math.floor(this.kills / 3)));
    this.fx.text(enemy.x, enemy.y - 120 * this.unit, '+1', {
      color: enemy.palette.main,
      size: 12,
      life: 0.6,
      vy: -55,
    });
    if (this.player) {
      this.player.bestCombo = Math.max(this.player.bestCombo, this.player.combo);
    }
  }

  removeEnemy(enemy) {
    const index = this.enemies.indexOf(enemy);
    if (index >= 0) this.enemies.splice(index, 1);
  }

  onPlayerDeath() {
    if (this.pendingGameOver) return;
    this.pendingGameOver = true;
    this.deathDelay = 1.55;
    this.timeScaleTarget = 0.58;
    this.shake(20, 0.5);
    this.fx.screenFlash('#ff1f45', 0.25, 2.4);
    this.audio.death();
    this.ui.setCombo(0, 0);
    this.ui.showContextTip('', 0);
    this.fx.ring(this.player.x, this.player.y - 60 * this.unit, {
      color: '#ff3b4e',
      maxRadius: 190 * this.unit,
      life: 0.8,
      width: 4,
      squash: 0.7,
    });
  }

  showGameOver() {
    this.deathCount += 1;
    this.specialGameOver = this.deathCount >= 2;
    this.state = 'gameover';
    this.pendingGameOver = false;
    this.timeScale = 1;
    this.timeScaleTarget = 1;
    this.ui.showGameOver({
      special: this.specialGameOver,
      deathCount: this.deathCount,
      stats: {
        wave: this.wave,
        kills: this.kills,
        bestCombo: this.player?.bestCombo || 0,
        time: formatTime(this.runTime),
      },
    });
    this.audio.wave();
  }

  acceptRevive() {
    if (this.state !== 'gameover' || !this.specialGameOver) return;
    this.deathCount = 0;
    this.specialGameOver = false;
    this.state = 'ad';
    this.adTimer = 0;
    this.adDone = false;
    this.ui.showAd();
    this.audio.ui();
  }

  finishAd() {
    if (this.state !== 'ad') return;
    this.deathCount = 0;
    this.specialGameOver = false;
    this.adDone = true;
    this.state = 'playing';
    this.ui.showScreen(null);
    this.player.revive();
    this.player.x = this.width * 0.5;
    this.player.y = this.groundY;
    this.player.facing = 1;
    this.player.vx = 0;
    this.player.vy = 0;
    this.player.onGround = true;
    this.player.invuln = 2.8;
    this.pendingGameOver = false;
    this.deathDelay = 0;
    this.hitstopTimer = 0;
    this.timeScale = 1;
    this.timeScaleTarget = 1;
    this.slowmoRemaining = 0;
    this.fx.ring(this.player.x, this.groundY, {
      color: '#ffd34d',
      maxRadius: 240 * this.unit,
      life: 0.8,
      width: 5,
      squash: 0.3,
    });
    this.fx.burst(this.player.x, this.groundY - 60 * this.unit, {
      count: 30,
      color: '#ffd34d',
      speed: 520,
      spread: TAU,
      gravity: 400,
      size: 3.2,
      life: 0.9,
    });
    this.fx.screenFlash('#fff3b8', 0.2, 3);
    this.shake(14, 0.4);
    this.audio.revive();
    this.ui.banner('REVIVIDO', '50% DE VIDA', 'La arena te da otra oportunidad', 'alert', 2.0);
    for (const enemy of this.enemies) {
      if (enemy.state === 'dead') continue;
      if (Math.abs(enemy.x - this.player.x) < 260 * this.unit) {
        this.hitEnemy(enemy, {
          damage: 14,
          kind: 'reviveBlast',
          vx: (enemy.x < this.player.x ? -1 : 1) * 780 * this.unit,
          vy: -540 * this.unit,
          batteryGain: 0,
          source: 'revive',
          dramatic: true,
          allowArmorBreak: true,
          hitY: enemy.y - 55 * this.unit,
        });
      }
    }
    this.spawnTimer = Math.max(this.spawnTimer, 0.7);
  }

  // ---------------------------------------------------------------- time / camera

  shake(magnitude, duration) {
    if (magnitude >= this.shakeMagnitude || this.shakeTimer <= 0) {
      this.shakeMagnitude = magnitude;
      this.shakeDuration = duration;
      this.shakeTimer = duration;
    }
  }

  hitstop(duration) {
    this.hitstopTimer = Math.max(this.hitstopTimer, duration);
  }

  startSlowMo(duration = 3.2) {
    this.slowmoRemaining = Math.max(this.slowmoRemaining, duration);
    this.timeScaleTarget = 0.4;
  }

  endSlowMo() {
    this.slowmoRemaining = 0;
    this.timeScaleTarget = 1;
  }

  showContextTip(html, duration = 1.6) {
    this.ui.showContextTip(html, duration);
  }

  updateCamera(realDt) {
    if (this.shakeTimer > 0) {
      this.shakeTimer -= realDt;
      const ratio = clamp(this.shakeTimer / this.shakeDuration, 0, 1);
      const intensity = this.shakeMagnitude * ratio * ratio;
      const phase = this.realTime * 83;
      this.shakeX = Math.sin(phase) * intensity * 0.65 + Math.sin(phase * 1.9) * intensity * 0.25;
      this.shakeY = Math.cos(phase * 1.23) * intensity * 0.5;
      if (this.shakeTimer <= 0) {
        this.shakeMagnitude = 0;
        this.shakeX = 0;
        this.shakeY = 0;
      }
    } else {
      this.shakeX *= 0.8;
      this.shakeY *= 0.8;
    }
  }

  // ---------------------------------------------------------------- loop

  update(realDt) {
    const dt = Math.min(realDt, 0.05);
    this.realTime += dt;
    this.updateCamera(dt);
    this.ui.update(dt);

    if (this.state === 'menu' || this.state === 'how') {
      this.scene.update(dt * 0.7);
      this.player.animTime += dt;
      this.player.state = 'idle';
      this.fx.update(dt);
      return;
    }

    if (this.state === 'paused') {
      return;
    }

    if (this.state === 'gameover') {
      this.scene.update(dt * 0.25);
      this.fx.update(dt * 0.25);
      return;
    }

    if (this.state === 'ad') {
      this.scene.update(dt * 0.2);
      this.fx.update(dt * 0.2);
      this.adTimer += dt;
      this.ui.updateAd(this.adTimer / this.adDuration, this.adDuration - this.adTimer);
      if (this.adTimer >= this.adDuration && !this.adDone) {
        this.ui.updateAd(1, 0);
      }
      if (this.adTimer >= this.adDuration + 2.2 && !this.adDone) {
        this.finishAd();
      }
      return;
    }

    // Slow motion timing is real-time so the effect always feels snappy.
    if (this.slowmoRemaining > 0) {
      this.slowmoRemaining -= dt;
      if (this.slowmoRemaining <= 0) this.timeScaleTarget = 1;
    }
    this.timeScale = damp(this.timeScale, this.timeScaleTarget, 11, dt);

    if (this.hitstopTimer > 0) {
      this.hitstopTimer -= dt;
      this.fx.update(dt * 0.15);
      return;
    }

    const scaled = dt * this.timeScale;
    this.runTime += scaled;
    this.scene.update(scaled);
    this.fx.update(scaled);

    if (this.pendingGameOver) {
      this.player.updateDead(scaled);
      for (const enemy of this.enemies) enemy.update(scaled, this.player);
      this.deathDelay -= dt;
      if (this.deathDelay <= 0) this.showGameOver();
      return;
    }

    this.player.update(scaled, this.input);
    for (const enemy of this.enemies) {
      enemy.update(scaled, this.player);
    }
    this.separateEnemies();
    this.updateWaves(scaled);
    this.updateComboUi();

    // Remove dead entities that faded out
    for (let i = this.enemies.length - 1; i >= 0; i -= 1) {
      if (!this.enemies[i] || this.enemies[i].alpha <= 0) this.enemies.splice(i, 1);
    }

    if (this.player.combo > 0) {
      this.player.bestCombo = Math.max(this.player.bestCombo, this.player.combo);
    }
  }

  separateEnemies() {
    const active = this.enemies.filter((enemy) => enemy && !['grabbed', 'ragdoll', 'dead'].includes(enemy.state) && enemy.onGround);
    for (let i = 0; i < active.length; i += 1) {
      for (let j = i + 1; j < active.length; j += 1) {
        const a = active[i];
        const b = active[j];
        const dx = b.x - a.x;
        const minDistance = (a.radius + b.radius) * 1.4;
        if (Math.abs(dx) < minDistance) {
          const push = (minDistance - Math.abs(dx)) * 0.5;
          const dir = dx === 0 ? (a.id < b.id ? 1 : -1) : sign(dx);
          a.x -= dir * push;
          b.x += dir * push;
          a.x = clamp(a.x, this.left + a.radius, this.right - a.radius);
          b.x = clamp(b.x, this.left + b.radius, this.right - b.radius);
        }
      }
      const playerDistance = Math.abs(active[i].x - this.player.x);
      if (playerDistance < (active[i].radius + this.player.radius) * 0.9 && Math.abs(active[i].y - this.player.y) < 40) {
        const dir = active[i].x < this.player.x ? -1 : 1;
        active[i].x += dir * 2.4 * this.unit;
        active[i].x = clamp(active[i].x, this.left + active[i].radius, this.right - active[i].radius);
      }
    }
  }

  updateComboUi() {
    if (!this.player) return;
    if (this.player.combo > 0) {
      this.player.comboTimer = Math.max(0, this.player.comboTimer);
      this.ui.updateCombo(this.player.combo, this.player.comboTimer / 1.7);
      if (this.player.comboTimer <= 0) {
        this.player.combo = 0;
        this.ui.setCombo(0, 0);
      }
    }
  }

  draw() {
    const ctx = this.ctx;
    const { width, height } = this;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, width, height);

    const shakeRatio = this.shakeTimer > 0 ? clamp(this.shakeTimer / this.shakeDuration, 0, 1) : 0;
    const zoom = 1.004 + (this.shakeMagnitude * shakeRatio * shakeRatio) * 0.0009;
    ctx.save();
    ctx.translate(width / 2 + this.shakeX, height / 2 + this.shakeY);
    ctx.scale(zoom, zoom);
    ctx.translate(-width / 2, -height / 2);

    this.scene.draw(ctx);

    if (this.state === 'menu' || this.state === 'how') {
      if (this.player) {
        this.player.alpha = 0.5;
        this.player.animTime += 0.003;
        drawStickman(ctx, this.player, { groundY: this.groundY });
        this.player.alpha = 1;
      }
    } else {
      const entities = this.enemies.filter(Boolean).slice();
      if (this.player) entities.push(this.player);
      entities.sort((a, b) => a.y - b.y);
      for (const entity of entities) {
        drawStickman(ctx, entity, { groundY: this.groundY });
      }
    }

    this.scene.drawForeground(ctx);
    this.fx.draw(ctx, this.groundY);

    // Bullet-time tint sits over the action, under the flash
    if (this.timeScale < 0.94 && this.state === 'playing') {
      const intensity = 1 - this.timeScale;
      ctx.save();
      ctx.globalAlpha = 0.12 * intensity;
      ctx.fillStyle = '#1a6dff';
      ctx.fillRect(0, 0, width, height);
      ctx.globalAlpha = 0.45 * intensity;
      ctx.strokeStyle = 'rgba(140, 235, 255, 0.5)';
      ctx.lineWidth = 1;
      for (let i = 0; i < 14; i += 1) {
        const y = ((i * 97 + this.realTime * 190) % (height * 0.8)) + height * 0.05;
        const length = 30 + ((i * 37) % 90);
        const side = i % 2 === 0 ? 0 : width;
        ctx.beginPath();
        ctx.moveTo(side, y);
        ctx.lineTo(side + (i % 2 === 0 ? length : -length), y + 1.5);
        ctx.stroke();
      }
      ctx.restore();
    }

    this.fx.drawScreen(ctx, width, height);
    this.drawFrameOverlay(ctx);
    ctx.restore();
  }

  drawFrameOverlay(ctx) {
    const { width, height } = this;
    if (this.state === 'playing' || this.state === 'dying') {
      const hpRatio = this.player ? this.player.hp / this.player.maxHp : 1;
      if (hpRatio < 0.3) {
        const danger = (1 - hpRatio / 0.3) * (0.09 + Math.sin(this.realTime * 6) * 0.025);
        const gradient = ctx.createRadialGradient(width / 2, height / 2, Math.min(width, height) * 0.2, width / 2, height / 2, Math.max(width, height) * 0.65);
        gradient.addColorStop(0, 'rgba(255, 20, 50, 0)');
        gradient.addColorStop(1, `rgba(255, 20, 50, ${clamp(danger, 0, 0.3)})`);
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, width, height);
      }
    }

    // Top & bottom cinematic edges, subtle
    const top = ctx.createLinearGradient(0, 0, 0, 70);
    top.addColorStop(0, 'rgba(0, 3, 10, 0.5)');
    top.addColorStop(1, 'rgba(0, 3, 10, 0)');
    ctx.fillStyle = top;
    ctx.fillRect(0, 0, width, 70);
    const bottom = ctx.createLinearGradient(0, height - 90, 0, height);
    bottom.addColorStop(0, 'rgba(0, 3, 10, 0)');
    bottom.addColorStop(1, 'rgba(0, 3, 10, 0.45)');
    ctx.fillStyle = bottom;
    ctx.fillRect(0, height - 90, width, 90);
  }
}

import { Game } from './game.js';

const canvas = document.getElementById('game');
const errorPanel = document.getElementById('bootError');
const errorText = document.getElementById('bootErrorText');

try {
  const game = new Game(canvas);
  game.draw();

  let last = performance.now();
  const frame = (now) => {
    const dt = Math.min(0.05, Math.max(0, (now - last) / 1000));
    last = now;
    try {
      game.update(dt);
      game.draw();
    } catch (error) {
      console.error(error);
      if (errorPanel && errorText) {
        errorPanel.classList.remove('hidden');
        errorText.textContent = error instanceof Error ? error.message : String(error);
      }
    } finally {
      game.input.endFrame();
      requestAnimationFrame(frame);
    }
  };
  requestAnimationFrame(frame);

  document.addEventListener('visibilitychange', () => {
    if (document.hidden && game.state === 'playing') game.togglePause();
  });

  // Prevent browser pinch-zoom on the play surface while keeping UI accessible.
  document.addEventListener('gesturestart', (event) => event.preventDefault());
  document.addEventListener('dblclick', (event) => event.preventDefault(), { passive: false });
} catch (error) {
  console.error(error);
  if (errorPanel && errorText) {
    errorPanel.classList.remove('hidden');
    errorText.textContent = error instanceof Error ? error.message : String(error);
  }
}

