168:     this.animTime += dt;
169:     this.stateTime += dt;
170:     this.invuln = Math.max(0, this.invuln - dt);
171:     this.flash = Math.max(0, this.flash - dt);
172:     this.chainTimer = Math.max(0, this.chainTimer - dt);
173:     this.comboTimer = Math.max(0, this.comboTimer - dt);
174:     this.auraScale = 1 + (this.charged ? Math.sin(this.animTime * 5) * 0.08 : 0);
175:     if (this.comboTimer <= 0 && this.combo > 0) {
176:       this.combo = 0;
177:       this.game.ui.setCombo(0, 0);
178:     }
179: 
180:     // Timed visual invulnerability flicker
181:     if (this.invuln > 0 && this.state !== 'special') {
182:       this.alpha = 0.55 + Math.abs(Math.sin(this.animTime * 28)) * 0.45;
183:     } else {
184:       this.alpha = 1;
185:     }
