187:     this.updateStateLogic(dt, input);
188:     this.handleInput(dt, input);
189:     this.updatePhysics(dt, input);
190:     this.updateAttackHits();
191:     this.updateHeldEnemy();
192:     this.updateVisualTrail(dt);
193: 
194:     if (this.state === 'wall') {
195:       this.game.showContextTip('<b>SALTO DE PARED</b> · pulsa SALTO para la patada descendente', 0.18);
196:     }
