199:   updateStateLogic(dt, input) {
200:     const state = this.state;
201: 
202:     if (state === 'wall') {
203:       this.wallTimer -= dt;
204:       if (this.wallTimer <= 0 || (this.wallSide === 'left' && input.move > 0) || (this.wallSide === 'right' && input.move < 0)) {
205:         this.leaveWall();
206:       }
207:     }
208: 
209:     if (state === 'grab') {
210:       this.grabTimer -= dt;
211:       if (!this.grabTarget || this.grabTarget.state === 'dead' || this.grabTarget.hp <= 0) {
212:         this.releaseGrab();
213:       } else if (this.grabTimer <= 0) {
214:         this.releaseGrab();
215:       }
216:       const throwPressed = input.wasPressed('light') || input.wasPressed('heavy') || input.wasPressed('grab') || input.wasPressed('down');
217:       if (this.grabTarget && throwPressed) {
218:         this.throwGrab();
219:       }
220:       return;
221:     }
222: 
223:     if (state === 'suplex') {
224:       this.updateSuplex(dt);
225:       return;
226:     }
227: 
228:     if (state === 'special') {
229:       this.updateSpecial(dt);
230:       return;
231:     }
232: 
233:     if (state === 'hurt') {
234:       if (this.stateTime >= this.stateDuration) {
235:         this.setState(this.onGround ? 'idle' : 'fall');
236:       }
237:       return;
238:     }
239: 
240:     if (state === 'attack' || state === 'heavy' || state === 'dragon' || state === 'spin' || state === 'throw') {
241:       const progress = this.stateDuration > 0 ? this.stateTime / this.stateDuration : 1;
242:       if (this.stateTime >= this.stateDuration) {
243:         this.chainTimer = 0.68;
244:         this.setState(this.onGround ? 'idle' : 'fall');
245:         this.vx *= 0.35;
246:         this.attackHitSet.clear();
247:         return;
248:       }
249:       // allow a cancel into the next attack or jump late in the recovery
250:       if (progress < 0.55) return;
251:     }
252: 
253:     // Crouch handling
254:     if (this.onGround && input.isDown('down') && ['idle', 'run', 'crouch'].includes(this.state)) {
255:       if (this.state !== 'crouch') this.setState('crouch');
256:       this.vx = approach(this.vx, 0, 2800 * this.unit * dt);
257:       return;
258:     }
259:     if (this.state === 'crouch' && !input.isDown('down')) {
260:       this.setState('idle');
261:     }
262:   }
