264:   handleInput(dt, input) {
265:     if (this.state === 'hurt' || this.state === 'dead' || this.state === 'grab' || this.state === 'suplex') return;
266:     if (this.state === 'special') return;
267: 
268:     if (this.state === 'wall') {
269:       if (input.wasPressed('jump')) {
270:         this.wallJump();
271:       }
272:       return;
273:     }
274: 
275:     // Wall jump can also be triggered if the player is pressed against a wall midair
276:     if (!this.onGround && (input.wasPressed('jump')) && this.nearWall()) {
277:       this.wallJump(true);
278:       return;
279:     }
280: 
281:     const attacking = ['attack', 'heavy', 'dragon', 'spin', 'throw'].includes(this.state);
282:     const canAct = ['idle', 'run', 'crouch', 'jump', 'fall', 'dive'].includes(this.state) || attacking;
283:     if (!canAct) return;
284: 
285:     if (input.wasPressed('special') && this.battery >= 100) {
286:       this.startSpecial();
287:       return;
288:     }
289: 
290:     if (input.wasPressed('grab')) {
291:       if (this.tryGrab()) return;
292:       if (!attacking) {
293:         this.setState('attack', 0.22);
294:         this.attackKind = 'grabWhiff';
295:         this.attackHitSet.clear();
296:         this.game.audio.whoosh(0.5);
297:       }
298:       return;
299:     }
300: 
301:     if (input.wasPressed('jump')) {
302:       if (this.onGround || this.state === 'crouch') {
303:         this.jump();
304:         return;
305:       }
306:     }
307: 
308:     if (input.wasPressed('heavy')) {
309:       if (!this.onGround) {
310:         this.startAttack('airspin');
311:       } else if (input.isDown('down')) {
312:         this.startAttack('dragon');
313:       } else {
314:         this.startAttack('heavy');
315:       }
316:       return;
317:     }
318: 
319:     if (input.wasPressed('light')) {
320:       this.startAttack('light');
321:     }
322:   }
