408:   startAttack(kind) {
409:     const air = !this.onGround;
410:     const alreadyAttacking = ['attack', 'heavy'].includes(this.state) && this.stateTime > this.stateDuration * 0.45;
411:     let duration = 0.26;
412:     if (kind === 'light') {
413:       const chaining = this.chainTimer > 0 || (alreadyAttacking && this.attackKind === 'light');
414:       this.attackChain = chaining ? (this.attackChain + 1) % 3 : 0;
415:       duration = [0.24, 0.23, 0.34][this.attackChain];
416:       this.setState('attack', duration);
417:       this.facing = this.facing || 1;
418:       // small forward step
419:       this.vx = this.facing * (air ? 80 : 170) * this.unit;
420:     } else if (kind === 'heavy') {
421:       this.attackChain = 0;
422:       duration = 0.46;
423:       this.setState('heavy', duration);
424:       this.vx = this.facing * 210 * this.unit;
425:     } else if (kind === 'dragon') {
426:       this.attackChain = 0;
427:       duration = 0.64;
428:       this.setState('dragon', duration);
429:       this.vy = -280 * this.unit;
430:       this.onGround = false;
431:       this.vx = this.facing * 110 * this.unit;
432:     } else if (kind === 'airspin') {
433:       this.attackChain = 0;
434:       duration = 0.52;
435:       this.setState('spin', duration);
436:       this.spinAngle = 0;
437:       this.vx *= 0.55;
438:     }
439:     this.attackKind = kind;
440:     this.attackHitSet.clear();
441:     this.attackLungeApplied = false;
442:     this.game.audio.whoosh(kind === 'heavy' || kind === 'dragon' ? 1.5 : 0.8);
443:     if (kind === 'dragon') {
444:       this.game.fx.ring(this.x, this.y, { color: '#ffd34d', maxRadius: 54, life: 0.3, width: 2, squash: 0.35 });
445:       this.game.fx.burst(this.x, this.y, { count: 9, color: '#ffe47a', speed: 220, angle: -Math.PI / 2, spread: 1.1, gravity: 240, size: 2.4, life: 0.4 });
446:     }
447:   }
