449:   updateAttackHits() {
450:     const state = this.state;
451:     if (!['attack', 'heavy', 'dragon', 'spin', 'dive'].includes(state)) return;
452:     const progress = this.stateDuration > 0 ? this.stateTime / this.stateDuration : 1;
453:     if (state === 'attack' && this.attackKind === 'grabWhiff') return;
454: 
455:     let active = false;
456:     if (state === 'attack') active = progress > 0.2 && progress < 0.58;
457:     else if (state === 'heavy') active = progress > 0.32 && progress < 0.65;
458:     else if (state === 'dragon') active = progress > 0.16 && progress < 0.58;
459:     else if (state === 'spin') active = progress > 0.08 && progress < 0.72;
460:     else if (state === 'dive') active = true;
461:     if (!active) return;
462: 
463:     const unit = this.unit;
464:     const enemies = this.game.enemies;
465:     for (const enemy of enemies) {
466:       if (!enemy || enemy.state === 'dead' || enemy.state === 'grabbed' || this.attackHitSet.has(enemy.id)) continue;
467: 
468:       let hit = false;
469:       let damage = 0;
470:       let vx = 0;
471:       let vy = 0;
472:       let kind = 'light';
473:       let batteryGain = 0;
474:       let hitY = this.y - 66 * unit;
475: 
476:       if (state === 'attack') {
477:         const reach = (this.attackChain === 2 ? 88 : 76) * unit;
478:         const hitX = this.x + this.facing * reach * 0.5;
479:         if (Math.abs(enemy.x - hitX) < reach * 0.5 + 20 * unit && enemy.y > this.y - 150 * unit && enemy.y < this.y + 34 * unit) {
480:           hit = true;
481:           if (this.attackChain === 2) {
482:             damage = 13;
483:             vx = this.facing * 690 * unit;
484:             vy = -540 * unit;
485:             kind = 'finisher';
486:             batteryGain = 7;
487:           } else {
488:             damage = 7 + this.attackChain;
489:             vx = this.facing * (240 + this.attackChain * 90) * unit;
490:             vy = -190 * unit;
491:             kind = 'light';
492:             batteryGain = 4;
493:           }
494:           hitY = enemy.y - 64 * unit;
495:         }
496:       } else if (state === 'heavy') {
497:         const reach = 102 * unit;
498:         const hitX = this.x + this.facing * reach * 0.48;
499:         if (Math.abs(enemy.x - hitX) < reach * 0.5 + 22 * unit && enemy.y > this.y - 160 * unit && enemy.y < this.y + 36 * unit) {
500:           hit = true;
501:           damage = 19;
502:           vx = this.facing * 760 * unit;
503:           vy = -570 * unit;
504:           kind = 'heavy';
505:           batteryGain = 9;
506:           hitY = enemy.y - 62 * unit;
507:         }
508:       } else if (state === 'dragon') {
509:         const reach = 88 * unit;
510:         const hitX = this.x + this.facing * reach * 0.35;
511:         if (Math.abs(enemy.x - hitX) < reach * 0.65 + 18 * unit && enemy.y > this.y - 230 * unit && enemy.y < this.y + 44 * unit) {
512:           hit = true;
513:           damage = 27;
514:           vx = this.facing * 210 * unit;
515:           vy = -1120 * unit;
516:           kind = 'dragon';
517:           batteryGain = 13;
518:           hitY = enemy.y - 66 * unit;
519:         }
520:       } else if (state === 'spin') {
521:         const radius = 126 * unit;
522:         if (Math.abs(enemy.x - this.x) < radius + 18 * unit && enemy.y > this.y - 150 * unit && enemy.y < this.y + 40 * unit) {
523:           hit = true;
524:           damage = 16;
525:           vx = (enemy.x < this.x ? -1 : 1) * 620 * unit;
526:           vy = -410 * unit;
527:           kind = 'spin';
528:           batteryGain = 6;
529:           hitY = enemy.y - 62 * unit;
530:         }
531:       } else if (state === 'dive') {
532:         if (Math.abs(enemy.x - this.x) < 92 * unit && enemy.y > this.y - 45 * unit && enemy.y < this.y + 220 * unit) {
533:           hit = true;
534:           damage = 34;
535:           vx = (enemy.x < this.x ? -1 : 1) * 420 * unit;
536:           vy = 690 * unit;
537:           kind = 'dive';
538:           batteryGain = 15;
539:           hitY = enemy.y - 54 * unit;
540:         }
541:       }
542: 
543:       if (!hit) continue;
544:       this.attackHitSet.add(enemy.id);
545: 
546:       const landed = this.game.hitEnemy(enemy, {
547:         damage,
548:         kind,
549:         vx,
550:         vy,
551:         batteryGain,
552:         source: 'player',
553:         hitX: enemy.x,
554:         hitY,
555:         dramatic: kind !== 'light',
556:         allowArmorBreak: ['dragon', 'dive'].includes(state),
557:       });
558: 
559:       if (landed) {
560:         const hitAngle = Math.atan2(hitY - (this.y - 70 * unit), enemy.x - this.x);
561:         this.game.fx.impact(enemy.x, hitY, hitAngle, kind === 'heavy' || kind === 'dragon' || kind === 'dive' ? 1.5 : 1, kind === 'dragon' ? '#ffe47a' : '#8ffbff');
562:         this.game.hitstop(kind === 'heavy' || kind === 'dragon' ? 0.075 : kind === 'dive' ? 0.09 : 0.035);
563:         this.game.shake(kind === 'dive' ? 13 : kind === 'dragon' ? 11 : 5, 0.18);
564:         this.game.audio[kind === 'dive' || kind === 'dragon' ? 'hitHeavy' : 'hitLight']();
565: 
566:         if (state === 'dive') {
567:           this.diveBounces += 1;
568:           if (this.diveBounces < 3) {
569:             this.vy = -430 * unit;
570:             this.vx *= 0.82;
571:           }
572:         }
573:       }
574:     }
575:   }
576: 
577:   updateSpecial(dt) {
578:     const progress = this.stateDuration > 0 ? this.stateTime / this.stateDuration : 1;
579:     this.attackHitSet.clear();
580:     this.invuln = Math.max(this.invuln, 0.1);
581: 
582:     if (progress > 0.1 && progress < 0.86) {
583:       this.vx = this.facing * 280 * this.unit;
584:     } else {
585:       this.vx *= 0.82;
586:     }
587: 
588:     if (progress > 0.08 && progress < 0.92) {
589:       const unit = this.unit;
590:       for (const enemy of this.game.enemies) {
591:         if (!enemy || enemy.state === 'dead' || enemy.state === 'grabbed' || this.specialHits.has(enemy.id)) continue;
592:         const inFront = (enemy.x - this.x) * this.facing > -34 * unit;
593:         if (Math.abs(enemy.x - this.x) < 185 * unit && inFront && enemy.y > this.y - 180 * unit && enemy.y < this.y + 60 * unit) {
594:           this.specialHits.add(enemy.id);
595:           const hitY = enemy.y - 66 * unit;
596:           const landed = this.game.hitEnemy(enemy, {
597:             damage: 36,
