955:         this.vx = approach(this.vx, targetSpeed, (targetSpeed !== 0 ? 3900 : 2700) * unit * dt);
956:         if (input.move !== 0) this.facing = input.move > 0 ? 1 : -1;
957:         if (Math.abs(this.vx) > 24 && this.state !== 'crouch') {
