171:     pose.hipY = BASE_HIP;
172:     pose.lean = 0.35;
173:     pose.armFront = [2.5, 2.8];
174:     pose.armBack = [2.35, 2.7];
175:     pose.legFront = [0.75, 0.5];
176:     pose.legBack = [-0.5, -0.2];
