213:     pose.lean = 0.1;
214:     pose.rotation = char.rot || 0;
215:     pose.rotationPivot = -58;
216:     pose.armFront = [0.8 + Math.sin(flail) * 0.7, 1.2 + Math.sin(flail + 1.7) * 0.9];
217:     pose.armBack = [-0.9 + Math.sin(flail + 2.1) * 0.65, -1.4 + Math.sin(flail + 0.8) * 0.8];
