222:     pose.hipY = -52;
223:     pose.lean = -0.15 + struggle * 0.08;
224:     pose.armFront = [1.1 + struggle * 0.4, 1.8 + struggle * 0.3];
225:     pose.armBack = [-1.2 - struggle * 0.3, -1.8 - struggle * 0.2];
