231:     pose.lean = -0.08;
232:     pose.armFront = [2.3, 2.8];
233:     pose.armBack = [-0.4, -0.1];
234:     pose.legFront = [0.25, -0.2];
235:     pose.legBack = [-0.25, 0.15];
236:     pose.headTilt = -0.08;
237:   }
238: 
239:   return pose;
240: }
