249: function buildSkeleton(char, pose) {
250:   const hip = { x: pose.hipX, y: pose.hipY };
251:   const chest = { x: hip.x + pose.lean * 20, y: hip.y - TORSO * 0.66 };
252:   const neck = { x: hip.x + pose.lean * TORSO, y: hip.y - NECK };
253:   const head = { x: neck.x + pose.lean * 11 + pose.headTilt * 8, y: neck.y - 16 };
254:   const shoulder = { x: neck.x, y: neck.y + 1 };
255: 
256:   const kneeF = pointFrom(hip, pose.legFront[0], THIGH);
257:   const footF = pointFrom(kneeF, pose.legFront[1], SHIN);
258:   const kneeB = pointFrom(hip, pose.legBack[0], THIGH);
259:   const footB = pointFrom(kneeB, pose.legBack[1], SHIN);
260: 
261:   const elbowF = pointFrom(shoulder, pose.armFront[0], UPPER_ARM);
262:   const handF = pointFrom(elbowF, pose.armFront[1], FOREARM);
263:   const elbowB = pointFrom(shoulder, pose.armBack[0], UPPER_ARM);
264:   const handB = pointFrom(elbowB, pose.armBack[1], FOREARM);
265: 
266:   return { hip, chest, neck, head, shoulder, kneeF, footF, kneeB, footB, elbowF, handF, elbowB, handB };
267: }
