280: function drawLimb(ctx, a, b, c, width, color, outline, alpha, jointColor) {
281:   ctx.globalAlpha = alpha;
282:   ctx.strokeStyle = outline;
283:   ctx.lineWidth = width + 4.5;
284:   ctx.beginPath();
