371:     ctx.save();
372:     ctx.globalCompositeOperation = 'lighter';
373:     ctx.strokeStyle = accent;
374:     ctx.lineWidth = 4;
375:     ctx.shadowColor = accent;
376:     ctx.shadowBlur = 14;
377:     ctx.beginPath();
378:     ctx.moveTo(joints.neck.x - 2, joints.neck.y + 7);
379:     ctx.quadraticCurveTo(-16 - speed * 12, joints.neck.y + 16 + wave * 0.4, -length, joints.neck.y + 24 + wave);
