import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: ['--no-sandbox', '--disable-gpu'],
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('console', (msg) => { if (msg.type() === 'error') errors.push(`console: ${msg.text()}`); });
page.on('pageerror', (err) => errors.push(`pageerror: ${err.message}`));
page.on('requestfailed', (req) => errors.push(`requestfailed: ${req.url()} ${req.failure()?.errorText}`));
page.on('response', (res) => { if (res.status() >= 400) errors.push(`http ${res.status()}: ${res.url()}`); });

await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.screenshot({ path: 'screenshots/menu-desktop.png' });
await page.click('#startBtn');
await page.waitForTimeout(1200);

const info = await page.evaluate(() => {
  const g = window.__neonFist;
  const p = g.player;
  return {
    state: g.state,
    playerX: p.x, playerY: p.y, groundY: g.groundY, unit: g.unit,
    enemies: g.enemies.map((e) => ({ id: e.id, type: e.type, heavy: e.heavy, x: e.x, y: e.y, hp: e.hp, state: e.state })),
    wave: g.wave,
    comboText: document.getElementById('comboCount').textContent,
    comboRank: document.getElementById('comboRank').textContent,
    comboShown: document.getElementById('comboDisplay').classList.contains('show'),
  };
});
console.log(JSON.stringify(info, null, 2));

// Place an enemy right in front of the player and land a light hit.
const comboResult = await page.evaluate(() => {
  const g = window.__neonFist;
  const p = g.player;
  const e = g.enemies[0];
  if (!e) return { error: 'no enemy' };
  e.x = p.x + 55 * g.unit;
  e.y = g.groundY;
  e.state = 'idle';
  e.stateTime = 0;
  p.facing = 1;
  p.startAttack('light');
  return { started: true, enemyHp: e.hp, enemyState: e.state, px: p.x };
});
await page.waitForTimeout(120);
const afterHit = await page.evaluate(() => {
  const g = window.__neonFist;
  const e = g.enemies[0];
  return {
    enemyHp: e?.hp, enemyState: e?.state, combo: g.player.combo,
    comboText: document.getElementById('comboCount').textContent,
    comboRank: document.getElementById('comboRank').textContent,
    comboShown: document.getElementById('comboDisplay').classList.contains('show'),
    attackState: g.player.state, attackTime: g.player.stateTime,
  };
});
console.log('afterHit', JSON.stringify(afterHit, null, 2));
await page.screenshot({ path: 'screenshots/action-light-new.png' });
console.log('errors', errors);
await browser.close();

