import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: ['--no-sandbox', '--disable-gpu'],
});
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('console', (msg) => { if (msg.type() === 'error') errors.push(`console: ${msg.text()}`); });
page.on('pageerror', (err) => errors.push(`pageerror: ${err.message}`));
page.on('requestfailed', (req) => errors.push(`requestfailed: ${req.url()} ${req.failure()?.errorText}`));
page.on('response', (res) => { if (res.status() >= 400) errors.push(`http ${res.status()}: ${res.url()}`); });

await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.click('#startBtn');
await page.waitForTimeout(650);

// freeze wave spawning noise
await page.evaluate(() => { const g = window.__neonFist; g.spawnTimer = 999; g.spawnQueue.length = 0; g.enemies.length = 0; });

// --- GRAB + THROW ---
const grabSetup = await page.evaluate(() => {
  const g = window.__neonFist;
  const p = g.player;
  g.spawnEnemy('red', 'red');
  const e = g.enemies[0];
  e.state = 'idle'; e.stateTime = 0; e.stateDuration = 0;
  e.x = p.x + 45 * g.unit; e.y = g.groundY; e.onGround = true; e.vx = 0;
  e.cooldown = 9;
  p.facing = 1; p.onGround = true; p.y = g.groundY; p.state = 'idle';
  return { grabbed: p.tryGrab(), playerState: p.state, enemyState: e.state, enemyX: e.x };
});
await page.waitForTimeout(120);
const held = await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player; const e = g.enemies[0];
  return { playerState: p.state, enemyState: e.state, enemyX: e.x, playerX: p.x, tied: !!p.grabTarget };
});
await page.screenshot({ path: 'screenshots/action-grab.png' });
const thrown = await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player; const e = g.enemies[0];
  p.throwGrab();
  return { playerState: p.state, enemyState: e.state, vx: e.vx, thrown: e.thrown };
});
await page.waitForTimeout(100);
await page.screenshot({ path: 'screenshots/action-throw.png' });
console.log('GRAB', { grabSetup, held, thrown });

// --- AERIAL GRAB + SUPLEX AoE ---
await page.waitForTimeout(900);
const suplexSetup = await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player;
  g.enemies.length = 0;
  g.spawnEnemy('red', 'red');
  g.spawnEnemy('red', 'red');
  const [a, b] = g.enemies;
  p.x = g.width * 0.5; p.y = g.groundY - 160 * g.unit; p.onGround = false; p.vx = 0; p.vy = 0; p.state = 'fall'; p.facing = 1;
  a.x = p.x + 30 * g.unit; a.y = p.y + 40 * g.unit; a.state = 'idle'; a.stateTime = 0; a.cooldown = 9;
  b.x = p.x + 120 * g.unit; b.y = g.groundY; b.state = 'idle'; b.stateTime = 0; b.cooldown = 9;
  return { grabbed: p.tryGrab(), playerState: p.state, target: a.state, targetId: a.id, bHp: b.hp };
});
await page.waitForTimeout(260);
await page.screenshot({ path: 'screenshots/action-suplex-air.png' });
await page.waitForTimeout(700);
const suplexDone = await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player;
  const [a, b] = g.enemies;
  return {
    playerState: p.state,
    targetHp: a?.hp, targetState: a?.state,
    splashHp: b?.hp, splashState: b?.state,
    playerY: p.y, groundY: g.groundY,
    combo: p.combo, banner: document.getElementById('bannerTitle').textContent,
  };
});
await page.screenshot({ path: 'screenshots/action-suplex-slam.png' });
console.log('SUPLEX', { suplexSetup, suplexDone });

// --- HEAVY ARMOR ---
await page.waitForTimeout(900);
const armorSetup = await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player;
  g.enemies.length = 0;
  g.spawnEnemy('heavy', 'gold');
  const e = g.enemies[0];
  e.y = g.groundY; e.onGround = true; e.state = 'idle'; e.stateTime = 0; e.stateDuration = 0; e.cooldown = 99;
  e.x = p.x + 70 * g.unit;
  p.x = g.width * 0.5; p.y = g.groundY; p.onGround = true; p.state = 'idle'; p.facing = 1; p.invuln = 99;
  p.startAttack('light');
  return { hp: e.hp, armored: e.armored, state: e.state };
});
await page.waitForTimeout(180);
const armorAfter = await page.evaluate(() => {
  const g = window.__neonFist; const e = g.enemies[0];
  return { hp: e.hp, state: e.state, shieldFlash: e.shieldFlash, tip: document.getElementById('contextTip').textContent };
});
await page.screenshot({ path: 'screenshots/action-armor.png' });
await page.waitForTimeout(450);
const armorBreak = await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player; const e = g.enemies[0];
  e.x = p.x + 40 * g.unit; e.y = g.groundY; e.state = 'idle'; e.stateTime = 0;
  p.state = 'idle'; p.stateTime = 0; p.facing = 1;
  p.startAttack('dragon');
  return { before: e.hp };
});
await page.waitForTimeout(220);
const armorBreakAfter = await page.evaluate(() => {
  const g = window.__neonFist; const e = g.enemies[0];
  return { hp: e.hp, state: e.state };
});
console.log('ARMOR', { armorSetup, armorAfter, armorBreak, armorBreakAfter });

console.log('errors', errors);
await browser.close();

