const page = await browser.newPage();
await page.goto('http://localhost:3002/');
const out = await page.evaluate(async () => {
  const names = ['game-desktop.png', 'action-spin.png', 'action-grab.png', 'check-b.png', 'action-dragon-new.png'];
  const res = {};
  for (const name of names) {
    const blob = await (await fetch('/screenshots/' + name)).blob();
    const bmp = await createImageBitmap(blob);
    const c = document.createElement('canvas'); c.width = bmp.width; c.height = bmp.height;
    const ctx = c.getContext('2d'); ctx.drawImage(bmp, 0, 0);
    const dat = ctx.getImageData(0, 0, bmp.width, bmp.height).data;
    const rows = [];
    for (let y = 0; y < bmp.height; y += 1) {
      let n = 0;
      for (let x = 0; x < bmp.width; x += 2) {
        const i = (y * bmp.width + x) * 4;
        const r = dat[i], g = dat[i + 1], b = dat[i + 2];
        if (g > 180 && b > 190 && r < 130) n += 1;
      }
      if (n > 100) rows.push([y, n]);
    }
    // group contiguous rows, report groups
    const groups = [];
    for (const [y, n] of rows) {
      const last = groups[groups.length - 1];
      if (last && y === last.end + 1) { last.end = y; last.n = Math.max(last.n, n); }
      else groups.push({ start: y, end: y, n });
    }
    res[name] = groups;
  }
  return res;
});
