        if (n > bmp.width * 0.12) rows.push(y);
      }
      res[name] = { size: [bmp.width, bmp.height], groundRows: rows.slice(0, 3).concat(rows.slice(-3)) };
    } catch (e) { res[name] = String(e); }
  }
  return res;
}, names);
console.log(JSON.stringify(out, null, 2));
await browser.close();
