import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.click('#startBtn');
await page.waitForTimeout(650);
await page.evaluate(() => { const g = window.__neonFist; g.spawnTimer = 999; g.spawnQueue.length = 0; g.enemies.length = 0; });

const insp = (label) => page.evaluate((label) => {
  const app = document.getElementById('app');
  const hud = document.getElementById('hud');
  const canvas = document.getElementById('game');
  const cr = canvas.getBoundingClientRect();
  return {
    label,
    appScroll: app.scrollTop, appScrollH: app.scrollHeight,
    hudY: hud.getBoundingClientRect().y,
    canvasRect: [cr.x, cr.y, cr.width, cr.height],
    canvasStyle: [canvas.style.width, canvas.style.height],
    docScroll: document.scrollingElement.scrollTop,
    state: window.__neonFist.state,
    groundY: window.__neonFist.groundY,
    inner: [innerWidth, innerHeight],
  };
}, label);
console.log(await insp('before grab'));

await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player;
  g.spawnEnemy('red', 'red');
  const e = g.enemies[0];
  e.state = 'idle'; e.stateTime = 0; e.stateDuration = 0; e.x = p.x + 45 * g.unit; e.y = g.groundY; e.onGround = true; e.vx = 0; e.cooldown = 9;
  p.facing = 1; p.onGround = true; p.y = g.groundY; p.state = 'idle';
  p.tryGrab();
});
await page.waitForTimeout(120);
console.log(await insp('after grab'));
await page.screenshot({ path: '/tmp/opencode/g1.png' });
console.log(await insp('after shot'));
await page.waitForTimeout(300);
console.log(await insp('after 300'));

// also log scroll of every element in case
const scrollers = await page.evaluate(() => {
  const out = [];
  document.querySelectorAll('*').forEach((el) => {
    if (el.scrollTop) out.push([el.tagName, el.id, el.className, el.scrollTop, el.scrollHeight, el.clientHeight]);
  });
  return out;
});
console.log('scrollers', scrollers);
await browser.close();

import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
const page = await context.newPage();
const errors = [];
page.on('console', (msg) => { if (msg.type() === 'error') errors.push(`console: ${msg.text()}`); });
page.on('pageerror', (err) => errors.push(`pageerror: ${err.message}`));
page.on('response', (res) => { if (res.status() >= 400) errors.push(`http ${res.status()}: ${res.url()}`); });

await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.screenshot({ path: 'screenshots/menu-mobile.png' });
await page.click('#startBtn');
await page.waitForTimeout(900);
await page.screenshot({ path: 'screenshots/game-mobile.png' });

const beforeDeath = await page.evaluate(() => {
  const g = window.__neonFist;
  return { state: g.state, deathCount: g.deathCount, rotateHint: !!document.getElementById('rotateHint'), hud: document.getElementById('hud').className, controls: document.getElementById('controls').className };
});

// First death should be standard.
await page.evaluate(() => {
  const g = window.__neonFist;
  g.deathCount = 0;
  g.player.die();
});
await page.waitForTimeout(1900);
const death1 = await page.evaluate(() => {
  const g = window.__neonFist;
  const offer = document.getElementById('reviveOffer');
  return {
    state: g.state, deathCount: g.deathCount, special: g.specialGameOver,
    reviveHidden: offer.classList.contains('hidden'),
    title: document.getElementById('goTitle').textContent,
    kicker: document.getElementById('goKicker').textContent,
    note: document.getElementById('goAdNote').textContent,
    noteHidden: document.getElementById('goAdNote').classList.contains('hidden'),
  };
});
await page.screenshot({ path: 'screenshots/gameover-standard-mobile.png' });

// Retry preserves death count, second death is special.
await page.click('#retryBtn');
await page.waitForTimeout(500);
await page.evaluate(() => { const g = window.__neonFist; g.player.die(); });
await page.waitForTimeout(1900);
const death2 = await page.evaluate(() => {
  const g = window.__neonFist;
  const offer = document.getElementById('reviveOffer');
  return {
    state: g.state, deathCount: g.deathCount, special: g.specialGameOver,
    reviveHidden: offer.classList.contains('hidden'),
    title: document.getElementById('goTitle').textContent,
    kicker: document.getElementById('goKicker').textContent,
    copy: document.getElementById('goCopy').textContent,
    deaths: document.getElementById('offerDeaths').textContent,
    noteHidden: document.getElementById('goAdNote').classList.contains('hidden'),
    offerRect: (() => { const r = offer.getBoundingClientRect(); return [r.x, r.y, r.width, r.height]; })(),
    panelRect: (() => { const r = document.querySelector('.gameover-panel').getBoundingClientRect(); return [r.x, r.y, r.width, r.height]; })(),
    viewport: [innerWidth, innerHeight],
  };
});
await page.screenshot({ path: 'screenshots/gameover-special-mobile.png' });

// Accept revive -> ad overlay
await page.click('#reviveBtn');
await page.waitForTimeout(350);
const ad = await page.evaluate(() => {
  const g = window.__neonFist;
  return {
    state: g.state, deathCount: g.deathCount, special: g.specialGameOver,
    adScreenHidden: document.getElementById('adScreen').classList.contains('hidden'),
    skipHidden: document.getElementById('adSkip').classList.contains('hidden'),
    claimHidden: document.getElementById('adClaim').classList.contains('hidden'),
    countdown: document.getElementById('adCountdown').textContent,
  };
});
await page.screenshot({ path: 'screenshots/ad-mobile.png' });
await page.waitForTimeout(5200);
const adDone = await page.evaluate(() => ({
  state: window.__neonFist.state,
  countdown: document.getElementById('adCountdown').textContent,
  skipHidden: document.getElementById('adSkip').classList.contains('hidden'),
  claimHidden: document.getElementById('adClaim').classList.contains('hidden'),
  progress: document.getElementById('adProgress').style.width,
}));
await page.screenshot({ path: 'screenshots/ad-claim-mobile.png' });
await page.click('#adClaim');
await page.waitForTimeout(500);
const revived = await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player;
  return {
    state: g.state, deathCount: g.deathCount, special: g.specialGameOver,
    hp: p.hp, maxHp: p.maxHp, battery: p.battery, invuln: p.invuln,
    hud: document.getElementById('hud').className, controls: document.getElementById('controls').className,
    banner: document.getElementById('bannerTitle').textContent,
  };
});
await page.screenshot({ path: 'screenshots/revived-mobile.png' });

// After revival, next death resets to standard because deathCount is 0
await page.evaluate(() => { window.__neonFist.player.die(); });
await page.waitForTimeout(1900);
const death3 = await page.evaluate(() => {
  const g = window.__neonFist;
  return { state: g.state, deathCount: g.deathCount, special: g.specialGameOver, reviveHidden: document.getElementById('reviveOffer').classList.contains('hidden') };
});

// Menu from standard game over keeps count 1, then dying again should be special
await page.click('#goMenuBtn');
await page.waitForTimeout(500);
const menuState = await page.evaluate(() => ({ state: window.__neonFist.state, deathCount: window.__neonFist.deathCount, special: window.__neonFist.specialGameOver }));
await page.click('#startBtn');
await page.waitForTimeout(500);
await page.evaluate(() => { window.__neonFist.player.die(); });
await page.waitForTimeout(1900);
const death4 = await page.evaluate(() => {
  const g = window.__neonFist;
  return { state: g.state, deathCount: g.deathCount, special: g.specialGameOver };
});

// Decline revive via menu should reset counter
await page.click('#goMenuBtn');
await page.waitForTimeout(400);
const afterDecline = await page.evaluate(() => ({ state: window.__neonFist.state, deathCount: window.__neonFist.deathCount, special: window.__neonFist.specialGameOver }));

console.log(JSON.stringify({ beforeDeath, death1, death2, ad, adDone, revived, death3, menuState, death4, afterDecline, errors }, null, 2));
await browser.close();

