import { createRequire } from 'node:module';
import { join } from 'node:path';
import { writeFileSync } from 'node:fs';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });
const page = await browser.newPage();
await page.goto('http://localhost:3002/');
const data = await page.evaluate(async () => {
  const blob = await (await fetch('/screenshots/game-mobile.png')).blob();
  const bmp = await createImageBitmap(blob);
  const sx = 100, sy = 900, sw = 400, sh = 360; // in 2x image pixels
  const c = document.createElement('canvas'); c.width = sw * 2; c.height = sh * 2;
  const ctx = c.getContext('2d'); ctx.imageSmoothingEnabled = false;
  ctx.drawImage(bmp, sx, sy, sw, sh, 0, 0, c.width, c.height);
  return c.toDataURL('image/png');
});
writeFileSync('/tmp/opencode/crop.png', Buffer.from(data.split(',')[1], 'base64'));
await browser.close();

