    this.facing = 1;
    this.scale = 1.06 * this.unit;
    this.maxHp = 100;
    this.hp = 100;
    this.battery = 0;
    this.onGround = true;
    this.state = 'idle';
    this.stateTime = 0;
    this.stateDuration = 0;
    this.animTime = 0;
    this.attackKind = null;
    this.attackChain = 0;
    this.chainTimer = 0;
    this.attackHitSet = new Set();
    this.attackLungeApplied = false;
    this.wallSide = null;
    this.wallTimer = 0;
    this.invuln = 0;
    this.flash = 0;
    this.alpha = 1;
    this.alive = true;
    this.grabTarget = null;
    this.grabTimer = 0;
    this.grabThrowReady = false;
    this.suplexTarget = null;
    this.suplexSlammed = false;
    this.specialWaveDone = false;
    this.specialHits = new Set();
    this.diveHits = new Set();
    this.diveBounces = 0;
    this.combo = 0;
    this.comboTimer = 0;
    this.bestCombo = 0;
    this.trailTimer = 0;
    this.landedFrom = 0;
    this.palette = PALETTE;
    this.charged = false;
    this.aura = true;
    this.auraScale = 1;
    this.seed = 7;
    this.radius = 16 * this.unit;
    this.lastState = 'idle';
    this.stunTimer = 0;
  }

  get moveSpeed() {
    return 355 * this.unit;
  }

  get airSpeed() {
    return 300 * this.unit;
  }

  get gravity() {
    return 2180 * this.unit;
  }

  get height() {
    return 140 * this.scale;
  }

  setState(name, duration = 0) {
    this.lastState = this.state;
    this.state = name;
    this.stateTime = 0;
    this.stateDuration = duration;
  }

  addBattery(amount) {
    if (amount <= 0) return;
    const wasCharged = this.battery >= 100;
    this.battery = clamp(this.battery + amount, 0, 100);
    this.charged = this.battery >= 100;
    if (!wasCharged && this.charged) {
      this.game.audio.charged?.();
      this.game.ui.flashBattery();
      this.game.fx.ring(this.x, this.y - 68 * this.unit, {
        color: '#ffd34d',
        maxRadius: 82 * this.unit,
        life: 0.5,
        width: 2.5,
        squash: 0.45,
      });
      this.game.fx.text(this.x, this.y - 160 * this.unit, 'BATERÍA AL 100%', {
        color: '#ffd34d',
        size: 13,
        life: 1.1,
        vy: -35,
      });
    }
  }

  heal(amount) {
    this.hp = clamp(this.hp + amount, 0, this.maxHp);
  }

  comboHit(kind = 'light') {
    this.combo += 1;
    this.comboTimer = 1.7;
    this.bestCombo = Math.max(this.bestCombo, this.combo);
    this.game.ui.comboHit(this.combo, 1);
    this.game.audio.combo(this.combo - 1);
  }

  resetPosition(x) {
    this.x = x;
    this.y = this.game.groundY;
    this.vx = 0;
    this.vy = 0;
    this.onGround = true;
    this.state = 'idle';
    this.stateTime = 0;
    this.stateDuration = 0;
    this.grabTarget = null;
    this.suplexTarget = null;
    this.wallSide = null;
    this.invuln = 2;
  }

  revive() {
    this.alive = true;
    this.hp = Math.max(1, Math.round(this.maxHp * 0.5));
    this.battery = Math.max(this.battery, 35);
    this.charged = this.battery >= 100;
    this.y = this.game.groundY;
    this.vx = 0;
    this.vy = 0;
    this.onGround = true;
    this.state = 'idle';
    this.stateTime = 0;
    this.stateDuration = 0;
    this.invuln = 2.5;
    this.alpha = 1;
    this.flash = 0;
    this.grabTarget = null;
    this.suplexTarget = null;
    this.combo = 0;
    this.comboTimer = 0;
  }

  update(dt, input) {
    if (!this.alive) {
      this.updateDead(dt);
      return;
    }

    this.animTime += dt;
    this.stateTime += dt;
    if (this.state === 'spin' && this.stateDuration > 0) {
      this.spinAngle = (this.stateTime / this.stateDuration) * TAU;
    }
    this.invuln = Math.max(0, this.invuln - dt);
    this.flash = Math.max(0, this.flash - dt);
    this.chainTimer = Math.max(0, this.chainTimer - dt);
    this.comboTimer = Math.max(0, this.comboTimer - dt);
    this.auraScale = 1 + (this.charged ? Math.sin(this.animTime * 5) * 0.08 : 0);
    if (this.comboTimer <= 0 && this.combo > 0) {
      this.combo = 0;
      this.game.ui.setCombo(0, 0);
    }

