    if (!html) {
      this.el.contextTip.classList.remove('show');
      this.contextTimer = 0;
      this.contextText = '';
      return;
    }
    if (this.contextText !== html) {
      this.contextText = html;
      this.el.contextTip.innerHTML = html;
    }
    this.el.contextTip.classList.add('show');
    this.contextTimer = duration;
  }

