      if (this.vx < -160 && !this.onGround) this.game.scene.pulseWall('left', 0.5);
      this.vx = 0;
      if (this.onGround && state !== 'wall' && !locked && input.move < 0) this.enterWall('left');
    } else if (this.x > maxX) {
