import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });

const sizes = [
  [1440, 900], [1280, 720], [1024, 768], [820, 1180], [761, 900], [760, 900],
  [390, 844], [375, 667], [360, 640], [320, 568], [844, 390], [667, 375],
];

const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.click('#startBtn');
await page.waitForTimeout(500);

const results = [];
for (const [width, height] of sizes) {
  await page.setViewportSize({ width, height });
  await page.waitForTimeout(160);
  results.push(await page.evaluate(({ width, height }) => {
    const rect = (sel) => {
      const el = document.querySelector(sel);
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return { x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1), right: +r.right.toFixed(1), bottom: +r.bottom.toFixed(1) };
    };
    const dpad = rect('.dpad');
    const cluster = rect('.action-cluster');
    const card = rect('.fighter-card');
    const stats = rect('.run-stats');
    const actions = rect('.hud-actions');
    const r0 = document.getElementById('app').getBoundingClientRect();
    return {
      size: `${width}x${height}`,
      dpad, cluster, card, stats, actions,
      gap: +(cluster.x - (dpad.x + dpad.w)).toFixed(1),
      hudOverlap: !!(card && actions && card.right > actions.x),
      statsBelowCard: !!(stats && card && stats.y >= card.bottom - 1),
      outOfBounds: [dpad, cluster, card, stats, actions].some((r) => r && (r.x < -1 || r.right > width + 1 || r.y < -1 || r.bottom > height + 1)),
      appScrollH: document.getElementById('app').scrollHeight,
      appClientH: document.getElementById('app').clientHeight,
      menuLabel: document.querySelector('.stat-label')?.textContent,
      groundY: window.__neonFist.groundY,
      unit: window.__neonFist.unit,
    };
  }, { width, height }));
}
console.log(JSON.stringify(results, null, 2));
await browser.close();

