import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });
const errors = [];
function watch(page) {
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(`console: ${msg.text()}`); });
  page.on('pageerror', (err) => errors.push(`pageerror: ${err.message}`));
  page.on('requestfailed', (req) => errors.push(`requestfailed: ${req.url()} ${req.failure()?.errorText}`));
  page.on('response', (res) => { if (res.status() >= 400) errors.push(`http ${res.status()}: ${res.url()}`); });
}

const desktop = await browser.newPage({ viewport: { width: 1440, height: 900 } });
watch(desktop);
await desktop.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await desktop.screenshot({ path: 'screenshots/menu-desktop.png' });
await desktop.click('#howBtn');
await desktop.waitForTimeout(350);
const howDesktop = await desktop.evaluate(() => {
  const r = document.querySelector('.sheet').getBoundingClientRect();
  const s = document.querySelector('.sheet').scrollHeight;
  return { rect: [r.x, r.y, r.width, r.height], scrollHeight: s, clientHeight: document.querySelector('.sheet').clientHeight, viewport: [innerWidth, innerHeight] };
});
await desktop.screenshot({ path: 'screenshots/how-desktop.png' });
await desktop.click('#howClose');
await desktop.click('#startBtn');
await desktop.waitForTimeout(900);
await desktop.screenshot({ path: 'screenshots/game-desktop.png' });
await desktop.click('#pauseBtn');
await desktop.waitForTimeout(250);
const pauseDesktop = await desktop.evaluate(() => {
  const r = document.querySelector('.pause-panel').getBoundingClientRect();
  return { rect: [r.x, r.y, r.width, r.height], state: window.__neonFist.state, wave: document.getElementById('pauseWave').textContent, kills: document.getElementById('pauseKills').textContent };
});
await desktop.screenshot({ path: 'screenshots/pause-desktop.png' });
await desktop.click('#resumeBtn');
await desktop.waitForTimeout(250);

// Grab setup, desktop.
await desktop.evaluate(() => {
  const g = window.__neonFist;
  g.spawnTimer = 999; g.spawnQueue.length = 0; g.enemies.length = 0;
  const p = g.player;
  p.x = g.width * 0.5; p.y = g.groundY; p.onGround = true; p.state = 'idle'; p.facing = 1; p.invuln = 99;
  g.spawnEnemy('red', 'red');
  const e = g.enemies[0];
  e.x = p.x + 45 * g.unit; e.y = g.groundY; e.onGround = true; e.state = 'idle'; e.stateTime = 0; e.cooldown = 99;
  p.tryGrab();
});
await desktop.waitForTimeout(160);
await desktop.screenshot({ path: 'screenshots/action-grab.png' });
const grabDesktop = await desktop.evaluate(() => {
  const g = window.__neonFist; const p = g.player; const e = g.enemies[0];
  return { player: p.state, enemy: e?.state, held: !!p.grabTarget };
});
// Release without throwing to keep the overlay out of later shots.
await desktop.evaluate(() => window.__neonFist.player.releaseGrab());

// Resize while playing: canvas must follow the viewport.
const beforeResize = await desktop.evaluate(() => ({ w: window.__neonFist.width, h: window.__neonFist.height, unit: window.__neonFist.unit, ground: window.__neonFist.groundY, canvas: document.getElementById('game').style.width }));
await desktop.setViewportSize({ width: 390, height: 844 });
await desktop.waitForTimeout(300);
const afterResize = await desktop.evaluate(() => ({ w: window.__neonFist.width, h: window.__neonFist.height, unit: window.__neonFist.unit, ground: window.__neonFist.groundY, canvas: document.getElementById('game').style.width, inner: [innerWidth, innerHeight] }));
await desktop.setViewportSize({ width: 1440, height: 900 });
await desktop.waitForTimeout(300);

const mobileContext = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
const mobile = await mobileContext.newPage();
watch(mobile);
await mobile.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await mobile.screenshot({ path: 'screenshots/menu-mobile.png' });
await mobile.click('#howBtn');
await mobile.waitForTimeout(350);
const howMobile = await mobile.evaluate(() => {
  const sheet = document.querySelector('.sheet');
  const r = sheet.getBoundingClientRect();
  return { rect: [r.x, r.y, r.width, r.height], scrollHeight: sheet.scrollHeight, clientHeight: sheet.clientHeight, viewport: [innerWidth, innerHeight] };
});
await mobile.screenshot({ path: 'screenshots/how-mobile.png' });
await mobile.click('#howClose');
await mobile.click('#startBtn');
await mobile.waitForTimeout(900);
await mobile.screenshot({ path: 'screenshots/game-mobile.png' });

// Touch: hold right, release, then tap light attack.
const touchBefore = await mobile.evaluate(() => {
  const g = window.__neonFist;
  g.spawnTimer = 999; g.spawnQueue.length = 0; g.enemies.length = 0;
  const p = g.player;
  p.x = g.width * 0.5; p.y = g.groundY; p.onGround = true; p.state = 'idle'; p.facing = 1; p.invuln = 99;
  g.spawnEnemy('red', 'red');
  const e = g.enemies[0];
  e.x = p.x + 74 * g.unit; e.y = g.groundY; e.onGround = true; e.state = 'idle'; e.stateTime = 0; e.cooldown = 99;
  return { x: p.x, enemyHp: e.hp, state: p.state };
});
const right = mobile.locator('.pad-right');
await right.dispatchEvent('pointerdown', { pointerId: 11, pointerType: 'touch', isPrimary: true, bubbles: true, cancelable: true });
await mobile.waitForTimeout(300);
const touchHeld = await mobile.evaluate(() => ({ x: window.__neonFist.player.x, state: window.__neonFist.player.state, move: window.__neonFist.input.move }));
await right.dispatchEvent('pointerup', { pointerId: 11, pointerType: 'touch', isPrimary: true, bubbles: true, cancelable: true });
await mobile.waitForTimeout(80);
const light = mobile.locator('.action-light');
await light.dispatchEvent('pointerdown', { pointerId: 12, pointerType: 'touch', isPrimary: true, bubbles: true, cancelable: true });
await mobile.waitForTimeout(120);
await light.dispatchEvent('pointerup', { pointerId: 12, pointerType: 'touch', isPrimary: true, bubbles: true, cancelable: true });
await mobile.waitForTimeout(130);
const touchAfter = await mobile.evaluate(() => {
  const g = window.__neonFist; const p = g.player; const e = g.enemies[0];
  return { x: p.x, state: p.state, enemyHp: e?.hp, enemyState: e?.state, combo: p.combo };
});
await mobile.screenshot({ path: 'screenshots/action-touch-mobile.png' });

// Aerial special for the final mobile action shot.
await mobile.waitForTimeout(950);
await mobile.evaluate(() => {
  const g = window.__neonFist; const p = g.player;
  g.enemies.length = 0;
  for (let i = 0; i < 3; i += 1) {
    g.spawnEnemy('red', 'red');
    const e = g.enemies[g.enemies.length - 1];
    e.x = p.x + (i - 1) * 80 * g.unit; e.y = g.groundY; e.onGround = true; e.state = 'idle'; e.stateTime = 0; e.cooldown = 99;
  }
  p.x = g.width * 0.5; p.y = g.groundY; p.onGround = true; p.state = 'idle'; p.facing = 1; p.battery = 100; p.charged = true;
  p.startSpecial();
});
await mobile.waitForTimeout(720);
const mobileSpecial = await mobile.evaluate(() => {
  const g = window.__neonFist; const p = g.player;
  return { state: p.state, battery: p.battery, timeScale: +g.timeScale.toFixed(2), hp: g.enemies.map((e) => e.hp), states: g.enemies.map((e) => e.state) };
});
await mobile.screenshot({ path: 'screenshots/action-special-mobile.png' });

// Pause overlay after the action settles.
await mobile.waitForTimeout(1600);
await mobile.click('#pauseBtn');
await mobile.waitForTimeout(250);
const pauseMobile = await mobile.evaluate(() => {
  const r = document.querySelector('.pause-panel').getBoundingClientRect();
  return { rect: [r.x, r.y, r.width, r.height], state: window.__neonFist.state, viewport: [innerWidth, innerHeight] };
});
await mobile.screenshot({ path: 'screenshots/pause-mobile.png' });
await mobile.click('#resumeBtn');

// Small-phone layout.
const smallContext = await browser.newContext({ viewport: { width: 320, height: 568 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
const small = await smallContext.newPage();
watch(small);
await small.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await small.click('#startBtn');
await small.waitForTimeout(700);
const smallLayout = await small.evaluate(() => {
  const d = document.querySelector('.dpad').getBoundingClientRect();
  const c = document.querySelector('.action-cluster').getBoundingClientRect();
  const card = document.querySelector('.fighter-card').getBoundingClientRect();
  const stats = document.querySelector('.run-stats').getBoundingClientRect();
  return {
    dpad: [d.x, d.right], cluster: [c.x, c.right], gap: c.x - d.right,
    card: [card.x, card.right], stats: [stats.x, stats.right],
    viewport: [innerWidth, innerHeight], canvas: [window.__neonFist.width, window.__neonFist.height],
    out: c.right > innerWidth || d.x < 0 || card.right > innerWidth || stats.right > innerWidth,
  };
});
await small.screenshot({ path: 'screenshots/game-320-mobile.png' });

// Landscape layout.
const landscapeContext = await browser.newContext({ viewport: { width: 844, height: 390 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
const landscape = await landscapeContext.newPage();
watch(landscape);
await landscape.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await landscape.screenshot({ path: 'screenshots/menu-landscape.png' });
await landscape.click('#startBtn');
await landscape.waitForTimeout(700);
const landscapeLayout = await landscape.evaluate(() => {
  const d = document.querySelector('.dpad').getBoundingClientRect();
  const c = document.querySelector('.action-cluster').getBoundingClientRect();
  return { dpad: [d.x, d.right], cluster: [c.x, c.right], gap: c.x - d.right, viewport: [innerWidth, innerHeight], canvas: [window.__neonFist.width, window.__neonFist.height] };
});
await landscape.screenshot({ path: 'screenshots/game-landscape.png' });

const hud = await mobile.evaluate(() => ({
  labels: [...document.querySelectorAll('.stat-label')].map((e) => e.textContent),
  values: [document.getElementById('waveValue').textContent, document.getElementById('killValue').textContent],
  card: (() => { const r = document.querySelector('.fighter-card').getBoundingClientRect(); return [r.x, r.y, r.width, r.height]; })(),
  stats: (() => { const r = document.querySelector('.run-stats').getBoundingClientRect(); return [r.x, r.y, r.width, r.height]; })(),
}));

console.log(JSON.stringify({ howDesktop, pauseDesktop, grabDesktop, beforeResize, afterResize, touchBefore, touchHeld, touchAfter, mobileSpecial, pauseMobile, howMobile, smallLayout, landscapeLayout, hud, errors }, null, 2));
await browser.close();

