import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });
const context = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, isMobile: true, hasTouch: true });
const page = await context.newPage();
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push(e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'networkidle' });
await page.click('#startBtn');
await page.waitForTimeout(500);
const setup = await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player;
  g.spawnTimer = 999; g.spawnQueue.length = 0; g.enemies.length = 0;
  p.x = g.width * 0.5; p.y = g.groundY; p.onGround = true; p.state = 'idle'; p.facing = 1; p.invuln = 99;
  g.spawnEnemy('red', 'red');
  const e = g.enemies[0];
  e.x = p.x + 62 * g.unit; e.y = g.groundY; e.onGround = true; e.state = 'idle'; e.stateTime = 0; e.cooldown = 99;
  return { p: p.x, e: e.x, hp: e.hp };
});
const tap = async (sel, id) => {
  const l = page.locator(sel);
  await l.dispatchEvent('pointerdown', { pointerId: id, pointerType: 'touch', isPrimary: true, bubbles: true, cancelable: true });
  await page.waitForTimeout(60);
  await l.dispatchEvent('pointerup', { pointerId: id, pointerType: 'touch', isPrimary: true, bubbles: true, cancelable: true });
};
await tap('.action-light', 21);
await page.waitForTimeout(170);
const light = await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player; const e = g.enemies[0];
  return { state: p.state, attackKind: p.attackKind, enemyHp: e?.hp, enemyState: e?.state, battery: p.battery, combo: p.combo };
});
await page.waitForTimeout(700);
const jumpSetup = await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player;
  p.x = g.width * 0.5; p.y = g.groundY; p.onGround = true; p.state = 'idle'; p.vx = 0; p.vy = 0;
  return { y: p.y, onGround: p.onGround };
});
await tap('.action-jump', 22);
await page.waitForTimeout(150);
const jump = await page.evaluate(() => { const p = window.__neonFist.player; return { y: p.y, vy: p.vy, state: p.state, onGround: p.onGround }; });
await page.waitForTimeout(1000);
const grabSetup = await page.evaluate(() => {
  const g = window.__neonFist; const p = g.player;
  g.enemies.length = 0;
  p.x = g.width * 0.5; p.y = g.groundY; p.onGround = true; p.state = 'idle'; p.vx = 0; p.vy = 0; p.facing = 1;
  g.spawnEnemy('red', 'red');
  const e = g.enemies[0];
  e.x = p.x + 46 * g.unit; e.y = g.groundY; e.onGround = true; e.state = 'idle'; e.stateTime = 0; e.cooldown = 99;
  return { p: p.x, e: e.x };
});
await tap('.action-grab', 23);
await page.waitForTimeout(100);
const grab = await page.evaluate(() => { const g = window.__neonFist; return { state: g.player.state, enemy: g.enemies[0]?.state, held: !!g.player.grabTarget }; });
console.log(JSON.stringify({ setup, light, jumpSetup, jump, grabSetup, grab, errors }, null, 2));
await browser.close();
EOF
